Here's a reusable `UserCard` component with an avatar, name, and follow button. It includes optimistic updates, a loading state, an initials fallback when there's no image, and accessibility attributes.

## UserCard.tsx

```tsx
import { useState } from "react";
import "./UserCard.css";

export interface User {
  id: string;
  name: string;
  username?: string;
  avatarUrl?: string;
}

interface UserCardProps {
  user: User;
  initialFollowing?: boolean;
  /** Called when the follow state changes. Return a promise to handle async requests. */
  onFollowChange?: (userId: string, following: boolean) => Promise<void> | void;
}

function getInitials(name: string): string {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0].toUpperCase())
    .join("");
}

export default function UserCard({
  user,
  initialFollowing = false,
  onFollowChange,
}: UserCardProps) {
  const [isFollowing, setIsFollowing] = useState(initialFollowing);
  const [isLoading, setIsLoading] = useState(false);
  const [imageError, setImageError] = useState(false);
  const [isHovering, setIsHovering] = useState(false);

  const handleFollowClick = async () => {
    const nextState = !isFollowing;

    // Optimistic update
    setIsFollowing(nextState);
    setIsLoading(true);

    try {
      await onFollowChange?.(user.id, nextState);
    } catch (error) {
      // Roll back on failure
      setIsFollowing(!nextState);
      console.error("Failed to update follow status:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const showImage = user.avatarUrl && !imageError;

  let buttonLabel = isFollowing ? "Following" : "Follow";
  if (isFollowing && isHovering && !isLoading) buttonLabel = "Unfollow";

  return (
    <div className="user-card">
      <div className="user-card__avatar">
        {showImage ? (
          <img
            src={user.avatarUrl}
            alt={`${user.name}'s avatar`}
            onError={() => setImageError(true)}
          />
        ) : (
          <span className="user-card__initials" aria-hidden="true">
            {getInitials(user.name)}
          </span>
        )}
      </div>

      <div className="user-card__info">
        <span className="user-card__name">{user.name}</span>
        {user.username && (
          <span className="user-card__username">@{user.username}</span>
        )}
      </div>

      <button
        type="button"
        className={`user-card__button ${
          isFollowing ? "user-card__button--following" : ""
        }`}
        onClick={handleFollowClick}
        onMouseEnter={() => setIsHovering(true)}
        onMouseLeave={() => setIsHovering(false)}
        disabled={isLoading}
        aria-pressed={isFollowing}
        aria-label={`${isFollowing ? "Unfollow" : "Follow"} ${user.name}`}
      >
        {buttonLabel}
      </button>
    </div>
  );
}
```

