Here's a reusable `UserCard` component with an avatar, name, and a follow button. It includes optimistic updates, a loading state, an initials fallback when there's no image, and accessibility attributes.

## UserCard.tsx

```tsx
import { useState } from "react";
import "./UserCard.css";

export interface User {
  id: string;
  name: string;
  username?: string;
  avatarUrl?: string;
}

interface UserCardProps {
  user: User;
  initiallyFollowing?: boolean;
  /** Called when the follow state changes. Should return a Promise for async APIs. */
  onFollowChange?: (userId: string, following: boolean) => Promise<void> | void;
}

function getInitials(name: string): string {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0].toUpperCase())
    .join("");
}

export default function UserCard({
  user,
  initiallyFollowing = false,
  onFollowChange,
}: UserCardProps) {
  const [isFollowing, setIsFollowing] = useState(initiallyFollowing);
  const [isLoading, setIsLoading] = useState(false);
  const [imgError, setImgError] = useState(false);
  const [isHovering, setIsHovering] = useState(false);

  const handleClick = async () => {
    const next = !isFollowing;
    setIsFollowing(next); // optimistic update
    setIsLoading(true);

    try {
      await onFollowChange?.(user.id, next);
    } catch (err) {
      setIsFollowing(!next); // roll back on failure
      console.error("Failed to update follow status:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const showImage = user.avatarUrl && !imgError;

  let buttonLabel = "Follow";
  if (isFollowing) buttonLabel = isHovering ? "Unfollow" : "Following";

  return (
    <div className="user-card">
      <div className="user-card__avatar" aria-hidden={!showImage}>
        {showImage ? (
          <img
            src={user.avatarUrl}
            alt={`${user.name}'s avatar`}
            onError={() => setImgError(true)}
          />
        ) : (
          <span className="user-card__initials">{getInitials(user.name)}</span>
        )}
      </div>

      <div className="user-card__info">
        <span className="user-card__name">{user.name}</span>
        {user.username && (
          <span className="user-card__username">@{user.username}</span>
        )}
      </div>

      <button
        type="button"
        className={`user-card__button ${
          isFollowing ? "user-card__button--following" : ""
        }`}
        onClick={handleClick}
        onMouseEnter={() => setIsHovering(true)}
        onMouseLeave={() => setIsHovering(false)}
        disabled={isLoading}
        aria-pressed={isFollowing}
        aria-label={`${isFollowing ? "Unfollow" : "Follow"} ${user.name}`}
      >
        {buttonLabel}
      </button>
    </div>
  );
}
