```typescript
// format.ts

export type DateInput = Date | string | number;

const DEFAULT_LOCALE = "en-US";
const DEFAULT_CURRENCY = "USD";

// Cache formatters — constructing Intl objects is relatively expensive.
const formatterCache = new Map<string, Intl.NumberFormat | Intl.DateTimeFormat>();

function getNumberFormatter(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `num|${locale}|${JSON.stringify(options)}`;
  let fmt = formatterCache.get(key) as Intl.NumberFormat | undefined;
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, options);
    formatterCache.set(key, fmt);
  }
  return fmt;
}

function getDateFormatter(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `date|${locale}|${JSON.stringify(options)}`;
  let fmt = formatterCache.get(key) as Intl.DateTimeFormat | undefined;
  if (!fmt) {
    fmt = new Intl.DateTimeFormat(locale, options);
    formatterCache.set(key, fmt);
  }
  return fmt;
}

/** Converts a Date, ISO string, or timestamp into a valid Date. Throws on invalid input. */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? new Date(input.getTime()) : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}

// ---------------------------------------------------------------------------
// Prices
// ---------------------------------------------------------------------------

export interface PriceOptions {
  currency?: string;   // ISO 4217 code, e.g. "USD", "EUR", "JPY"
  locale?: string;     // BCP 47 tag, e.g. "en-US", "de-DE"
  fromCents?: boolean; // treat the amount as minor units (e.g. cents)
  compact?: boolean;   // "$1.2K" style output
}

/**
 * Formats a number as a currency string.
 *
 * formatPrice(1234.5)                          // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * formatPrice(199, { fromCents: true })        // "$1.99"
 * formatPrice(1_250_000, { compact: true })    // "$1.3M"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    currency = DEFAULT_CURRENCY,
    locale = DEFAULT_LOCALE,
    fromCents = false,
    compact = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid amount: ${amount}`);
  }

  const formatter = getNumberFormatter(locale, {
    style: "currency",
    currency,
    ...(compact && { notation: "compact", maximumFractionDigits: 1 }),
  });

  // Respect the currency's real minor-unit count (e.g. JPY has 0, KWD has 3).
  const value = fromCents
    ? amount / 10 ** (formatter.resolvedOptions().maximumFractionDigits ?? 2)
    : amount;

  return formatter.format(value);
}

/**
 * Formats a price range, collapsing to a single price when min === max.
 *
 * formatPriceRange(10, 25) // "$10.00 – $25.00"
 */
export function formatPriceRange(min: number, max: number, options: PriceOptions = {}): string {
  if (min === max) return formatPrice(min, options);
  return `${formatPrice(min, options)} – ${formatPrice(max, options)}`;
}

/**
 * Formats a discount as a percentage.
 *
 * formatDiscount(100, 75) // "-25%"
 */
export function formatDiscount(
  originalPrice: number,
  salePrice: number,
  locale: string = DEFAULT_LOCALE
): string {
  if (originalPrice <= 0) {
    throw new RangeError("Original price must be greater than zero");
  }
  const ratio = (salePrice - originalPrice) / originalPrice;
  return getNumberFormatter(locale, {
    style: "percent",
    maximumFractionDigits: 0,
    signDisplay: "exceptZero",
  }).format(ratio);
}

// ---------------------------------------------------------------------------
// Dates
// ---------------------------------------------------------------------------

export type DateStyle = "short" | "medium" | "long" | "full";

/**
 * Formats a date using a preset style.
 *
 * formatDate("2024-03-15")          // "Mar 15, 2024"
 * formatDate(new Date(), "long")    // "March 15, 2024"
 * formatDate(Date.now(), "short")   // "3/15/24"
 */
export function formatDate(
  input: DateInput,
  style: DateStyle = "medium",
  locale: string = DEFAULT_LOCALE
): string {
  return getDateFormatter(locale, { dateStyle: style }).format(toDate(input));
}

/**
 * Formats a date with time.
 *
 * formatDateTime("2024-03-15T14:30:00") // "Mar 15, 2024, 2:30 PM"
 */
export function formatDateTime(
  input: DateInput,
  style: DateStyle = "medium",
  locale: string = DEFAULT_LOCALE,
  timeZone?: string
): string {
  return getDateFormatter(locale, {
    dateStyle: style,
    timeStyle: "short",
    ...(timeZone && { timeZone }),
  }).format(toDate(input));
}

/**
 * Returns an ISO date string (YYYY-MM-DD) in local time — handy for
 * <input type="date"> values. Avoids the UTC shift of toISOString().
 */
export function toISODateString(input: DateInput): string {
  const d = toDate(input);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 60 * 60 * 24 * 365],
  ["month", 60 * 60 * 24 * 30],
  ["week", 60 * 60 * 24 * 7],
  ["day", 60 * 60 * 24],
  ["hour", 60 * 60],
  ["minute", 60],
  ["second", 1],
];

/**
 * Formats a date relative to now (or a given reference date).
 *
 * formatRelativeTime(Date.now() - 5 * 60_000) // "5 minutes ago"
 * formatRelativeTime(Date.now() + 86_400_000) // "tomorrow"
 */
export function formatRelativeTime(
  input: DateInput,
  locale: string = DEFAULT_LOCALE,
  now: DateInput = Date.now()
): string {
  const diffSeconds = (toDate(input).getTime() - toDate(now).getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, secondsInUnit] of RELATIVE_UNITS) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return rtf.format(0, "second"); // unreachable, satisfies the compiler
}
```

