```typescript
// format.ts

/** Input types accepted by the date helpers. */
export type DateInput = Date | string | number;

/**
 * Normalizes a DateInput into a valid Date object.
 * @throws {RangeError} if the input cannot be parsed into a valid date.
 */
function toDate(input: DateInput): Date {
  const date = input instanceof Date ? new Date(input.getTime()) : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date input: ${String(input)}`);
  }
  return date;
}

// ---------------------------------------------------------------------------
// Price formatting
// ---------------------------------------------------------------------------

export interface PriceOptions {
  /** ISO 4217 currency code. Default: "USD" */
  currency?: string;
  /** BCP 47 locale. Default: "en-US" */
  locale?: string;
  /** Omit decimals when the amount is a whole number (e.g. "$10" instead of "$10.00"). Default: false */
  hideZeroCents?: boolean;
  /** Use compact notation (e.g. "$1.2K"). Default: false */
  compact?: boolean;
}

/**
 * Formats a numeric amount as a localized currency string.
 *
 * @example
 * formatPrice(1234.5)                              // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * formatPrice(10, { hideZeroCents: true })         // "$10"
 * formatPrice(1_250_000, { compact: true })        // "$1.3M"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    currency = "USD",
    locale = "en-US",
    hideZeroCents = false,
    compact = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid price amount: ${amount}`);
  }

  const formatOptions: Intl.NumberFormatOptions = {
    style: "currency",
    currency,
  };

  if (compact) {
    formatOptions.notation = "compact";
    formatOptions.maximumFractionDigits = 1;
  } else if (hideZeroCents && Number.isInteger(amount)) {
    formatOptions.minimumFractionDigits = 0;
    formatOptions.maximumFractionDigits = 0;
  }

  return new Intl.NumberFormat(locale, formatOptions).format(amount);
}

/**
 * Formats an amount given in minor units (e.g. cents), which is how
 * many payment APIs (Stripe, etc.) represent money to avoid float errors.
 *
 * Assumes 2 decimal places; pass `fractionDigits` for currencies like JPY (0) or KWD (3).
 *
 * @example
 * formatPriceFromCents(199900)          // "$1,999.00"
 * formatPriceFromCents(500, { currency: "JPY" }, 0) // "¥500"
 */
export function formatPriceFromCents(
  cents: number,
  options: PriceOptions = {},
  fractionDigits = 2
): string {
  if (!Number.isInteger(cents)) {
    throw new RangeError(`Minor-unit amount must be an integer: ${cents}`);
  }
  return formatPrice(cents / 10 ** fractionDigits, options);
}

// ---------------------------------------------------------------------------
// Date formatting
// ---------------------------------------------------------------------------

export type DateStyle = "short" | "medium" | "long" | "full";

export interface DateOptions {
  /** BCP 47 locale. Default: "en-US" */
  locale?: string;
  /** Preset style. Default: "medium" */
  style?: DateStyle;
  /** Include the time of day. Default: false */
  includeTime?: boolean;
  /** IANA time zone, e.g. "UTC" or "America/New_York". Default: runtime local zone */
  timeZone?: string;
}

/**
 * Formats a date using a localized preset style.
 *
 * @example
 * formatDate("2024-03-15T14:30:00Z")                      // "Mar 15, 2024"
 * formatDate(new Date(), { style: "long" })               // "March 15, 2024"
 * formatDate(Date.now(), { includeTime: true })           // "Mar 15, 2024, 2:30 PM"
 */
export function formatDate(input: DateInput, options: DateOptions = {}): string {
  const { locale = "en-US", style = "medium", includeTime = false, timeZone } = options;

  return new Intl.DateTimeFormat(locale, {
    dateStyle: style,
    ...(includeTime && { timeStyle: "short" }),
    ...(timeZone && { timeZone }),
  }).format(toDate(input));
}

/**
 * Returns an ISO 8601 calendar date string (YYYY-MM-DD) in UTC.
 * Useful for APIs, form inputs, and sortable keys.
 *
 * @example
 * formatISODate(new Date("2024-03-15T23:00:00Z")) // "2024-03-15"
 */
export function formatISODate(input: DateInput): string {
  return toDate(input).toISOString().slice(0, 10);
}

const RELATIVE_UNITS: Array<[Intl.RelativeTimeFormatUnit, number]> = [
  ["year", 60 * 60 * 24 * 365],
  ["month", 60 * 60 * 24 * 30],
  ["week", 60 * 60 * 24 * 7],
  ["day", 60 * 60 * 24],
  ["hour", 60 * 60],
  ["minute", 60],
  ["second", 1],
];

/**
 * Formats a date relative to now (or a supplied reference date).
 *
 * @example
 * formatRelativeTime(Date.now() - 5 * 60_000)         // "5 minutes ago"
 * formatRelativeTime(Date.now() + 2 * 86_400_000)     // "in 2 days"
 * formatRelativeTime(Date.now() - 86_400_000)         // "yesterday"
 */
export function formatRelativeTime(
  input: DateInput,
  options: { locale?: string; now?: DateInput } = {}
): string {
  const { locale = "en-US", now = Date.now() } = options;
  const diffSeconds = (toDate(input).getTime() - toDate(now).getTime()) / 1000;

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, secondsInUnit] of RELATIVE_UNITS) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }

  // Unreachable, but satisfies the compiler.
  return rtf.format(0, "second");
}
```

