### Notes on design choices

- **No dependencies:** Uses `Intl.NumberFormat`, `Intl.DateTimeFormat`, and `Intl.RelativeTimeFormat`, which are supported in all modern browsers and Node.js 14+.
- **Fails loudly:** Invalid numbers or dates throw a `RangeError` instead of silently rendering `"NaN"` or `"Invalid Date"`.
- **Cents helper:** Storing money as integer minor units avoids floating-point rounding bugs, so `formatPriceFromCents` is the safer choice when your backend provides integer amounts.
- **Date-only strings:** `new Date("2024-12-25")` is parsed as UTC midnight, so pass `timeZone: "UTC"` when formatting date-only values to avoid off-by-one-day results in western time zones.
- **Performance:** If you format thousands of values in a hot loop, consider caching `Intl` formatter instances keyed by their options, since constructing them is relatively expensive.

Here's a small, dependency-free TypeScript module built on the native `Intl` APIs:

```typescript
// format.ts

export type DateInput = Date | string | number;

export interface PriceOptions {
  currency?: string;       // ISO 4217 code, e.g. "USD", "EUR"
  locale?: string;         // BCP 47 tag, e.g. "en-US", "de-DE"
  minorUnits?: boolean;    // true if amount is in cents (e.g. 1999 -> $19.99)
  showFreeAsText?: boolean; // render 0 as "Free"
}

export type DateStyle = "short" | "medium" | "long" | "full";

const DEFAULT_LOCALE = "en-US";
const DEFAULT_CURRENCY = "USD";

// Cache formatters — constructing Intl objects is relatively expensive.
const numberFormatCache = new Map<string, Intl.NumberFormat>();
const dateFormatCache = new Map<string, Intl.DateTimeFormat>();

function getNumberFormat(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let fmt = numberFormatCache.get(key);
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, options);
    numberFormatCache.set(key, fmt);
  }
  return fmt;
}

function getDateFormat(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let fmt = dateFormatCache.get(key);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat(locale, options);
    dateFormatCache.set(key, fmt);
  }
  return fmt;
}

/** Converts a Date, ISO string, or timestamp into a valid Date, or throws. */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}

// ---------------------------------------------------------------------------
// Prices
// ---------------------------------------------------------------------------

/**
 * Formats a monetary amount.
 * @example formatPrice(19.99)                         // "$19.99"
 * @example formatPrice(1999, { minorUnits: true })    // "$19.99"
 * @example formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    currency = DEFAULT_CURRENCY,
    locale = DEFAULT_LOCALE,
    minorUnits = false,
    showFreeAsText = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid amount: ${amount}`);
  }

  const formatter = getNumberFormat(locale, { style: "currency", currency });

  let value = amount;
  if (minorUnits) {
    // Respect the currency's actual decimal places (JPY has 0, KWD has 3, etc.)
    const digits = formatter.resolvedOptions().maximumFractionDigits ?? 2;
    value = amount / 10 ** digits;
  }

  if (showFreeAsText && value === 0) return "Free";

  return formatter.format(value);
}

/**
 * Formats a price range, collapsing to a single price if min === max.
 * @example formatPriceRange(10, 25) // "$10.00 – $25.00"
 */
export function formatPriceRange(min: number, max: number, options: PriceOptions = {}): string {
  if (min === max) return formatPrice(min, options);
  const [lo, hi] = min < max ? [min, max] : [max, min];
  return `${formatPrice(lo, options)} – ${formatPrice(hi, options)}`;
}

/**
 * Compact price for tight UI spaces.
 * @example formatCompactPrice(1_250_000) // "$1.3M"
 */
export function formatCompactPrice(
  amount: number,
  { currency = DEFAULT_CURRENCY, locale = DEFAULT_LOCALE }: Pick<PriceOptions, "currency" | "locale"> = {}
): string {
  return getNumberFormat(locale, {
    style: "currency",
    currency,
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(amount);
}

// ---------------------------------------------------------------------------
// Dates
// ---------------------------------------------------------------------------

/**
 * Formats a date using a preset style.
 * @example formatDate("2024-03-15")           // "Mar 15, 2024"
 * @example formatDate(new Date(), "full")     // "Friday, March 15, 2024"
 */
export function formatDate(
  input: DateInput,
  style: DateStyle = "medium",
  locale: string = DEFAULT_LOCALE,
  timeZone?: string
): string {
  return getDateFormat(locale, { dateStyle: style, timeZone }).format(toDate(input));
}

/**
 * Formats a date with time.
 * @example formatDateTime(new Date()) // "Mar 15, 2024, 3:45 PM"
 */
export function formatDateTime(
  input: DateInput,
  style: DateStyle = "medium",
  locale: string = DEFAULT_LOCALE,
  timeZone?: string
): string {
  return getDateFormat(locale, { dateStyle: style, timeStyle: "short", timeZone }).format(
    toDate(input)
  );
}

/** Formats as YYYY-MM-DD in local time (useful for <input type="date">). */
export function formatISODate(input: DateInput): string {
  const d = toDate(input);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

const RELATIVE_UNITS: Array<[Intl.RelativeTimeFormatUnit, number]> = [
  ["year", 60 * 60 * 24 * 365],
  ["month", 60 * 60 * 24 * 30],
  ["week", 60 * 60 * 24 * 7],
  ["day", 60 * 60 * 24],
  ["hour", 60 * 60],
  ["minute", 60],
  ["second", 1],
];

/**
 * Human-friendly relative time.
 * @example formatRelativeTime(Date.now() - 5 * 60_000) // "5 minutes ago"
 * @example formatRelativeTime(Date.now() + 86_400_000) // "tomorrow"
 */
export function formatRelativeTime(
  input: DateInput,
  locale: string = DEFAULT_LOCALE,
  now: DateInput = Date.now()
): string {
  const diffSeconds = (toDate(input).getTime() - toDate(now).getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, secondsInUnit] of RELATIVE_UNITS) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return rtf.format(0, "second"); // unreachable, satisfies the compiler
}
```

