**Design notes:**
- **No dependencies:** everything uses the built-in `Intl` APIs, which handle locale-specific separators, symbols, and ordering.
- **Formatter caching:** `Intl` constructors are slow-ish, so instances are reused per locale/options combo.
- **Minor units:** storing money as integer cents avoids floating-point errors. The `minorUnits` option respects each currency's real decimal count, so it handles currencies like JPY (0 decimals) and KWD (3 decimals).
- **Flexible date input:** functions accept `Date`, ISO strings, or timestamps, and throw a clear `RangeError` on invalid input instead of printing "Invalid Date".
- **Time zones:** `formatDate` and `formatDateTime` accept an optional `timeZone` (e.g. `"UTC"`, `"America/New_York"`). Use it for date-only strings, because `"2024-03-15"` is parsed as UTC midnight and can show as the previous day in western time zones.

Here's a small, dependency-free TypeScript module built on the native `Intl` APIs:

```typescript
// formatters.ts

/* =========================
 * Price formatting
 * ========================= */

export interface PriceFormatOptions {
  /** ISO 4217 currency code, e.g. "USD", "EUR". Default: "USD" */
  currency?: string;
  /** BCP 47 locale, e.g. "en-US", "de-DE". Default: "en-US" */
  locale?: string;
  /** Minimum fraction digits. Default: currency's standard (usually 2) */
  minimumFractionDigits?: number;
  /** Maximum fraction digits. Default: currency's standard (usually 2) */
  maximumFractionDigits?: number;
  /** Use compact notation, e.g. "$1.2K". Default: false */
  compact?: boolean;
}

/**
 * Formats a number as a localized currency string.
 *
 * @example
 * formatPrice(1234.5)                          // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * formatPrice(1250000, { compact: true })      // "$1.3M"
 */
export function formatPrice(
  amount: number,
  {
    currency = "USD",
    locale = "en-US",
    minimumFractionDigits,
    maximumFractionDigits,
    compact = false,
  }: PriceFormatOptions = {}
): string {
  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: expected a finite number, got ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

/**
 * Formats an integer amount in minor units (e.g. cents) as currency.
 * Useful when prices are stored as integers to avoid floating-point issues.
 *
 * @example
 * formatPriceFromCents(1999) // "$19.99"
 */
export function formatPriceFromCents(
  cents: number,
  options: PriceFormatOptions = {}
): string {
  if (!Number.isInteger(cents)) {
    throw new TypeError(`formatPriceFromCents: expected an integer, got ${cents}`);
  }
  return formatPrice(cents / 100, options);
}

/**
 * Formats a price range.
 *
 * @example
 * formatPriceRange(10, 25) // "$10.00 – $25.00"
 * formatPriceRange(10, 10) // "$10.00"
 */
export function formatPriceRange(
  min: number,
  max: number,
  options: PriceFormatOptions = {}
): string {
  if (min === max) return formatPrice(min, options);
  const [low, high] = min < max ? [min, max] : [max, min];
  return `${formatPrice(low, options)} – ${formatPrice(high, options)}`;
}

/* =========================
 * Date formatting
 * ========================= */

export type DateInput = Date | string | number;

/** Preset styles for common date formats. */
export type DateStyle = "short" | "medium" | "long" | "full";

/**
 * Converts supported inputs into a valid Date, or throws.
 */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? new Date(input.getTime()) : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`toDate: invalid date input "${String(input)}"`);
  }
  return date;
}

/**
 * Formats a date using a preset style.
 *
 * @example
 * formatDate("2024-03-15")                    // "Mar 15, 2024"
 * formatDate(new Date(), "full")              // "Friday, March 15, 2024"
 * formatDate(Date.now(), "short", "en-GB")    // "15/03/2024"
 */
export function formatDate(
  input: DateInput,
  style: DateStyle = "medium",
  locale = "en-US",
  timeZone?: string
): string {
  return new Intl.DateTimeFormat(locale, { dateStyle: style, timeZone }).format(
    toDate(input)
  );
}

/**
 * Formats a date with time.
 *
 * @example
 * formatDateTime("2024-03-15T14:30:00") // "Mar 15, 2024, 2:30 PM"
 */
export function formatDateTime(
  input: DateInput,
  dateStyle: DateStyle = "medium",
  timeStyle: DateStyle = "short",
  locale = "en-US",
  timeZone?: string
): string {
  return new Intl.DateTimeFormat(locale, { dateStyle, timeStyle, timeZone }).format(
    toDate(input)
  );
}

/**
 * Formats a date as an ISO calendar date string (YYYY-MM-DD) in local time.
 * Unlike `toISOString().slice(0, 10)`, this does not shift to UTC.
 *
 * @example
 * formatISODate(new Date(2024, 2, 5)) // "2024-03-05"
 */
export function formatISODate(input: DateInput): string {
  const d = toDate(input);
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

const RELATIVE_UNITS: Array<[Intl.RelativeTimeFormatUnit, number]> = [
  ["year", 60 * 60 * 24 * 365],
  ["month", 60 * 60 * 24 * 30],
  ["week", 60 * 60 * 24 * 7],
  ["day", 60 * 60 * 24],
  ["hour", 60 * 60],
  ["minute", 60],
  ["second", 1],
];

/**
 * Formats a date relative to now (or a given reference date).
 *
 * @example
 * formatRelativeTime(Date.now() - 5 * 60 * 1000) // "5 minutes ago"
 * formatRelativeTime(Date.now() + 86400000)      // "tomorrow"
 */
export function formatRelativeTime(
  input: DateInput,
  locale = "en-US",
  now: DateInput = Date.now()
): string {
  const diffSeconds = (toDate(input).getTime() - toDate(now).getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, secondsInUnit] of RELATIVE_UNITS) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }

  // Unreachable, but satisfies the compiler.
  return rtf.format(0, "second");
}
