### Notes
- **No dependencies**: everything uses the built-in `Intl` APIs, supported in all modern browsers and Node 14+.
- **Validation**: invalid numbers and dates throw descriptive errors instead of silently producing `"NaN"` or `"Invalid Date"`.
- **Cents helper**: storing prices as integers (minor units) avoids floating-point rounding bugs. Note that `/ 100` assumes a 2-decimal currency; for currencies like JPY (0 decimals), pass whole units to `formatPrice` instead.
- **Performance**: if you format thousands of values in a hot loop, consider caching `Intl.NumberFormat`/`DateTimeFormat` instances keyed by their options, since constructing them is relatively expensive.

Here's a small, dependency-free TypeScript module built on the native `Intl` APIs:

```typescript
// format.ts

/** Accepted date inputs: Date objects, ISO strings, or timestamps (ms). */
export type DateInput = Date | string | number;

export interface PriceOptions {
  /** ISO 4217 currency code. Default: "USD" */
  currency?: string;
  /** BCP 47 locale. Default: "en-US" */
  locale?: string;
  /** Treat the amount as minor units (e.g. cents). Default: false */
  fromMinorUnits?: boolean;
  /** Drop ".00" for whole amounts. Default: false */
  hideZeroCents?: boolean;
}

export type DateStyle = "short" | "medium" | "long" | "full";

const DEFAULT_LOCALE = "en-US";
const DEFAULT_CURRENCY = "USD";

// Intl formatters are relatively expensive to construct, so cache them.
const numberFormatCache = new Map<string, Intl.NumberFormat>();
const dateFormatCache = new Map<string, Intl.DateTimeFormat>();

function getNumberFormat(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let fmt = numberFormatCache.get(key);
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, options);
    numberFormatCache.set(key, fmt);
  }
  return fmt;
}

function getDateFormat(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let fmt = dateFormatCache.get(key);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat(locale, options);
    dateFormatCache.set(key, fmt);
  }
  return fmt;
}

/** Number of minor-unit digits for a currency (USD → 2, JPY → 0, KWD → 3). */
function getCurrencyDigits(currency: string, locale: string): number {
  return (
    getNumberFormat(locale, { style: "currency", currency }).resolvedOptions()
      .maximumFractionDigits ?? 2
  );
}

/** Converts any DateInput to a valid Date, or throws. */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? new Date(input.getTime()) : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}

// ─── Prices ──────────────────────────────────────────────────────────────────

/**
 * Formats a monetary amount.
 *
 * @example
 * formatPrice(1234.5)                                   // "$1,234.50"
 * formatPrice(199900, { fromMinorUnits: true })         // "$1,999.00"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * formatPrice(20, { hideZeroCents: true })              // "$20"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    currency = DEFAULT_CURRENCY,
    locale = DEFAULT_LOCALE,
    fromMinorUnits = false,
    hideZeroCents = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid amount: ${amount}`);
  }

  const digits = getCurrencyDigits(currency, locale);
  const value = fromMinorUnits ? amount / 10 ** digits : amount;

  const fmtOptions: Intl.NumberFormatOptions = { style: "currency", currency };
  if (hideZeroCents && Number.isInteger(value)) {
    fmtOptions.minimumFractionDigits = 0;
    fmtOptions.maximumFractionDigits = 0;
  }

  return getNumberFormat(locale, fmtOptions).format(value);
}

/**
 * Formats a price range, collapsing to a single price if min === max.
 *
 * @example
 * formatPriceRange(10, 25) // "$10.00 – $25.00"
 */
export function formatPriceRange(min: number, max: number, options: PriceOptions = {}): string {
  if (min === max) return formatPrice(min, options);
  return `${formatPrice(min, options)} – ${formatPrice(max, options)}`;
}

/**
 * Formats a price in compact notation.
 *
 * @example
 * formatCompactPrice(1_250_000) // "$1.3M"
 */
export function formatCompactPrice(
  amount: number,
  options: Pick<PriceOptions, "currency" | "locale"> = {},
): string {
  const { currency = DEFAULT_CURRENCY, locale = DEFAULT_LOCALE } = options;
  return getNumberFormat(locale, {
    style: "currency",
    currency,
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(amount);
}

// ─── Dates ───────────────────────────────────────────────────────────────────

/**
 * Formats a date using a preset style.
 *
 * @example
 * formatDate("2024-03-15T12:00:00Z")           // "Mar 15, 2024"
 * formatDate(new Date(), { style: "long" })     // "March 15, 2024"
 * formatDate(date, { timeZone: "UTC" })         // force a specific zone
 */
export function formatDate(
  input: DateInput,
  options: { style?: DateStyle; locale?: string; timeZone?: string } = {},
): string {
  const { style = "medium", locale = DEFAULT_LOCALE, timeZone } = options;
  return getDateFormat(locale, { dateStyle: style, timeZone }).format(toDate(input));
}

/**
 * Formats a date with a time component.
 *
 * @example
 * formatDateTime(new Date()) // "Mar 15, 2024, 2:30 PM"
 */
export function formatDateTime(
  input: DateInput,
  options: { dateStyle?: DateStyle; timeStyle?: DateStyle; locale?: string; timeZone?: string } = {},
): string {
  const { dateStyle = "medium", timeStyle = "short", locale = DEFAULT_LOCALE, timeZone } = options;
  return getDateFormat(locale, { dateStyle, timeStyle, timeZone }).format(toDate(input));
}

/**
 * Formats a date as an ISO calendar date (YYYY-MM-DD) in local time.
 * Unlike `toISOString().slice(0, 10)`, this doesn't shift the day across UTC.
 */
export function formatISODate(input: DateInput): string {
  const d = toDate(input);
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

const RELATIVE_UNITS: Array<[Intl.RelativeTimeFormatUnit, number]> = [
  ["year", 365 * 24 * 60 * 60 * 1000],
  ["month", 30 * 24 * 60 * 60 * 1000],
  ["week", 7 * 24 * 60 * 60 * 1000],
  ["day", 24 * 60 * 60 * 1000],
  ["hour", 60 * 60 * 1000],
  ["minute", 60 * 1000],
  ["second", 1000],
];

