// Prices
// ---------------------------------------------------------------------------

export interface PriceOptions {
  currency?: string;
  locale?: string;
  /** Treat the amount as minor units (e.g. cents). Default: false. */
  fromMinorUnits?: boolean;
  /** Hide ".00" for whole amounts. Default: false. */
  trimZeroDecimals?: boolean;
  /** Use compact notation, e.g. "$1.2K". Default: false. */
  compact?: boolean;
}

/**
 * Format a numeric amount as a currency string.
 *
 * @example formatPrice(1234.5)                          // "$1,234.50"
 * @example formatPrice(1999, { fromMinorUnits: true })  // "$19.99"
 * @example formatPrice(10, { trimZeroDecimals: true })  // "$10"
 * @example formatPrice(1500000, { compact: true })      // "$1.5M"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    currency = DEFAULT_CURRENCY,
    locale = DEFAULT_LOCALE,
    fromMinorUnits = false,
    trimZeroDecimals = false,
    compact = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid amount: ${amount}`);
  }

  const base = getNumberFormat(locale, { style: "currency", currency });
  const fractionDigits = base.resolvedOptions().maximumFractionDigits ?? 2;
  const value = fromMinorUnits ? amount / 10 ** fractionDigits : amount;

  if (compact) {
    return getNumberFormat(locale, {
      style: "currency",
      currency,
      notation: "compact",
      maximumFractionDigits: 1,
    }).format(value);
  }

  if (trimZeroDecimals && Number.isInteger(value)) {
    return getNumberFormat(locale, {
      style: "currency",
      currency,
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);
  }

  return base.format(value);
}

