 * Format a price range.
 *
 * @example formatPriceRange(10, 25) // "$10.00 – $25.00"
 */
export function formatPriceRange(min: number, max: number, options: PriceOptions = {}): string {
  if (min === max) return formatPrice(min, options);
  return `${formatPrice(min, options)} – ${formatPrice(max, options)}`;
}

/**
 * Format a discount as a percentage.
 *
 * @example formatDiscount(100, 75) // "-25%"
 */
export function formatDiscount(original: number, discounted: number, locale = DEFAULT_LOCALE): string {
  if (original <= 0) throw new RangeError("Original price must be greater than 0");
  const ratio = (discounted - original) / original;
  return getNumberFormat(locale, {
    style: "percent",
    maximumFractionDigits: 0,
    signDisplay: "exceptZero",
  }).format(ratio);
}

