  ["year", 365 * 24 * 60 * 60 * 1000],
  ["month", 30 * 24 * 60 * 60 * 1000],
  ["week", 7 * 24 * 60 * 60 * 1000],
  ["day", 24 * 60 * 60 * 1000],
  ["hour", 60 * 60 * 1000],
  ["minute", 60 * 1000],
  ["second", 1000],
];

/**
 * Format a date relative to now (or a given reference date).
 *
 * @example formatRelative(Date.now() - 5 * 60_000)    // "5 minutes ago"
 * @example formatRelative(Date.now() + 86_400_000)    // "tomorrow"
 */
export function formatRelative(
  input: DateInput,
  { locale = DEFAULT_LOCALE, now = new Date() }: { locale?: string; now?: DateInput } = {}
): string {
  const diff = toDate(input).getTime() - toDate(now).getTime();
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, ms] of RELATIVE_UNITS) {
    if (Math.abs(diff) >= ms || unit === "second") {
      return rtf.format(Math.round(diff / ms), unit);
    }
  }
  return rtf.format(0, "second"); // unreachable, satisfies the compiler
}

/**
 * Format a date range compactly when possible.
 *
 * @example formatDateRange("2024-03-01", "2024-03-05") // "Mar 1 – 5, 2024"
 */
export function formatDateRange(start: DateInput, end: DateInput, options: DateOptions = {}): string {
  const { locale = DEFAULT_LOCALE, timeZone, style = "medium" } = options;
  const fmt = getDateFormat(locale, { dateStyle: style, ...(timeZone && { timeZone }) });
  return fmt.formatRange(toDate(start), toDate(end));
}
