```typescript
// format.ts
// Helper functions for formatting prices and dates.

export type DateInput = Date | string | number;

export interface PriceOptions {
  currency?: string;          // ISO 4217 code, e.g. "USD", "EUR"
  locale?: string;            // BCP 47 tag, e.g. "en-US", "de-DE"
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  compact?: boolean;          // e.g. "$1.2K" instead of "$1,234.00"
}

export type DateStyle = "short" | "medium" | "long" | "full";

const DEFAULT_LOCALE = "en-US";
const DEFAULT_CURRENCY = "USD";

// Intl formatters are relatively expensive to create, so cache them.
const formatterCache = new Map<string, Intl.NumberFormat | Intl.DateTimeFormat>();

function getNumberFormat(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `num|${locale}|${JSON.stringify(options)}`;
  let fmt = formatterCache.get(key) as Intl.NumberFormat | undefined;
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, options);
    formatterCache.set(key, fmt);
  }
  return fmt;
}

function getDateFormat(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `date|${locale}|${JSON.stringify(options)}`;
  let fmt = formatterCache.get(key) as Intl.DateTimeFormat | undefined;
  if (!fmt) {
    fmt = new Intl.DateTimeFormat(locale, options);
    formatterCache.set(key, fmt);
  }
  return fmt;
}

/** Converts a Date, ISO string, or timestamp to a valid Date, or throws. */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}

// ---------------------------------------------------------------------------
// Prices
// ---------------------------------------------------------------------------

/**
 * Formats a numeric amount as a currency string.
 * @example formatPrice(1234.5)                          // "$1,234.50"
 * @example formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * @example formatPrice(1234567, { compact: true })      // "$1.2M"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid amount: ${amount}`);
  }

  const {
    currency = DEFAULT_CURRENCY,
    locale = DEFAULT_LOCALE,
    minimumFractionDigits,
    maximumFractionDigits,
    compact = false,
  } = options;

  const fmtOptions: Intl.NumberFormatOptions = {
    style: "currency",
    currency,
    ...(compact && { notation: "compact", maximumFractionDigits: 1 }),
    ...(minimumFractionDigits !== undefined && { minimumFractionDigits }),
    ...(maximumFractionDigits !== undefined && { maximumFractionDigits }),
  };

  return getNumberFormat(locale, fmtOptions).format(amount);
}

/**
 * Formats an amount stored in minor units (e.g. cents) — the safest way to
 * store money, since it avoids floating-point rounding issues.
 * @example formatCents(199900) // "$1,999.00"
 */
export function formatCents(cents: number, options: PriceOptions = {}): string {
  if (!Number.isInteger(cents)) {
    throw new RangeError(`Cents must be an integer: ${cents}`);
  }
  const currency = options.currency ?? DEFAULT_CURRENCY;
  // Ask Intl how many decimal places this currency uses (JPY = 0, USD = 2, KWD = 3).
  const digits =
    getNumberFormat(DEFAULT_LOCALE, { style: "currency", currency })
      .resolvedOptions().maximumFractionDigits ?? 2;
  return formatPrice(cents / 10 ** digits, options);
}

/**
 * Formats a price range.
 * @example formatPriceRange(10, 25) // "$10.00 – $25.00"
 */
export function formatPriceRange(min: number, max: number, options: PriceOptions = {}): string {
  if (min === max) return formatPrice(min, options);
  const [lo, hi] = min < max ? [min, max] : [max, min];
  return `${formatPrice(lo, options)} – ${formatPrice(hi, options)}`;
}

/**
 * Formats a percentage discount between an original and sale price.
 * @example formatDiscount(80, 60) // "-25%"
 */
export function formatDiscount(original: number, sale: number, locale = DEFAULT_LOCALE): string {
  if (original <= 0) throw new RangeError("Original price must be greater than 0");
  const ratio = (sale - original) / original;
  return getNumberFormat(locale, {
    style: "percent",
    maximumFractionDigits: 0,
    signDisplay: "exceptZero",
  }).format(ratio);
}

// ---------------------------------------------------------------------------
// Dates
// ---------------------------------------------------------------------------

/**
 * Formats a date using a preset style.
 * @example formatDate("2024-03-15")           // "Mar 15, 2024"
 * @example formatDate(new Date(), "long")     // "March 15, 2024"
 */
export function formatDate(
  input: DateInput,
  style: DateStyle = "medium",
  locale = DEFAULT_LOCALE,
  timeZone?: string
): string {
  return getDateFormat(locale, { dateStyle: style, timeZone }).format(toDate(input));
}

/**
 * Formats a date and time.
 * @example formatDateTime(new Date()) // "Mar 15, 2024, 3:45 PM"
 */
export function formatDateTime(
  input: DateInput,
  dateStyle: DateStyle = "medium",
  timeStyle: DateStyle = "short",
  locale = DEFAULT_LOCALE,
  timeZone?: string
): string {
  return getDateFormat(locale, { dateStyle, timeStyle, timeZone }).format(toDate(input));
}

/**
 * Formats a date as ISO `YYYY-MM-DD` in local time (useful for <input type="date">).
 * Note: `toISOString().slice(0, 10)` uses UTC and can be off by a day.
 */
export function formatISODate(input: DateInput): string {
  const d = toDate(input);
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 60 * 60 * 24 * 365],
  ["month", 60 * 60 * 24 * 30],
  ["week", 60 * 60 * 24 * 7],
  ["day", 60 * 60 * 24],
  ["hour", 60 * 60],
  ["minute", 60],
  ["second", 1],
];

/**
 * Formats a date relative to now (or a given reference date).
 * @example formatRelative(Date.now() - 5 * 60_000)    // "5 minutes ago"
 * @example formatRelative(Date.now() + 86_400_000)    // "tomorrow"
 */
export function formatRelative(
  input: DateInput,
  now: DateInput = Date.now(),
  locale = DEFAULT_LOCALE
): string {
  const diffSeconds = (toDate(input).getTime() - toDate(now).getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, secondsInUnit] of RELATIVE_UNITS) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return rtf.format(0, "second"); // unreachable, satisfies the compiler
}

/**
 * Formats a date range, collapsing shared parts where possible.
 * @example formatDateRange("2024-03-15", "2024-03-20") // "Mar 15 – 20, 2024"
 */
export function formatDateRange(
  start: DateInput,
  end: DateInput,
  style: DateStyle = "medium",
  locale = DEFAULT_LOCALE
): string {
  return getDateFormat(locale, { dateStyle: style }).formatRange(toDate(start), toDate(end));
}
