// format.ts

export type DateInput = Date | string | number;

export interface PriceOptions {
  currency?: string;        // ISO 4217 code, e.g. "USD", "EUR"
  locale?: string;          // BCP 47 tag, e.g. "en-US", "de-DE"
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  fromCents?: boolean;      // treat input as minor units (e.g. 1999 -> 19.99)
}

export type DateStyle = "short" | "medium" | "long" | "full";

const DEFAULT_LOCALE = "en-US";
const DEFAULT_CURRENCY = "USD";

// Cache formatters — constructing Intl objects is relatively expensive.
const formatterCache = new Map<string, Intl.NumberFormat | Intl.DateTimeFormat>();

function getNumberFormat(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `num|${locale}|${JSON.stringify(options)}`;
  let fmt = formatterCache.get(key) as Intl.NumberFormat | undefined;
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, options);
    formatterCache.set(key, fmt);
  }
  return fmt;
}

function getDateFormat(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `date|${locale}|${JSON.stringify(options)}`;
  let fmt = formatterCache.get(key) as Intl.DateTimeFormat | undefined;
  if (!fmt) {
    fmt = new Intl.DateTimeFormat(locale, options);
    formatterCache.set(key, fmt);
  }
  return fmt;
}

/** Converts a Date, ISO string, or timestamp into a valid Date, or throws. */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? new Date(input.getTime()) : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}

