// Prices
// ---------------------------------------------------------------------------

/**
 * Formats a number as a localized currency string.
 *
 * @example
 * formatPrice(1234.5)                                   // "$1,234.50"
 * formatPrice(1999, { fromCents: true })                // "$19.99"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid amount: ${amount}`);
  }

  const {
    currency = DEFAULT_CURRENCY,
    locale = DEFAULT_LOCALE,
    minimumFractionDigits,
    maximumFractionDigits,
    fromCents = false,
  } = options;

  const fmt = getNumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits,
    maximumFractionDigits,
  });

  // Use the currency's own number of decimal places (e.g. JPY = 0, USD = 2).
  const digits = fmt.resolvedOptions().maximumFractionDigits ?? 2;
  const value = fromCents ? amount / 10 ** digits : amount;

  return fmt.format(value);
}

/**
 * Formats a price compactly, e.g. "$1.2K", "$3.4M".
 */
