  input: DateInput,
  style: DateStyle = "medium",
  locale: string = DEFAULT_LOCALE,
  timeZone?: string
): string {
  return getDateFormat(locale, {
    dateStyle: style,
    timeStyle: "short",
    timeZone,
  }).format(toDate(input));
}

