    throw new RangeError(`Invalid amount: ${amount}`);
  }

  const intlOptions: Intl.NumberFormatOptions = { style: "currency", currency };

  if (compact) {
    intlOptions.notation = "compact";
    intlOptions.maximumFractionDigits = 1;
  } else if (trimWholeNumbers && Number.isInteger(amount)) {
    intlOptions.minimumFractionDigits = 0;
    intlOptions.maximumFractionDigits = 0;
