formatISODate(new Date());                             // "2024-03-15"
formatRelativeTime(Date.now() - 2 * 3600_000);         // "2 hours ago"
```

### Design notes

- **No dependencies:** It relies entirely on the built-in `Intl` APIs, which handle locale-specific separators, currency symbols, and month names.
- **Formatter caching:** Creating `Intl` formatters is relatively costly, so they're cached by locale and options.
- **Cents support:** `formatPriceFromCents` reads the currency's minor-unit digits, so JPY (0 decimals) and KWD (3 decimals) work correctly.
- **Input validation:** Invalid dates and non-finite amounts throw a `RangeError` instead of silently printing `"Invalid Date"` or `"NaN"`.
- **Date-only strings:** Note that `new Date("2024-03-15")` is parsed as UTC midnight, which can display as the previous day in western time zones. Pass a full timestamp (e.g. `"2024-03-15T00:00:00"`) if you mean local time.

Here's a small, dependency-free TypeScript module built on the native `Intl` APIs:

```typescript
// format.ts

export type DateInput = Date | string | number;

const DEFAULT_LOCALE = "en-US";
const DEFAULT_CURRENCY = "USD";

// Intl formatters are relatively expensive to construct, so we cache them.
const numberFormatCache = new Map<string, Intl.NumberFormat>();
const dateFormatCache = new Map<string, Intl.DateTimeFormat>();

function getNumberFormat(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let fmt = numberFormatCache.get(key);
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, options);
    numberFormatCache.set(key, fmt);
  }
  return fmt;
}

function getDateFormat(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let fmt = dateFormatCache.get(key);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat(locale, options);
    dateFormatCache.set(key, fmt);
  }
  return fmt;
}

/** Converts a Date, ISO string, or timestamp into a valid Date, or throws. */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? new Date(input.getTime()) : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}

// ---------------------------------------------------------------------------
// Prices
// ---------------------------------------------------------------------------

export interface PriceOptions {
  currency?: string;
  locale?: string;
  /** Use compact notation, e.g. "$1.2K". */
  compact?: boolean;
  /** Drop ".00" for whole amounts, e.g. "$10" instead of "$10.00". */
  hideZeroCents?: boolean;
}

/**
 * Formats an amount in major units (e.g. dollars).
 * formatPrice(1234.5) -> "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) -> "1.234,50 €"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid amount: ${amount}`);
  }

  const {
    currency = DEFAULT_CURRENCY,
    locale = DEFAULT_LOCALE,
    compact = false,
    hideZeroCents = false,
  } = options;

  const intlOptions: Intl.NumberFormatOptions = { style: "currency", currency };

  if (compact) {
    intlOptions.notation = "compact";
    intlOptions.maximumFractionDigits = 1;
  } else if (hideZeroCents && Number.isInteger(amount)) {
    intlOptions.minimumFractionDigits = 0;
    intlOptions.maximumFractionDigits = 0;
  }

  return getNumberFormat(locale, intlOptions).format(amount);
}

/**
 * Formats an integer amount in minor units (e.g. cents), as returned by
 * most payment APIs. Respects currencies with 0 or 3 decimal places.
 * formatPriceFromMinor(123450) -> "$1,234.50"
 * formatPriceFromMinor(500, { currency: "JPY" }) -> "¥500"
 */
export function formatPriceFromMinor(minorUnits: number, options: PriceOptions = {}): string {
  if (!Number.isInteger(minorUnits)) {
    throw new RangeError(`Minor units must be an integer: ${minorUnits}`);
  }

  const currency = options.currency ?? DEFAULT_CURRENCY;
  const locale = options.locale ?? DEFAULT_LOCALE;
  const digits =
    getNumberFormat(locale, { style: "currency", currency }).resolvedOptions()
      .maximumFractionDigits ?? 2;

  return formatPrice(minorUnits / 10 ** digits, options);
}

// ---------------------------------------------------------------------------
// Dates
// ---------------------------------------------------------------------------

export type DateStyle = "short" | "medium" | "long" | "full";

export interface DateOptions {
  locale?: string;
  style?: DateStyle;
  /** IANA time zone, e.g. "UTC" or "America/New_York". Defaults to local. */
  timeZone?: string;
}

/**
 * formatDate("2024-03-15T12:00:00Z") -> "Mar 15, 2024"
 * formatDate(date, { style: "full" }) -> "Friday, March 15, 2024"
 */
export function formatDate(input: DateInput, options: DateOptions = {}): string {
  const { locale = DEFAULT_LOCALE, style = "medium", timeZone } = options;
  return getDateFormat(locale, { dateStyle: style, timeZone }).format(toDate(input));
}

/**
 * formatDateTime(date) -> "Mar 15, 2024, 2:30 PM"
 */
export function formatDateTime(
  input: DateInput,
  options: DateOptions & { timeStyle?: DateStyle } = {}
): string {
  const { locale = DEFAULT_LOCALE, style = "medium", timeStyle = "short", timeZone } = options;
  return getDateFormat(locale, { dateStyle: style, timeStyle, timeZone }).format(toDate(input));
}

/** Returns a "YYYY-MM-DD" string in local time (or UTC if `utc` is true). */
export function toISODate(input: DateInput, utc = false): string {
  const d = toDate(input);
  const year = utc ? d.getUTCFullYear() : d.getFullYear();
  const month = (utc ? d.getUTCMonth() : d.getMonth()) + 1;
  const day = utc ? d.getUTCDate() : d.getDate();
  return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 60 * 60 * 24 * 365],
  ["month", 60 * 60 * 24 * 30],
  ["week", 60 * 60 * 24 * 7],
  ["day", 60 * 60 * 24],
  ["hour", 60 * 60],
  ["minute", 60],
  ["second", 1],
];

/**
 * Human-friendly relative time.
 * formatRelative(fiveMinutesAgo) -> "5 minutes ago"
 * formatRelative(tomorrow) -> "tomorrow"
 */
export function formatRelative(
  input: DateInput,
  options: { locale?: string; now?: DateInput } = {}
): string {
  const { locale = DEFAULT_LOCALE, now = Date.now() } = options;
  const diffSeconds = (toDate(input).getTime() - toDate(now).getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, secondsInUnit] of RELATIVE_UNITS) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return rtf.format(0, "second"); // unreachable, satisfies the compiler
}
```

