    intlOptions.maximumFractionDigits = 1;
  } else if (trimWholeNumbers && Number.isInteger(amount)) {
    intlOptions.minimumFractionDigits = 0;
    intlOptions.maximumFractionDigits = 0;
  }

  return getNumberFormat(locale, intlOptions).format(amount);
}

/**
 * Formats an amount stored in minor units (e.g. cents), which is the
 * recommended way to store money to avoid floating-point errors.
 * formatPriceFromCents(199) -> "$1.99"
 */
export function formatPriceFromCents(
  cents: number,
  options: PriceOptions = {}
): string {
  if (!Number.isInteger(cents)) {
    throw new RangeError(`Cents must be an integer: ${cents}`);
  }
  const currency = options.currency ?? DEFAULT_CURRENCY;
  const locale = options.locale ?? DEFAULT_LOCALE;
  // Respect currencies with non-2 decimal places (e.g. JPY = 0, KWD = 3).
  const digits =
    getNumberFormat(locale, { style: "currency", currency }).resolvedOptions()
      .maximumFractionDigits ?? 2;
  return formatPrice(cents / 10 ** digits, options);
}

/**
 * Formats a price range.
 * formatPriceRange(10, 25) -> "$10.00 – $25.00"
 */
export function formatPriceRange(
  min: number,
  max: number,
  options: PriceOptions = {}
): string {
  if (min === max) return formatPrice(min, options);
  const [low, high] = min < max ? [min, max] : [max, min];
  return `${formatPrice(low, options)} – ${formatPrice(high, options)}`;
}

// ---------- Dates ----------

export type DateStyle = "short" | "medium" | "long" | "full";

export interface DateOptions {
  locale?: string;
  timeZone?: string;
}

/**
 * Formats a date using a preset style.
 * formatDate("2024-03-15") -> "Mar 15, 2024"
 */
export function formatDate(
  input: DateInput,
  style: DateStyle = "medium",
  { locale = DEFAULT_LOCALE, timeZone }: DateOptions = {}
): string {
  return getDateFormat(locale, { dateStyle: style, timeZone }).format(toDate(input));
}

/**
 * Formats a date and time.
 * formatDateTime(new Date()) -> "Mar 15, 2024, 3:42 PM"
 */
export function formatDateTime(
  input: DateInput,
  { locale = DEFAULT_LOCALE, timeZone }: DateOptions = {}
): string {
  return getDateFormat(locale, {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone,
  }).format(toDate(input));
}

/**
 * Formats a date as ISO "YYYY-MM-DD" in local time
 * (unlike toISOString(), which uses UTC and can shift the day).
 */
export function formatISODate(input: DateInput): string {
  const d = toDate(input);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 60 * 60 * 24 * 365],
  ["month", 60 * 60 * 24 * 30],
  ["week", 60 * 60 * 24 * 7],
  ["day", 60 * 60 * 24],
  ["hour", 60 * 60],
  ["minute", 60],
  ["second", 1],
];

/**
 * Formats a date relative to now (or a given reference date).
 * formatRelative(Date.now() - 3600_000) -> "1 hour ago"
 */
export function formatRelative(
  input: DateInput,
  { locale = DEFAULT_LOCALE, now = new Date() }: { locale?: string; now?: DateInput } = {}
): string {
  const diffSeconds = (toDate(input).getTime() - toDate(now).getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, secondsInUnit] of RELATIVE_UNITS) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return rtf.format(0, "second"); // unreachable, satisfies the compiler
}
```

