 * formatPrice(10, { trimWholeNumbers: true })  // "$10"
 */
export function formatPrice(
  amount: number,
  {
    currency = "USD",
    locale = "en-US",
    compact = false,
    trimWholeNumbers = false,
  }: PriceFormatOptions = {}
): string {
  if (!Number.isFinite(amount)) {
    throw new RangeError(`formatPrice: invalid amount "${amount}"`);
  }

  const options: Intl.NumberFormatOptions = {
    style: "currency",
    currency,
  };

