  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 365 * 24 * 60 * 60 * 1000],
  ["month", 30 * 24 * 60 * 60 * 1000],
  ["week", 7 * 24 * 60 * 60 * 1000],
  ["day", 24 * 60 * 60 * 1000],
  ["hour", 60 * 60 * 1000],
  ["minute", 60 * 1000],
  ["second", 1000],
];

/**
 * Format a date relative to now (or a given reference date).
 *
 * @example
 * formatRelativeTime(Date.now() - 5 * 60 * 1000) // "5 minutes ago"
 * formatRelativeTime(Date.now() + 86400000)      // "tomorrow"
 */
export function formatRelativeTime(
  input: DateInput,
  locale = "en-US",
  now: DateInput = Date.now()
): string {
  const diffMs = toDate(input).getTime() - toDate(now).getTime();
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, ms] of RELATIVE_UNITS) {
    if (Math.abs(diffMs) >= ms || unit === "second") {
      return rtf.format(Math.round(diffMs / ms), unit);
    }
  }

  // Unreachable, but satisfies the compiler.
  return rtf.format(0, "second");
}
