```typescript
// format.ts

export type DateInput = Date | string | number;

export interface PriceOptions {
  currency?: string;          // ISO 4217 code, e.g. "USD", "EUR"
  locale?: string;            // BCP 47 tag, e.g. "en-US", "de-DE"
  fromMinorUnits?: boolean;   // true if amount is in cents (e.g. 1999 -> 19.99)
  compact?: boolean;          // "$1.2K" style output
  showFreeForZero?: boolean;  // return "Free" for 0
}

const DEFAULT_LOCALE = "en-US";
const DEFAULT_CURRENCY = "USD";

// Cache formatters; constructing Intl objects is relatively expensive.
const numberFormatCache = new Map<string, Intl.NumberFormat>();
const dateFormatCache = new Map<string, Intl.DateTimeFormat>();

function getNumberFormat(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let fmt = numberFormatCache.get(key);
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, options);
    numberFormatCache.set(key, fmt);
  }
  return fmt;
}

function getDateFormat(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let fmt = dateFormatCache.get(key);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat(locale, options);
    dateFormatCache.set(key, fmt);
  }
  return fmt;
}

/** Number of decimal places a currency uses (USD -> 2, JPY -> 0). */
export function currencyDecimals(currency: string, locale = DEFAULT_LOCALE): number {
  return (
    getNumberFormat(locale, { style: "currency", currency }).resolvedOptions()
      .maximumFractionDigits ?? 2
  );
}

/**
 * Format a price.
 * @example formatPrice(19.99)                               // "$19.99"
 * @example formatPrice(1999, { fromMinorUnits: true })      // "$19.99"
 * @example formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * @example formatPrice(1250000, { compact: true })          // "$1.3M"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    currency = DEFAULT_CURRENCY,
    locale = DEFAULT_LOCALE,
    fromMinorUnits = false,
    compact = false,
    showFreeForZero = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new RangeError(`formatPrice: invalid amount "${amount}"`);
  }

  const value = fromMinorUnits
    ? amount / 10 ** currencyDecimals(currency, locale)
    : amount;

  if (showFreeForZero && value === 0) return "Free";

  const fmtOptions: Intl.NumberFormatOptions = { style: "currency", currency };
  if (compact) {
    fmtOptions.notation = "compact";
    fmtOptions.maximumFractionDigits = 1;
  }

  return getNumberFormat(locale, fmtOptions).format(value);
}

/**
 * Format a price range.
 * @example formatPriceRange(10, 25) // "$10.00 – $25.00"
 */
export function formatPriceRange(min: number, max: number, options: PriceOptions = {}): string {
  if (min === max) return formatPrice(min, options);
  return `${formatPrice(min, options)} – ${formatPrice(max, options)}`;
}

/** Normalize input to a valid Date, throwing on invalid values. */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? new Date(input.getTime()) : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: "${String(input)}"`);
  }
  return date;
}

export type DateStyle = "short" | "medium" | "long" | "full";

/**
 * Format a date.
 * @example formatDate("2024-03-15")            // "Mar 15, 2024"
 * @example formatDate(new Date(), "long")      // "March 15, 2024"
 */
export function formatDate(
  input: DateInput,
  style: DateStyle = "medium",
  locale = DEFAULT_LOCALE,
  timeZone?: string
): string {
  return getDateFormat(locale, { dateStyle: style, timeZone }).format(toDate(input));
}

/**
 * Format a date with time.
 * @example formatDateTime(new Date()) // "Mar 15, 2024, 3:45 PM"
 */
export function formatDateTime(
  input: DateInput,
  locale = DEFAULT_LOCALE,
  timeZone?: string
): string {
  return getDateFormat(locale, { dateStyle: "medium", timeStyle: "short", timeZone }).format(
    toDate(input)
  );
}

/** Format as ISO date "YYYY-MM-DD" in local time (no UTC shift). */
export function formatISODate(input: DateInput): string {
  const d = toDate(input);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 60 * 60 * 24 * 365],
  ["month", 60 * 60 * 24 * 30],
  ["week", 60 * 60 * 24 * 7],
  ["day", 60 * 60 * 24],
  ["hour", 60 * 60],
  ["minute", 60],
  ["second", 1],
];

/**
 * Human-friendly relative time.
 * @example formatRelative(Date.now() - 3 * 60_000) // "3 minutes ago"
 * @example formatRelative(Date.now() + 86_400_000) // "tomorrow"
 */
export function formatRelative(
  input: DateInput,
  now: DateInput = Date.now(),
  locale = DEFAULT_LOCALE
): string {
  const diffSeconds = (toDate(input).getTime() - toDate(now).getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, secondsInUnit] of RELATIVE_UNITS) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
