import { useSyncExternalStore } from "react";

/**
 * Subscribes to the browser's online/offline events.
 * Returns an unsubscribe function, as required by useSyncExternalStore.
 */
function subscribe(callback: () => void): () => void {
  window.addEventListener("online", callback);
  window.addEventListener("offline", callback);

  return () => {
    window.removeEventListener("online", callback);
    window.removeEventListener("offline", callback);
  };
}

/** Reads the current online status on the client. */
function getSnapshot(): boolean {
  return navigator.onLine;
}

/**
 * Value used during server rendering and hydration.
 * We assume "online" since the server can't know the client's status.
 */
function getServerSnapshot(): boolean {
  return true;
}

/**
 * React hook that tracks whether the browser is online.
 *
 * @returns `true` if the browser reports being online, `false` otherwise.
 *
 * @example
 * const isOnline = useOnlineStatus();
 * return <p>{isOnline ? "✅ Online" : "❌ Disconnected"}</p>;
 */
export function useOnlineStatus(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

export default useOnlineStatus;
```

### Usage

```tsx
