```jsx
// UserCard.jsx
import { useState } from "react";
import PropTypes from "prop-types";
import "./UserCard.css";

function Avatar({ src, name, size = 56 }) {
  const [failed, setFailed] = useState(false);
  const initials = name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  if (!src || failed) {
    return (
      <div
        className="avatar avatar--fallback"
        style={{ width: size, height: size, fontSize: size * 0.4 }}
        aria-hidden="true"
      >
        {initials}
      </div>
    );
  }

  return (
    <img
      className="avatar"
      src={src}
      alt={`${name}'s avatar`}
      width={size}
      height={size}
      onError={() => setFailed(true)}
    />
  );
}

export default function UserCard({
  name,
  avatarUrl,
  initiallyFollowing = false,
  onFollowChange,
}) {
  const [following, setFollowing] = useState(initiallyFollowing);
  const [pending, setPending] = useState(false);

  const handleClick = async () => {
    const next = !following;
    setFollowing(next); // optimistic update
    setPending(true);
    try {
      await onFollowChange?.(next);
    } catch (err) {
      setFollowing(!next); // roll back on failure
    } finally {
      setPending(false);
    }
  };

  return (
    <div className="user-card">
      <Avatar src={avatarUrl} name={name} />
      <span className="user-card__name">{name}</span>
      <button
        type="button"
        className={`follow-btn ${following ? "follow-btn--following" : ""}`}
        onClick={handleClick}
        disabled={pending}
        aria-pressed={following}
      >
        {following ? "Following" : "Follow"}
      </button>
    </div>
  );
}

UserCard.propTypes = {
  name: PropTypes.string.isRequired,
  avatarUrl: PropTypes.string,
  initiallyFollowing: PropTypes.bool,
  onFollowChange: PropTypes.func,
};
