// format.ts
// Helpers for formatting prices and dates using the built-in Intl APIs.

export type DateInput = Date | string | number;

export interface FormatPriceOptions {
  /** BCP 47 locale tag, e.g. "en-US", "de-DE". Defaults to "en-US". */
  locale?: string;
  /** Show cents even for whole amounts. Defaults to true. */
  showCents?: boolean;
  /** Use compact notation, e.g. $1.2K. Defaults to false. */
  compact?: boolean;
}

/**
 * Formats a number as currency.
 * formatPrice(1234.5)                          -> "$1,234.50"
 * formatPrice(1234.5, "EUR", { locale: "de-DE" }) -> "1.234,50 €"
 * formatPrice(1500, "USD", { compact: true })  -> "$1.5K"
 */
export function formatPrice(
  amount: number,
  currency: string = "USD",
  options: FormatPriceOptions = {}
): string {
  const { locale = "en-US", showCents = true, compact = false } = options;

  if (!Number.isFinite(amount)) return "";

  const isWhole = Number.isInteger(amount);
  const hideCents = !showCents && isWhole;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
    ...(hideCents ? { minimumFractionDigits: 0, maximumFractionDigits: 0 } : {}),
  }).format(amount);
}

/**
 * Formats a price given in minor units (e.g. cents).
 * formatPriceFromMinor(1999, "USD") -> "$19.99"
 */
export function formatPriceFromMinor(
  minor: number,
  currency: string = "USD",
  options: FormatPriceOptions = {}
): string {
  const digits =
    new Intl.NumberFormat("en-US", { style: "currency", currency })
      .resolvedOptions().maximumFractionDigits ?? 2;
  return formatPrice(minor / 10 ** digits, currency, options);
}

function toDate(input: DateInput): Date | null {
  const date = input instanceof Date ? input : new Date(input);
  return Number.isNaN(date.getTime()) ? null : date;
}

/**
 * Formats a date using a standard style.
 * formatDate("2024-03-15T12:00:00Z")                 -> "Mar 15, 2024"
 * formatDate(new Date(), "en-GB", { dateStyle: "full" })
 */
export function formatDate(
  input: DateInput,
  locale: string = "en-US",
  options: Intl.DateTimeFormatOptions = { dateStyle: "medium" }
): string {
  const date = toDate(input);
  if (!date) return "";
  return new Intl.DateTimeFormat(locale, options).format(date);
}

/**
 * Formats a date with time.
 * formatDateTime("2024-03-15T14:30:00Z") -> "Mar 15, 2024, 2:30 PM" (in local tz)
 */
export function formatDateTime(
  input: DateInput,
  locale: string = "en-US",
  timeZone?: string
): string {
  return formatDate(input, locale, {
    dateStyle: "medium",
    timeStyle: "short",
    ...(timeZone ? { timeZone } : {}),
  });
}

/**
 * Formats a date relative to now.
 * formatRelativeTime(Date.now() - 3600_000) -> "1 hour ago"
 */
export function formatRelativeTime(
  input: DateInput,
  locale: string = "en-US",
  now: DateInput = Date.now()
): string {
  const date = toDate(input);
  const base = toDate(now);
  if (!date || !base) return "";

  const diffSeconds = Math.round((date.getTime() - base.getTime()) / 1000);
  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 31_536_000],
    ["month", 2_592_000],
    ["week", 604_800],
    ["day", 86_400],
    ["hour", 3_600],
    ["minute", 60],
    ["second", 1],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  for (const [unit, seconds] of units) {
    if (Math.abs(diffSeconds) >= seconds || unit === "second") {
      return rtf.format(Math.round(diffSeconds / seconds), unit);
    }
  }
  return "";
}
