/**
 * format.ts — helpers for formatting prices and dates.
 * Uses the built-in Intl APIs, so no external dependencies are needed.
 */

export type Locale = string;

/* -------------------------------------------------------------------------- */
/*                                   Prices                                   */
/* -------------------------------------------------------------------------- */

export interface FormatPriceOptions {
  /** BCP 47 locale tag. Defaults to "en-US". */
  locale?: Locale;
  /** ISO 4217 currency code. Defaults to "USD". */
  currency?: string;
  /** Hide ".00" when the amount is a whole number. Defaults to false. */
  trimWholeNumbers?: boolean;
}

/**
 * Format a number as a currency string.
 *
 * formatPrice(1234.5)                                  // "$1,234.50"
 * formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }) // "1.234,50 €"
 * formatPrice(10, { trimWholeNumbers: true })          // "$10"
 */
export function formatPrice(
  amount: number,
  { locale = "en-US", currency = "USD", trimWholeNumbers = false }: FormatPriceOptions = {}
): string {
  if (!Number.isFinite(amount)) return "";

  const isWhole = Number.isInteger(amount);
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    ...(trimWholeNumbers && isWhole
      ? { minimumFractionDigits: 0, maximumFractionDigits: 0 }
      : {}),
  }).format(amount);
}

/**
 * Format a price given in minor units (e.g. cents).
 *
 * formatPriceFromMinor(1999) // "$19.99"
 */
export function formatPriceFromMinor(
  minor: number,
  options: FormatPriceOptions = {}
): string {
  const { locale = "en-US", currency = "USD" } = options;
  const digits =
    new Intl.NumberFormat(locale, { style: "currency", currency }).resolvedOptions()
      .maximumFractionDigits ?? 2;
  return formatPrice(minor / 10 ** digits, options);
}

/* -------------------------------------------------------------------------- */
/*                                    Dates                                   */
/* -------------------------------------------------------------------------- */

export type DateInput = Date | string | number;

function toDate(input: DateInput): Date | null {
  const date = input instanceof Date ? input : new Date(input);
  return Number.isNaN(date.getTime()) ? null : date;
}

export interface FormatDateOptions {
  locale?: Locale;
  /** Preset style. Defaults to "medium". */
  style?: "short" | "medium" | "long" | "full";
  /** IANA time zone, e.g. "America/New_York". Defaults to the runtime's zone. */
  timeZone?: string;
  /** Include the time of day. Defaults to false. */
  includeTime?: boolean;
}

/**
 * Format a date.
 *
 * formatDate("2024-03-15T12:00:00Z")                       // "Mar 15, 2024"
 * formatDate(new Date(), { style: "full" })                // "Friday, March 15, 2024"
 * formatDate(Date.now(), { includeTime: true })            // "Mar 15, 2024, 2:30 PM"
 */
export function formatDate(
  input: DateInput,
  {
    locale = "en-US",
    style = "medium",
    timeZone,
    includeTime = false,
  }: FormatDateOptions = {}
): string {
  const date = toDate(input);
  if (!date) return "";

  return new Intl.DateTimeFormat(locale, {
    dateStyle: style,
    ...(includeTime ? { timeStyle: "short" as const } : {}),
    ...(timeZone ? { timeZone } : {}),
  }).format(date);
}

/**
 * Format a date relative to now ("3 days ago", "in 2 hours").
 *
 * formatRelativeTime(Date.now() - 3 * 86_400_000) // "3 days ago"
 */
export function formatRelativeTime(
  input: DateInput,
  locale: Locale = "en-US",
  now: DateInput = Date.now()
): string {
  const date = toDate(input);
  const base = toDate(now);
  if (!date || !base) return "";

  const diffSeconds = Math.round((date.getTime() - base.getTime()) / 1000);

  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 31_536_000],
    ["month", 2_592_000],
    ["week", 604_800],
    ["day", 86_400],
    ["hour", 3_600],
    ["minute", 60],
    ["second", 1],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  for (const [unit, secondsInUnit] of units) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return "";
}

/**
 * Format a date as an ISO-8601 calendar date (YYYY-MM-DD) in UTC.
 *
 * toISODate(new Date("2024-03-15T23:59:00Z")) // "2024-03-15"
 */
export function toISODate(input: DateInput): string {
  const date = toDate(input);
  return date ? date.toISOString().slice(0, 10) : "";
}
