## Notes

- Uses `Intl`, so output is locale-aware and handles currency-specific decimals (e.g., JPY has none).
- Invalid input returns `""` rather than throwing, so it is safe in UI rendering. Change this if you prefer errors.
- Date-only strings like `"2024-12-25"` are parsed as UTC; pass `timeZone: "UTC"` to avoid off-by-one-day shifts in negative-offset time zones.
- `dateStyle`/`timeStyle` require TypeScript 4.2+ with `lib` set to `ES2020` or newer.

# Formatting Helpers (`format.ts`)

```typescript
/**
 * Small helpers for formatting prices and dates using the built-in Intl APIs.
 * No external dependencies.
 */

// ---------- Types ----------

export interface FormatPriceOptions {
  /** ISO 4217 currency code. Default: "USD" */
  currency?: string;
  /** BCP 47 locale tag. Default: "en-US" */
  locale?: string;
  /** Treat the input as minor units (e.g. cents). Default: false */
  fromMinorUnits?: boolean;
  /** Hide ".00" on whole amounts. Default: false */
  trimZeroDecimals?: boolean;
}

export type DateInput = Date | string | number;
export type DateStyle = "short" | "medium" | "long" | "full";

export interface FormatDateOptions {
  locale?: string;
  style?: DateStyle;
  /** IANA time zone, e.g. "UTC" or "America/New_York". Default: runtime zone */
  timeZone?: string;
}

// ---------- Internal helpers ----------

function toDate(input: DateInput): Date | null {
  const date = input instanceof Date ? input : new Date(input);
  return Number.isNaN(date.getTime()) ? null : date;
}

// ---------- Prices ----------

/**
 * Formats a number as a currency string.
 *
 * formatPrice(1234.5)                                  // "$1,234.50"
 * formatPrice(1999, { fromMinorUnits: true })          // "$19.99"
 * formatPrice(10, { trimZeroDecimals: true })          // "$10"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 */
export function formatPrice(
  amount: number,
  options: FormatPriceOptions = {}
): string {
  const {
    currency = "USD",
    locale = "en-US",
    fromMinorUnits = false,
    trimZeroDecimals = false,
  } = options;

  if (!Number.isFinite(amount)) return "";

  const formatter = new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
  });

  // Respect the currency's own number of decimals (e.g. JPY = 0, USD = 2)
  const digits = formatter.resolvedOptions().maximumFractionDigits ?? 2;
  const value = fromMinorUnits ? amount / 10 ** digits : amount;

  if (trimZeroDecimals && Number.isInteger(value)) {
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);
  }

  return formatter.format(value);
}

/**
 * Formats a price range, e.g. "$10.00 – $25.00". Returns a single price
 * if both ends are equal.
 */
export function formatPriceRange(
  min: number,
  max: number,
  options: FormatPriceOptions = {}
): string {
  if (min === max) return formatPrice(min, options);
  return `${formatPrice(min, options)} – ${formatPrice(max, options)}`;
}

// ---------- Dates ----------

/**
 * Formats a date using the given style.
 * Returns an empty string for invalid dates.
 *
 * formatDate("2024-03-15T12:00:00Z", { timeZone: "UTC" })                  // "Mar 15, 2024"
 * formatDate(new Date(), { style: "full" })                                 // "Friday, March 15, 2024"
 */
export function formatDate(
  input: DateInput,
  options: FormatDateOptions = {}
): string {
  const { locale = "en-US", style = "medium", timeZone } = options;
  const date = toDate(input);
  if (!date) return "";

  return new Intl.DateTimeFormat(locale, {
    dateStyle: style,
    timeZone,
  }).format(date);
}

/**
 * Formats a date and time together.
 */
export function formatDateTime(
  input: DateInput,
  options: FormatDateOptions = {}
): string {
  const { locale = "en-US", style = "medium", timeZone } = options;
  const date = toDate(input);
  if (!date) return "";

  return new Intl.DateTimeFormat(locale, {
    dateStyle: style,
    timeStyle: "short",
    timeZone,
  }).format(date);
}

/**
 * Formats a date relative to now, e.g. "2 days ago" or "in 3 hours".
 * Pass `now` to make the output deterministic (useful for tests).
 */
export function formatRelativeTime(
  input: DateInput,
  locale = "en-US",
  now: Date = new Date()
): string {
  const date = toDate(input);
  if (!date) return "";

  const diffSeconds = Math.round((date.getTime() - now.getTime()) / 1000);
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
  ];

  for (const [unit, seconds] of units) {
    if (Math.abs(diffSeconds) >= seconds) {
      return rtf.format(Math.round(diffSeconds / seconds), unit);
    }
  }
  return rtf.format(diffSeconds, "second");
}
```

