// format.ts

/** Options for price formatting. */
export interface FormatPriceOptions {
  /** BCP 47 locale tag. Defaults to "en-US". */
  locale?: string;
  /** ISO 4217 currency code. Defaults to "USD". */
  currency?: string;
  /** Treat the input as minor units (e.g. cents) instead of major units. */
  minorUnits?: boolean;
  /** Use compact notation (e.g. $1.2K). */
  compact?: boolean;
}

/** Number of decimal places for a given currency, per Intl. */
function currencyDigits(currency: string, locale: string): number {
  return (
    new Intl.NumberFormat(locale, { style: "currency", currency })
      .resolvedOptions().maximumFractionDigits ?? 2
  );
}

/**
 * Format a number as a currency string.
 *
 * formatPrice(1234.5)                          // "$1,234.50"
 * formatPrice(123450, { minorUnits: true })    // "$1,234.50"
 * formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }) // "1.234,50 €"
 * formatPrice(1500, { compact: true })         // "$1.5K"
 */
export function formatPrice(
  amount: number,
  options: FormatPriceOptions = {}
): string {
  const {
    locale = "en-US",
    currency = "USD",
    minorUnits = false,
    compact = false,
  } = options;

  if (!Number.isFinite(amount)) return "";

  const value = minorUnits
    ? amount / 10 ** currencyDigits(currency, locale)
    : amount;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    ...(compact ? { notation: "compact", maximumFractionDigits: 1 } : {}),
  }).format(value);
}

/** Options for date formatting. */
export interface FormatDateOptions {
  locale?: string;
  /** Preset style. Defaults to "medium". */
  style?: "short" | "medium" | "long" | "full";
  /** IANA time zone, e.g. "UTC" or "America/New_York". Defaults to local. */
  timeZone?: string;
  /** Include the time of day. */
  includeTime?: boolean;
}

/** Convert a Date | string | number into a valid Date, or null. */
function toDate(input: Date | string | number): Date | null {
  const date = input instanceof Date ? input : new Date(input);
  return Number.isNaN(date.getTime()) ? null : date;
}

/**
 * Format a date using Intl.
 *
 * formatDate("2024-03-15T12:00:00Z", { timeZone: "UTC" })
 *   // "Mar 15, 2024"
 * formatDate("2024-03-15T12:00:00Z", { timeZone: "UTC", includeTime: true })
 *   // "Mar 15, 2024, 12:00 PM"
 */
export function formatDate(
  input: Date | string | number,
  options: FormatDateOptions = {}
): string {
  const {
    locale = "en-US",
    style = "medium",
    timeZone,
    includeTime = false,
  } = options;

  const date = toDate(input);
  if (!date) return "";

  return new Intl.DateTimeFormat(locale, {
    dateStyle: style,
    ...(includeTime ? { timeStyle: "short" as const } : {}),
    timeZone,
  }).format(date);
}

/**
 * Format a date relative to now (e.g. "3 days ago", "in 2 hours").
 *
 * formatRelativeTime(new Date(Date.now() - 3 * 86_400_000)) // "3 days ago"
 */
export function formatRelativeTime(
  input: Date | string | number,
  locale = "en-US",
  now: Date = new Date()
): string {
  const date = toDate(input);
  if (!date) return "";

  const diffSeconds = Math.round((date.getTime() - now.getTime()) / 1000);
  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 31_536_000],
    ["month", 2_592_000],
    ["week", 604_800],
    ["day", 86_400],
    ["hour", 3_600],
    ["minute", 60],
    ["second", 1],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  for (const [unit, seconds] of units) {
    if (Math.abs(diffSeconds) >= seconds || unit === "second") {
      return rtf.format(Math.round(diffSeconds / seconds), unit);
    }
  }
  return "";
}
```

