/**
 * Small helpers for formatting prices and dates.
 * Built on the standard Intl APIs, so there are no dependencies.
 */

export type DateInput = Date | string | number;

/* ----------------------------- Prices ----------------------------- */

export interface FormatPriceOptions {
  /** BCP 47 locale tag, e.g. "en-US", "de-DE". Defaults to "en-US". */
  locale?: string;
  /** ISO 4217 currency code. Defaults to "USD". */
  currency?: string;
  /** Hide ".00" on whole amounts. Defaults to false. */
  trimZeroCents?: boolean;
}

/**
 * Format a numeric amount as currency.
 * formatPrice(1234.5)                              // "$1,234.50"
 * formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }) // "1.234,50 €"
 * formatPrice(10, { trimZeroCents: true })         // "$10"
 */
export function formatPrice(
  amount: number,
  { locale = "en-US", currency = "USD", trimZeroCents = false }: FormatPriceOptions = {}
): string {
  if (!Number.isFinite(amount)) return "";

  const isWhole = Number.isInteger(amount);
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: trimZeroCents && isWhole ? 0 : undefined,
    maximumFractionDigits: trimZeroCents && isWhole ? 0 : undefined,
  }).format(amount);
}

/**
 * Format an amount stored in minor units (e.g. cents).
 * formatPriceFromCents(1999) // "$19.99"
 * Assumes a currency with 2 decimal places.
 */
export function formatPriceFromCents(
  cents: number,
  options: FormatPriceOptions = {}
): string {
  return formatPrice(cents / 100, options);
}

/* ------------------------------ Dates ----------------------------- */

function toDate(input: DateInput): Date | null {
  const date = input instanceof Date ? input : new Date(input);
  return Number.isNaN(date.getTime()) ? null : date;
}

/**
 * Format a date for display.
 * formatDate("2024-03-05T12:00:00Z")                  // "Mar 5, 2024"
 * formatDate(new Date(), "en-GB", { dateStyle: "full" })
 * Returns "" for invalid dates.
 */
export function formatDate(
  input: DateInput,
  locale = "en-US",
  options: Intl.DateTimeFormatOptions = { dateStyle: "medium" }
): string {
  const date = toDate(input);
  return date ? new Intl.DateTimeFormat(locale, options).format(date) : "";
}

/**
 * Format a date and time.
 * formatDateTime("2024-03-05T15:30:00Z", "en-US", "UTC") // "Mar 5, 2024, 3:30 PM"
 */
export function formatDateTime(
  input: DateInput,
  locale = "en-US",
  timeZone?: string
): string {
  return formatDate(input, locale, {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone,
  });
}

/**
 * Format a date relative to now.
 * formatRelativeTime(Date.now() - 3600_000) // "1 hour ago"
 * formatRelativeTime(Date.now() + 86400_000) // "tomorrow"
 */
export function formatRelativeTime(
  input: DateInput,
  locale = "en-US",
  now: DateInput = Date.now()
): string {
  const date = toDate(input);
  const base = toDate(now);
  if (!date || !base) return "";

  const diffSeconds = Math.round((date.getTime() - base.getTime()) / 1000);
  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  for (const [unit, seconds] of units) {
    if (Math.abs(diffSeconds) >= seconds) {
      return rtf.format(Math.round(diffSeconds / seconds), unit);
    }
  }
  return rtf.format(diffSeconds, "second");
}
