// format.ts

export type Locale = string; // e.g. "en-US", "de-DE"

/* ---------- Prices ---------- */

export interface FormatPriceOptions {
  locale?: Locale;
  /** Hide decimals when the value is a whole number (e.g. $5 instead of $5.00) */
  trimWholeNumbers?: boolean;
  /** Treat the input as minor units (cents) instead of major units (dollars) */
  fromMinorUnits?: boolean;
}

/**
 * Format a number as a currency string.
 * formatPrice(1234.5, "USD")                          -> "$1,234.50"
 * formatPrice(1234.5, "EUR", { locale: "de-DE" })     -> "1.234,50 €"
 * formatPrice(999, "USD", { fromMinorUnits: true })   -> "$9.99"
 */
export function formatPrice(
  amount: number,
  currency: string = "USD",
  options: FormatPriceOptions = {}
): string {
  const { locale = "en-US", trimWholeNumbers = false, fromMinorUnits = false } = options;

  if (!Number.isFinite(amount)) return "";

  const formatter = new Intl.NumberFormat(locale, { style: "currency", currency });
  const digits = formatter.resolvedOptions().maximumFractionDigits ?? 2;

  const value = fromMinorUnits ? amount / 10 ** digits : amount;
  const isWhole = Number.isInteger(value);

  if (trimWholeNumbers && isWhole) {
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);
  }

  return formatter.format(value);
}

/**
 * Format a price range.
