  min: number,
  max: number,
  currency: string = "USD",
  options: FormatPriceOptions = {}
): string {
  if (min === max) return formatPrice(min, currency, options);
  return `${formatPrice(min, currency, options)} – ${formatPrice(max, currency, options)}`;
}

