}

/**
 * Formats a date and time.
 *
 * formatDateTime("2024-03-15T14:30:00Z", { timeZone: "UTC" }) // "Mar 15, 2024, 2:30 PM"
 */
export function formatDateTime(
  input: DateInput,
  options: { locale?: string; timeZone?: string } = {}
): string {
  const { locale = "en-US", timeZone } = options;
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone,
  }).format(toDate(input));
}

/**
 * Formats a date as a relative time string.
 *
 * formatRelativeDate(Date.now() - 3 * 60 * 60 * 1000) // "3 hours ago"
 * formatRelativeDate(Date.now() + 86_400_000)         // "tomorrow"
 */
export function formatRelativeDate(
  input: DateInput,
  { locale = "en-US", now = Date.now() }: { locale?: string; now?: DateInput } = {}
): string {
  const diffSeconds = (toDate(input).getTime() - toDate(now).getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
  ];

  for (const [unit, secondsInUnit] of units) {
    if (Math.abs(diffSeconds) >= secondsInUnit) {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return rtf.format(Math.round(diffSeconds), "second");
}
