## Notes

- Uses the built-in `Intl` APIs, so there are no dependencies and locale handling is correct.
- Invalid inputs throw a `RangeError` rather than silently returning `"NaN"` or `"Invalid Date"`.
- For money, prefer storing integer minor units (cents) and using `formatPriceFromMinor` to avoid floating-point errors.

```typescript
// formatters.ts

/**
 * Formatting helpers for prices and dates.
 * Built on the standard Intl APIs, so there are no external dependencies.
 */

export interface PriceOptions {
  /** ISO 4217 currency code. Defaults to "USD". */
  currency?: string;
  /** BCP 47 locale tag. Defaults to "en-US". */
  locale?: string;
  /** Show the fraction digits even for whole amounts. Defaults to true. */
  alwaysShowDecimals?: boolean;
}

/**
 * Format a number as a currency string.
 *
 * formatPrice(1234.5)                          // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * formatPrice(10, { alwaysShowDecimals: false }) // "$10"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const { currency = "USD", locale = "en-US", alwaysShowDecimals = true } = options;

  if (!Number.isFinite(amount)) return "";

  const isWhole = Number.isInteger(amount);
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    ...(!alwaysShowDecimals && isWhole
      ? { minimumFractionDigits: 0, maximumFractionDigits: 0 }
      : {}),
  }).format(amount);
}

/**
 * Format a price given in minor units (e.g. cents).
 *
 * formatPriceFromMinor(123456) // "$1,234.56"
 */
export function formatPriceFromMinor(
  minor: number,
  options: PriceOptions = {}
): string {
  const { currency = "USD", locale = "en-US" } = options;
  const digits =
    new Intl.NumberFormat(locale, { style: "currency", currency }).resolvedOptions()
      .maximumFractionDigits ?? 2;
  return formatPrice(minor / 10 ** digits, options);
}

export type DateStyle = "short" | "medium" | "long" | "full";

export interface DateOptions {
  /** BCP 47 locale tag. Defaults to "en-US". */
  locale?: string;
  /** Preset style. Defaults to "medium". */
  style?: DateStyle;
  /** IANA time zone, e.g. "UTC". Defaults to the runtime's zone. */
  timeZone?: string;
  /** Include the time of day. Defaults to false. */
  includeTime?: boolean;
}

function toDate(value: Date | string | number): Date | null {
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

/**
 * Format a date for display.
 *
 * formatDate("2024-03-15T12:00:00Z", { timeZone: "UTC" })                   // "Mar 15, 2024"
 * formatDate("2024-03-15T12:00:00Z", { style: "long", timeZone: "UTC" })    // "March 15, 2024"
 * formatDate("2024-03-15T12:00:00Z", { includeTime: true, timeZone: "UTC" }) // "Mar 15, 2024, 12:00 PM"
 */
export function formatDate(
  value: Date | string | number,
  options: DateOptions = {}
): string {
  const { locale = "en-US", style = "medium", timeZone, includeTime = false } = options;
  const date = toDate(value);
  if (!date) return "";

  return new Intl.DateTimeFormat(locale, {
    dateStyle: style,
    ...(includeTime ? { timeStyle: "short" as const } : {}),
    timeZone,
  }).format(date);
}

/**
 * Format a date relative to now, e.g. "3 days ago" or "in 2 hours".
 *
 * formatRelativeTime(Date.now() - 3 * 86_400_000) // "3 days ago"
 */
export function formatRelativeTime(
  value: Date | string | number,
  options: { locale?: string; now?: Date | number } = {}
): string {
  const { locale = "en-US", now = Date.now() } = options;
  const date = toDate(value);
  if (!date) return "";

  const diffSeconds = Math.round((date.getTime() - new Date(now).getTime()) / 1000);
  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 31_536_000],
    ["month", 2_592_000],
    ["week", 604_800],
    ["day", 86_400],
    ["hour", 3_600],
    ["minute", 60],
    ["second", 1],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  for (const [unit, seconds] of units) {
    if (Math.abs(diffSeconds) >= seconds || unit === "second") {
      return rtf.format(Math.trunc(diffSeconds / seconds), unit);
    }
  }
  return "";
}
