  amount: number,
  options: FormatPriceOptions = {}
): string {
  const { currency = "USD", locale = "en-US", alwaysShowDecimals = true } = options;

  if (!Number.isFinite(amount)) {
    throw new RangeError(`formatPrice: invalid amount "${amount}"`);
  }

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: alwaysShowDecimals ? undefined : 0,
  }).format(amount);
}

/**
 * Formats a price given in minor units (e.g. cents).
 *
 * formatPriceFromMinor(123456) // "$1,234.56"
 */
