  minorUnits: number,
  options: FormatPriceOptions = {}
): string {
  const { currency = "USD", locale = "en-US" } = options;
  const digits =
    new Intl.NumberFormat(locale, { style: "currency", currency })
      .resolvedOptions().maximumFractionDigits ?? 2;
  return formatPrice(minorUnits / 10 ** digits, options);
}

/** Accepted date inputs. */
export type DateInput = Date | string | number;

function toDate(input: DateInput): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: "${String(input)}"`);
  }
  return date;
}

/**
 * Formats a date using a preset style.
 *
 * formatDate("2024-03-15T12:00:00Z")                  // "Mar 15, 2024"
 * formatDate("2024-03-15T12:00:00Z", "long")          // "March 15, 2024"
 * formatDate("2024-03-15T12:00:00Z", "short", "en-GB") // "15/03/2024"
 */
export function formatDate(
  input: DateInput,
  style: "short" | "medium" | "long" = "medium",
  locale = "en-US",
  timeZone?: string
): string {
  const presets: Record<string, Intl.DateTimeFormatOptions> = {
    short: { year: "numeric", month: "2-digit", day: "2-digit" },
    medium: { year: "numeric", month: "short", day: "numeric" },
    long: { year: "numeric", month: "long", day: "numeric" },
  };

  return new Intl.DateTimeFormat(locale, { ...presets[style], timeZone }).format(
    toDate(input)
  );
}

/**
 * Formats a date relative to now (e.g. "3 days ago", "in 2 hours").
 *
 * formatRelativeTime(Date.now() - 3 * 86_400_000) // "3 days ago"
 */
export function formatRelativeTime(
  input: DateInput,
  locale = "en-US",
  now: DateInput = Date.now()
): string {
  const diffSeconds = Math.round(
    (toDate(input).getTime() - toDate(now).getTime()) / 1000
  );

  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 31_536_000],
    ["month", 2_592_000],
    ["week", 604_800],
    ["day", 86_400],
    ["hour", 3_600],
    ["minute", 60],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, seconds] of units) {
    if (Math.abs(diffSeconds) >= seconds) {
      return rtf.format(Math.round(diffSeconds / seconds), unit);
    }
  }
  return rtf.format(diffSeconds, "second");
}
