  return new Intl.DateTimeFormat(locale, { dateStyle: style, timeZone }).format(
    date
  );
}

/**
 * Format a date with its time.
 * formatDateTime("2024-03-15T15:30:00Z", "en-US", "UTC") -> "Mar 15, 2024, 3:30 PM"
 */
export function formatDateTime(
  input: DateInput,
  locale = "en-US",
  timeZone?: string
): string {
  const date = toDate(input);
  if (!date) return "";
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone,
  }).format(date);
}

/**
 * Format a date relative to now.
 * formatRelativeTime(Date.now() - 3600_000) -> "1 hour ago"
 */
export function formatRelativeTime(
  input: DateInput,
  locale = "en-US",
  now: Date = new Date()
): string {
  const date = toDate(input);
  if (!date) return "";

  const diffSeconds = Math.round((date.getTime() - now.getTime()) / 1000);
  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  for (const [unit, secondsInUnit] of units) {
    if (Math.abs(diffSeconds) >= secondsInUnit) {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return rtf.format(diffSeconds, "second");
}

/**
 * Format as ISO date (YYYY-MM-DD) in UTC, useful for APIs and inputs.
 */
export function formatISODate(input: DateInput): string {
  const date = toDate(input);
  return date ? date.toISOString().slice(0, 10) : "";
}
```

