```typescript
import {
  formatPrice,
  formatPriceFromCents,
  formatDate,
  formatRelativeTime,
} from "./formatters";

formatPrice(1234.5);                                    // "$1,234.50"
formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }); // "1.234,50 €"
formatPriceFromCents(999);                              // "$9.99"
formatDate("2024-03-15T12:00:00Z");                     // "Mar 15, 2024"
formatRelativeTime(Date.now() - 2 * 86_400_000);        // "2 days ago"
```

