Here is a clean, self-contained React component using functional components and the `useState` hook to handle the follow/unfollow state.

```jsx
import React, { useState } from 'react';

const UserCard = ({ name, avatarUrl, initialFollowing = false, onFollowToggle }) => {
  const [isFollowing, setIsFollowing] = useState(initialFollowing);

  const handleFollowClick = () => {
    const newFollowingState = !isFollowing;
    setIsFollowing(newFollowingState);
    if (onFollowToggle) {
      onFollowToggle(newFollowingState);
    }
  };

  return (
    <div style={styles.card}>
      <img
        src={avatarUrl}
        alt={`${name}'s avatar`}
        style={styles.avatar}
      />
      <span style={styles.name}>{name}</span>
      <button
        onClick={handleFollowClick}
        style={{
          ...styles.button,
          ...(isFollowing ? styles.followingButton : styles.followButton),
        }}
      >
        {isFollowing ? 'Following' : 'Follow'}
      </button>
    </div>
  );
};

const styles = {
  card: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    padding: '12px 16px',
    border: '1px solid #e1e4e8',
    borderRadius: '8px',
    maxWidth: '300px',
    fontFamily: 'sans-serif',
  },
  avatar: {
    width: '48px',
    height: '48px',
    borderRadius: '50%',
    objectFit: 'cover',
  },
  name: {
    fontWeight: '600',
    fontSize: '16px',
    flex: 1,
    color: '#24292e',
  },
  button: {
    padding: '6px 14px',
    borderRadius: '6px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
    border: '1px solid',
    transition: 'all 0.2s ease',
  },
  followButton: {
    backgroundColor: '#0095f6',
    color: '#ffffff',
    borderColor: '#0095f6',
  },
  followingButton: {
    backgroundColor: '#ffffff',
    color: '#24292e',
    borderColor: '#d1d5da',
  },
};

export default UserCard;
```

