```ts
// formatters.ts

export interface PriceFormatOptions {
  currency?: string;
  locale?: string;
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
}

export interface DateFormatOptions extends Intl.DateTimeFormatOptions {
  locale?: string;
}

/**
 * Formats a numeric amount into a localized currency string.
 */
export function formatPrice(
  amount: number,
  options: PriceFormatOptions = {}
): string {
  const {
    currency = 'USD',
    locale = 'en-US',
    minimumFractionDigits,
    maximumFractionDigits,
  } = options;

  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

/**
 * Formats a Date object, ISO string, or timestamp into a localized date string.
 */
export function formatDate(
  date: Date | string | number,
  options: DateFormatOptions = {}
): string {
  const { locale = 'en-US', ...intlOptions } = options;
  const parsedDate = date instanceof Date ? date : new Date(date);

  if (Number.isNaN(parsedDate.getTime())) {
    throw new Error(`Invalid date provided: ${String(date)}`);
  }

  const defaultOptions: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  };

  return new Intl.DateTimeFormat(
    locale,
    Object.keys(intlOptions).length > 0 ? intlOptions : defaultOptions
  ).format(parsedDate);
}

/**
 * Formats a date relative to the current time (e.g., "2 days ago", "in 3 hours").
 */
export function formatRelativeDate(
  date: Date | string | number,
  locale = 'en-US'
): string {
  const parsedDate = date instanceof Date ? date : new Date(date);

  if (Number.isNaN(parsedDate.getTime())) {
    throw new Error(`Invalid date provided: ${String(date)}`);
  }

  const diffInSeconds = Math.round((parsedDate.getTime() - Date.now()) / 1000);
  const absSeconds = Math.abs(diffInSeconds);

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: 'auto' });

  const units: { unit: Intl.RelativeTimeFormatUnit; seconds: number }[] = [
    { unit: 'year', seconds: 31536000 },
    { unit: 'month', seconds: 2592000 },
    { unit: 'week', seconds: 604800 },
    { unit: 'day', seconds: 86400 },
    { unit: 'hour', seconds: 3600 },
    { unit: 'minute', seconds: 60 },
    { unit: 'second', seconds: 1 },
  ];

  for (const { unit, seconds } of units) {
    if (absSeconds >= seconds || unit === 'second') {
      const value = Math.round(diffInSeconds / seconds);
      return rtf.format(value, unit);
    }
  }

  return rtf.format(0, 'second');
}
