    format = { dateStyle: "medium" },
  }: DateOptions = {},
): string {
  const date = value instanceof Date ? value : new Date(value);

  if (Number.isNaN(date.getTime())) {
    throw new TypeError("Invalid date value.");
  }

  return new Intl.DateTimeFormat(locale, format).format(date);
}
