/**
 * Helper functions for formatting prices and dates.
 */

/** Format a number as a currency price, e.g. 1234.5 -> "$1,234.50" */
export function formatPrice(
  amount: number,
  currency: string = "USD",
  locale: string = "en-US"
): string {
  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid price: ${amount}`);
  }
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
  }).format(amount);
}

/** Format cents (integer) as a currency price, e.g. 123450 -> "$1,234.50" */
export function formatCents(
  cents: number,
  currency: string = "USD",
  locale: string = "en-US"
): string {
  return formatPrice(cents / 100, currency, locale);
}

/** Parse a price string back to a number, e.g. "$1,234.50" -> 1234.5 */
export function parsePrice(formatted: string): number {
  const cleaned = formatted.replace(/[^0-9.-]/g, "");
  const value = Number.parseFloat(cleaned);
  if (Number.isNaN(value)) {
    throw new Error(`Cannot parse price: ${formatted}`);
  }
  return value;
}

/** Format a date as a short locale date, e.g. "2024-06-15" -> "6/15/2024" (en-US) */
export function formatDate(
  date: Date | string | number,
  locale: string = "en-US"
): string {
  return new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "short",
    day: "numeric",
  }).format(new Date(date));
}

/** Format a date with time, e.g. "Jun 15, 2024, 3:30 PM" */
export function formatDateTime(
  date: Date | string | number,
  locale: string = "en-US",
  timeZone: string | undefined = undefined
): string {
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone,
  }).format(new Date(date));
}

/** Relative time from now, e.g. "3 days ago" */
export function formatRelativeTime(
  date: Date | string | number,
  now: Date = new Date(),
  locale: string = "en-US"
): string {
  const diffMs = new Date(date).getTime() - now.getTime();
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 31536000000],
    ["month", 2592000000],
    ["day", 86400000],
    ["hour", 3600000],
    ["minute", 60000],
  ];

  for (const [unit, ms] of units) {
    const value = Math.round(diffMs / ms);
    if (Math.abs(value) >= 1) {
      return rtf.format(-value, unit); // note: rtf counts backwards from now
    }
  }
  return rtf.format(0, "minute");
}
```

