  date: Date | string | number,
  locale: string = "en-US",
  options: Intl.DateTimeFormatOptions = { dateStyle: "medium" }
): string {
  return new Intl.DateTimeFormat(locale, options).format(new Date(date));
}

/** Format a date and time, e.g. "Jan 5, 2025, 3:45 PM". */
export function formatDateTime(
  date: Date | string | number,
  locale: string = "en-US"
): string {
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(new Date(date));
}

/** Format a date as a relative time string, e.g. "3 days ago". */
export function formatRelativeTime(
  date: Date | string | number,
  now: Date = new Date()
): string {
  const target = new Date(date);
  const diffMs = target.getTime() - now.getTime();
  const rtf = new Intl.RelativeTimeFormat("en", { numeric: "auto" });

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 365 * 24 * 60 * 60 * 1000],
    ["month", 30 * 24 * 60 * 60 * 1000],
    ["day", 24 * 60 * 60 * 1000],
    ["hour", 60 * 60 * 1000],
    ["minute", 60 * 1000],
  ];

  for (const [unit, ms] of units) {
    if (Math.abs(diffMs) >= ms) {
      return rtf.format(Math.round(diffMs / ms), unit);
    }
  }
  return rtf.format(Math.round(diffMs / 1000), "second");
}

/** Format a date as ISO date only, e.g. "2025-01-05". */
export function toISODate(date: Date | string | number): string {
  return new Date(date).toISOString().slice(0, 10);
}
