  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date input: ${String(input)}`);
  }
  return date;
}

/**
 * Format a date as a localized string.
 *
 * formatDate("2024-03-15") // "3/15/2024" (en-US)
 */
