/** Options for price formatting */
export interface PriceFormatOptions {
  currency?: string;
  locale?: string;
  /** Show trailing zeros, e.g. "$5.00" instead of "$5" */
  showCents?: boolean;
}

/**
 * Format a number as a currency string.
 * @example
