 * formatPrice(1234.5, { showCents: false }); // "$1,235"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }); // "1.234,50 €"
 */
export function formatPrice(
  amount: number,
  {
    currency = "USD",
    locale = "en-US",
    showCents = true,
  }: PriceFormatOptions = {}
): string {
  if (!Number.isFinite(amount)) {
    throw new Error(`Invalid price: ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: showCents ? 2 : 0,
    maximumFractionDigits: showCents ? 2 : 0,
  }).format(amount);
}

/**
 * Format a date as a localized string.
 * @example
 * formatDate(new Date("2024-06-15")); // "Jun 15, 2024"
 */
export function formatDate(
  date: Date | string | number,
  locale = "en-US",
  options: Intl.DateTimeFormatOptions = {
    year: "numeric",
    month: "short",
    day: "numeric",
  }
): string {
  const d = new Date(date);
  if (Number.isNaN(d.getTime())) {
    throw new Error(`Invalid date: ${date}`);
  }
  return new Intl.DateTimeFormat(locale, options).format(d);
}

/**
 * Format a date + time together.
 * @example
 * formatDateTime(new Date("2024-06-15T14:30:00Z")); // "Jun 15, 2024, 2:30 PM"
 */
export function formatDateTime(
  date: Date | string | number,
  locale = "en-US"
): string {
  return formatDate(date, locale, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

/**
 * Format a date as a relative time string ("3 days ago").
 * @example
 * formatRelativeTime(Date.now() - 86400000); // "yesterday" / "1 day ago"
 */
export function formatRelativeTime(
  date: Date | string | number,
  locale = "en-US"
): string {
  const d = new Date(date);
  if (Number.isNaN(d.getTime())) {
    throw new Error(`Invalid date: ${date}`);
  }
  const diffSeconds = Math.round((d.getTime() - Date.now()) / 1000);
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 31536000],
    ["month", 2592000],
    ["day", 86400],
    ["hour", 3600],
    ["minute", 60],
    ["second", 1],
  ];

  for (const [unit, seconds] of units) {
    if (Math.abs(diffSeconds) >= seconds || unit === "second") {
      return rtf.format(Math.round(diffSeconds / seconds), unit);
    }
  }
  return rtf.format(0, "second");
}
