/**
 * Formatting helpers for prices and dates.
 */

// ---------- Prices ----------

/** Format a number as a currency string (default: USD). */
export function formatPrice(
  amount: number,
  currency: string = "USD",
  locale: string = "en-US"
): string {
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
  }).format(amount);
}

/** Format cents (integer) as a currency string, e.g. 1999 -> "$19.99". */
export function formatCents(
  cents: number,
  currency: string = "USD",
  locale: string = "en-US"
): string {
  return formatPrice(cents / 100, currency, locale);
}

/** Format a price range, collapsing when both ends are equal. */
export function formatPriceRange(
  min: number,
  max: number,
  currency: string = "USD",
  locale: string = "en-US"
): string {
  if (min === max) return formatPrice(min, currency, locale);
  return `${formatPrice(min, currency, locale)} – ${formatPrice(max, currency, locale)}`;
}

/** Format as a compact price for large values, e.g. 1_200_000 -> "$1.2M". */
export function formatCompactPrice(
  amount: number,
  currency: string = "USD",
  locale: string = "en-US"
): string {
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(amount);
}

// ---------- Dates ----------

type DateInput = Date | string | number;

function toDate(input: DateInput): Date {
  return input instanceof Date ? input : new Date(input);
}

/** Format a date as a localized string, e.g. "Jan 5, 2025". */
export function formatDate(
  input: DateInput,
  locale: string = "en-US",
  options: Intl.DateTimeFormatOptions = { dateStyle: "medium" }
): string {
  return new Intl.DateTimeFormat(locale, options).format(toDate(input));
}

/** Format date + time, e.g. "Jan 5, 2025, 3:45 PM". */
export function formatDateTime(input: DateInput, locale: string = "en-US"): string {
  return formatDate(input, locale, { dateStyle: "medium", timeStyle: "short" });
}

/** Relative-time formatting: "3 days ago", "in 2 months". */
export function formatRelativeTime(input: DateInput, now: Date = new Date()): string {
  const diffMs = toDate(input).getTime() - now.getTime();
  const rtf = new Intl.RelativeTimeFormat("en", { numeric: "auto" });

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 365 * 24 * 60 * 60 * 1000],
    ["month", 30 * 24 * 60 * 60 * 1000],
    ["day", 24 * 60 * 60 * 1000],
    ["hour", 60 * 60 * 1000],
    ["minute", 60 * 1000],
    ["second", 1000],
  ];

  for (const [unit, ms] of units) {
    if (Math.abs(diffMs) >= ms || unit === "second") {
      return rtf.format(Math.round(diffMs / ms), unit);
    }
  }
  return rtf.format(0, "second");
}
```

