// formatters.ts

/**
 * Formats a number as a currency price string.
 * @param amount - The numeric amount (e.g. 1234.5)
 * @param currency - ISO currency code (default: "USD")
 */
export function formatPrice(amount: number, currency: string = "USD"): string {
  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid amount: ${amount}`);
  }
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
  }).format(amount);
}

/**
 * Formats a date as a human-readable string.
 * @param date - Date, timestamp, or ISO string
 * @param locale - BCP 47 locale tag (default: "en-US")
 */
export function formatDate(
  date: Date | string | number,
  locale: string = "en-US"
): string {
  const d = new Date(date);
  if (Number.isNaN(d.getTime())) {
    throw new RangeError(`Invalid date: ${date}`);
  }
  return new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "long",
    day: "numeric",
  }).format(d);
}

/**
 * Formats a date with time included.
 * @param date - Date, timestamp, or ISO string
 * @param locale - BCP 47 locale tag (default: "en-US")
 */
export function formatDateTime(
  date: Date | string | number,
  locale: string = "en-US"
): string {
  const d = new Date(date);
  if (Number.isNaN(d.getTime())) {
    throw new RangeError(`Invalid date: ${date}`);
  }
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(d);
}

/**
 * Formats a date as a relative time string (e.g. "3 days ago").
 * @param date - Date, timestamp, or ISO string
 * @param now - Reference point (default: current time)
 */
export function formatRelativeTime(
  date: Date | string | number,
  now: Date = new Date()
): string {
  const d = new Date(date);
  const diffMs = d.getTime() - now.getTime();
  const diffSec = Math.round(diffMs / 1000);
  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
  ];

  const abs = Math.abs(diffSec);
  if (abs < 60) return "just now";

  const rtf = new Intl.RelativeTimeFormat("en", { numeric: "auto" });
  for (const [unit, seconds] of units) {
    if (abs >= seconds) {
      return rtf.format(Math.round(diffSec / seconds), unit);
    }
  }
  return rtf.format(diffSec, "second");
}
