# useOnlineStatus.ts

```tsx
import { useEffect, useState } from "react";

/**
 * Tracks whether the browser is online or offline.
 * Listens to the browser's `online` and `offline` events
 * and keeps state in sync.
 */
export function useOnlineStatus(): boolean {
  const [isOnline, setIsOnline] = useState<boolean>(
    typeof navigator !== "undefined" ? navigator.onLine : true
  );

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  return isOnline;
}
```

## Usage

```tsx
import { useOnlineStatus } from "./useOnlineStatus";

function StatusBanner() {
  const isOnline = useOnlineStatus();

  return (
    <div>
      {isOnline ? "🟢 You are online" : "🔴 You are offline"}
    </div>
  );
}
```

## Notes

- The initial state comes from `navigator.onLine`, so it's correct on first render.
- Event listeners are added once on mount and cleaned up on unmount.
- The `typeof navigator !== "undefined"` guard makes it safe for SSR environments (e.g., Next.js), where `navigator` doesn't exist on the server.
- Caveat: `navigator.onLine` and these events reflect network *connectivity*, not actual internet access — the browser may report "online" while the connection is down. For a reliable check, ping a known endpoint (e.g., a `fetch` to your API health route).

