  const isOnline = useOnlineStatus();

  if (isOnline) return null;

  return <div className="banner">You are offline. Changes won't be saved.</div>;
}
```

## Notes

- The `online` and `offline` events fire on `window` when the browser's connection status changes, so we subscribe to both and clean up on unmount.
- The `typeof navigator` check makes it safe to run during server-side rendering (e.g., Next.js), defaulting to `true` on the server.
- If you're on **React 18+**, you can make this concurrent-rendering-safe with `useSyncExternalStore`:

```jsx
import { useSyncExternalStore } from 'react';

function subscribe(callback) {
  window.addEventListener('online', callback);
  window.addEventListener('offline', callback);
  return () => {
    window.removeEventListener('online', callback);
    window.removeEventListener('offline', callback);
  };
}

export default function useOnlineStatus() {
  return useSyncExternalStore(
    subscribe,
    () => navigator.onLine,
    () => true // server snapshot
  );
}
```

The `useSyncExternalStore` version reads directly from `navigator.onLine` (the source of truth) rather than mirroring it in state, which avoids tearing during concurrent renders.

Here's a ready-to-run React component that displays a user's avatar, name, and a follow button with optimistic UI updates.
```tsx
import { useCallback, useState } from 'react';
import './UserCard.css';

export interface User {
  id: string;
  name: string;
  username?: string;
  avatarUrl?: string;
}

interface UserCardProps {
  user: User;
  /** Initial follow state. Uncontrolled after mount. */
  initialFollowing?: boolean;
  /** Called with the *next* state. Throw/reject to roll back the optimistic update. */
  onFollowChange?: (userId: string, isFollowing: boolean) => void | Promise<void>;
}

function getInitials(name: string): string {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? '')
    .join('');
}

export function UserCard({
  user,
  initialFollowing = false,
  onFollowChange,
}: UserCardProps) {
  const [isFollowing, setIsFollowing] = useState(initialFollowing);
  const [isPending, setIsPending] = useState(false);
  const [imageFailed, setImageFailed] = useState(false);

  const handleToggle = useCallback(async () => {
    if (isPending) return;

    const next = !isFollowing;
    setIsFollowing(next); // optimistic
    setIsPending(true);

    try {
      await onFollowChange?.(user.id, next);
    } catch {
      setIsFollowing(!next); // rollback on failure
    } finally {
      setIsPending(false);
    }
  }, [isFollowing, isPending, onFollowChange, user.id]);

  const showImage = Boolean(user.avatarUrl) && !imageFailed;

  return (
    <div className="user-card">
      <div className="user-card__avatar" aria-hidden="true">
        {showImage ? (
          <img
            src={user.avatarUrl}
            alt=""
            loading="lazy"
            onError={() => setImageFailed(true)}
          />
        ) : (
          <span>{getInitials(user.name)}</span>
        )}
      </div>

      <div className="user-card__info">
        <span className="user-card__name" title={user.name}>
          {user.name}
        </span>
        {user.username && (
          <span className="user-card__handle">@{user.username}</span>
        )}
      </div>

      <button
        type="button"
        className={`user-card__follow${isFollowing ? ' is-following' : ''}`}
        onClick={handleToggle}
        aria-pressed={isFollowing}
        aria-busy={isPending}
        disabled={isPending}
      >
        {isFollowing ? 'Following' : 'Follow'}
      </button>
    </div>
  );
}
```

