Here's a ready-to-run React component that displays a user's avatar, name, and a follow button with optimistic UI updates.
```tsx
import { useState } from 'react';
import './UserCard.css';

export interface User {
  id: string;
  name: string;
  username: string;
  avatarUrl?: string;
}

interface UserCardProps {
  user: User;
  initialFollowing?: boolean;
  /** Called when the user toggles follow. Throw/reject to roll back the UI. */
  onFollowChange?: (userId: string, isFollowing: boolean) => Promise<void> | void;
}

export function UserCard({
  user,
  initialFollowing = false,
  onFollowChange,
}: UserCardProps) {
  const [isFollowing, setIsFollowing] = useState(initialFollowing);
  const [isPending, setIsPending] = useState(false);
  const [imageFailed, setImageFailed] = useState(false);

  const initials = user.name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? '')
    .join('');

  const showImage = Boolean(user.avatarUrl) && !imageFailed;

  async function handleToggle() {
    if (isPending) return;

    const next = !isFollowing;
    setIsFollowing(next); // optimistic update
    setIsPending(true);

    try {
      await onFollowChange?.(user.id, next);
    } catch {
      setIsFollowing(!next); // roll back on failure
    } finally {
      setIsPending(false);
    }
  }

  return (
    <div className="user-card">
      <div className="user-card__avatar" aria-hidden="true">
        {showImage ? (
          <img
            src={user.avatarUrl}
            alt=""
            onError={() => setImageFailed(true)}
          />
        ) : (
          <span>{initials || '?'}</span>
        )}
      </div>

      <div className="user-card__info">
        <span className="user-card__name" title={user.name}>
          {user.name}
        </span>
        <span className="user-card__username">@{user.username}</span>
      </div>

      <button
        type="button"
        className={`user-card__button${isFollowing ? ' is-following' : ''}`}
        onClick={handleToggle}
        disabled={isPending}
        aria-pressed={isFollowing}
        aria-busy={isPending}
        aria-label={isFollowing ? `Unfollow ${user.name}` : `Follow ${user.name}`}
      >
        {isFollowing ? 'Following' : 'Follow'}
      </button>
    </div>
  );
}
```
### Follow Button with Optimistic UI

The component keeps the follow state local and updates it immediately when you click, then rolls back if the callback fails.

- **Avatar fallback** — If the image URL is missing or fails to load, it shows the user's initials instead.
- **Optimistic toggle** — Clicking the button flips the label between “Follow” and “Following” right away, while the `onFollowChange` callback runs in the background.
- **Error rollback** — If `onFollowChange` throws or rejects, the button reverts to its previous state.
- **Accessibility** — The button uses `aria-pressed` and `aria-busy` to communicate its state to assistive technology.
---

**Optimization Tip:** You can replace the `User` interface and `onFollowChange` callback with your own data source or API call. The `initialFollowing` prop lets you set the starting state from server data.

# UserCard Component

A self-contained avatar + name + follow button with optimistic updates, a pending state, and an initials fallback if the image fails to load.

## `UserCard.tsx`

```tsx
import { useState } from "react";
import "./UserCard.css";

export interface UserCardProps {
  /** URL of the user's avatar image. */
  avatarUrl?: string;
  /** Display name, e.g. "Ada Lovelace". */
  name: string;
  /** Optional handle shown under the name, e.g. "ada" or "@ada". */
  username?: string;
  /** Whether the viewer already follows this user. */
  initialFollowing?: boolean;
  /** Called with the next follow state. Return a promise to show a pending state. */
  onFollowChange?: (following: boolean) => void | Promise<void>;
}

export default function UserCard({
  avatarUrl,
  name,
  username,
  initialFollowing = false,
  onFollowChange,
}: UserCardProps) {
  const [isFollowing, setIsFollowing] = useState(initialFollowing);
  const [isPending, setIsPending] = useState(false);
  const [imageFailed, setImageFailed] = useState(false);

  const showImage = Boolean(avatarUrl) && !imageFailed;

  async function handleToggle() {
    if (isPending) return;

    const next = !isFollowing;
    setIsFollowing(next); // optimistic update
    setIsPending(true);

    try {
      await onFollowChange?.(next);
    } catch (error) {
      setIsFollowing(!next); // roll back on failure
      console.error("Failed to update follow state:", error);
    } finally {
      setIsPending(false);
    }
  }

  return (
    <div className="user-card">
      {showImage ? (
        <img
          className="user-card__avatar"
          src={avatarUrl}
          alt="" // decorative — the name is already announced
          onError={() => setImageFailed(true)}
        />
      ) : (
        <div className="user-card__avatar user-card__avatar--fallback" aria-hidden="true">
          {getInitials(name)}
        </div>
      )}

      <div className="user-card__info">
        <span className="user-card__name">{name}</span>
        {username && (
          <span className="user-card__username">@{username.replace(/^@/, "")}</span>
        )}
      </div>

      <button
        type="button"
        className={`user-card__button ${isFollowing ? "is-following" : "is-not-following"}`}
        onClick={handleToggle}
        disabled={isPending}
        aria-pressed={isFollowing}
      >
        {isFollowing ? "Following" : "Follow"}
      </button>
    </div>
  );
}

function getInitials(name: string) {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("");
}
```

