```tsx
import { useState } from "react";
import "./UserCard.css";

export interface UserCardProps {
  /** Display name of the user. */
  name: string;
  /** Optional avatar image URL. Falls back to initials when missing or broken. */
  avatarUrl?: string;
  /** Whether the current viewer already follows this user. */
  initialFollowing?: boolean;
  /** Called with the desired next state. Throw/reject to roll back the UI. */
  onFollowChange?: (following: boolean) => void | Promise<void>;
}

function getInitials(name: string): string {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("");
}

export default function UserCard({
  name,
  avatarUrl,
  initialFollowing = false,
  onFollowChange,
}: UserCardProps) {
  const [isFollowing, setIsFollowing] = useState(initialFollowing);
  const [isPending, setIsPending] = useState(false);
  const [imageFailed, setImageFailed] = useState(false);

  const showImage = Boolean(avatarUrl) && !imageFailed;

  async function handleToggle() {
    if (isPending) return;

    const next = !isFollowing;
    setIsFollowing(next); // optimistic update
    setIsPending(true);

    try {
      await onFollowChange?.(next);
    } catch {
      setIsFollowing(!next); // roll back on failure
    } finally {
      setIsPending(false);
    }
  }

  return (
    <div className="user-card">
      <div className="user-card__avatar">
        {showImage ? (
          <img
            className="user-card__image"
            src={avatarUrl}
            alt=""
            onError={() => setImageFailed(true)}
          />
        ) : (
          <span className="user-card__initials" aria-hidden="true">
            {getInitials(name)}
          </span>
        )}
      </div>

      <span className="user-card__name" title={name}>
        {name}
      </span>

      <button
        type="button"
        className={`user-card__button${isFollowing ? " user-card__button--following" : ""}`}
        onClick={handleToggle}
        disabled={isPending}
        aria-pressed={isFollowing}
        aria-label={isFollowing ? `Unfollow ${name}` : `Follow ${name}`}
      >
        {isFollowing ? "Following" : "Follow"}
      </button>
    </div>
  );
}
```
### Interaction & Visual Details

- **Avatar fallback:** If `avatarUrl` is missing or fails to load, the component displays the user's initials instead, keeping the layout stable.
- **Optimistic follow toggle:** Clicking the button immediately updates the label between “Follow” and “Following,” then calls `onFollowChange`. If that callback throws or rejects, the state rolls back automatically.
- **Pending state:** While the callback is running, the button is disabled to prevent duplicate requests.
- **Accessibility:** The button uses `aria-pressed` and a dynamic `aria-label` to announce the current follow state to screen readers.
---

**Optimization Tip:** You can pass a real `avatarUrl` and an async `onFollowChange` handler that calls your API. If the request fails, the component will automatically revert the follow state.

