import { useState, useCallback } from "react";
import "./UserCard.css";

export interface UserCardProps {
  name: string;
  username?: string;
  avatarUrl?: string;
  initialFollowing?: boolean;
  /** Called with the next follow state. Return a promise to show a pending state. */
  onFollowChange?: (following: boolean) => Promise<void> | void;
}

function getInitials(name: string): string {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("");
}

export default function UserCard({
  name,
  username,
  avatarUrl,
  initialFollowing = false,
  onFollowChange,
}: UserCardProps) {
  const [isFollowing, setIsFollowing] = useState(initialFollowing);
  const [isPending, setIsPending] = useState(false);
  const [imageFailed, setImageFailed] = useState(false);

  const handleToggle = useCallback(async () => {
    if (isPending) return;

    const next = !isFollowing;
    setIsFollowing(next); // optimistic update
    setIsPending(true);

    try {
      await onFollowChange?.(next);
    } catch (error) {
      setIsFollowing(!next); // roll back on failure
      console.error("Failed to update follow state:", error);
    } finally {
      setIsPending(false);
    }
  }, [isFollowing, isPending, onFollowChange]);

  const showImage = Boolean(avatarUrl) && !imageFailed;

  return (
    <div className="user-card">
      <div className="user-card__avatar" aria-hidden="true">
        {showImage ? (
          <img
            src={avatarUrl}
            alt=""
            onError={() => setImageFailed(true)}
          />
        ) : (
          <span className="user-card__initials">{getInitials(name)}</span>
        )}
      </div>

      <div className="user-card__info">
        <p className="user-card__name">{name}</p>
        {username && <p className="user-card__username">@{username}</p>}
      </div>

      <button
        type="button"
        className={`user-card__follow-btn${isFollowing ? " is-following" : ""}`}
        onClick={handleToggle}
        disabled={isPending}
        aria-pressed={isFollowing}
        aria-label={isFollowing ? `Unfollow ${name}` : `Follow ${name}`}
      >
        {isPending ? "…" : isFollowing ? "Following" : "Follow"}
      </button>
    </div>
  );
}
```
### Component Logic & Interaction

This component handles the follow state locally while giving you a hook to sync with your backend.

- **Optimistic UI updates** — clicking the button immediately updates the label and `aria-pressed` state, then calls `onFollowChange`. If the promise rejects, the state rolls back automatically.
- **Avatar fallback** — if `avatarUrl` is missing or the image fails to load, the component shows the user's initials instead of a broken image.
- **Accessible button** — the button uses `aria-pressed` and a dynamic `aria-label` so screen readers announce the current follow state.
- **Pending state** — while the async handler is running, the button is disabled and shows an ellipsis to prevent duplicate clicks.
---

**Optimization Tip:** You can replace the `initialFollowing` prop with a value fetched from your API, and make sure `onFollowChange` returns a Promise so the optimistic rollback works correctly.

