Here's a ready-to-run React component that displays a user's avatar, name, and a follow button with optimistic UI updates.
```tsx
import { useCallback, useState } from "react";

export type User = {
  id: string;
  name: string;
  handle?: string;
  avatarUrl?: string;
};

type UserCardProps = {
  user: User;
  defaultFollowing?: boolean;
  /** May be async. If it rejects, the optimistic toggle is rolled back. */
  onFollowChange?: (user: User, isFollowing: boolean) => void | Promise<void>;
  className?: string;
};

function getInitials(name: string) {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("");
}

function Avatar({
  src,
  name,
  size = 48,
}: {
  src?: string;
  name: string;
  size?: number;
}) {
  const [failed, setFailed] = useState(false);
  const showImage = Boolean(src) && !failed;

  return (
    <div
      className="flex shrink-0 items-center justify-center overflow-hidden rounded-full bg-slate-200 text-sm font-semibold text-slate-600 ring-1 ring-black/5"
      style={{ width: size, height: size }}
    >
      {showImage ? (
        // alt="" because the name is already rendered next to it — avoids
        // screen readers announcing the same person twice.
        <img
          src={src}
          alt=""
          width={size}
          height={size}
          loading="lazy"
          onError={() => setFailed(true)}
          className="h-full w-full object-cover"
        />
      ) : (
        <span aria-hidden="true">{getInitials(name)}</span>
      )}
    </div>
  );
}

export default function UserCard({
  user,
  defaultFollowing = false,
  onFollowChange,
  className = "",
}: UserCardProps) {
  const [isFollowing, setIsFollowing] = useState(defaultFollowing);
  const [isPending, setIsPending] = useState(false);

  const toggleFollow = useCallback(async () => {
    if (isPending) return;

    const next = !isFollowing;
    setIsFollowing(next); // optimistic
    setIsPending(true);

    try {
      await onFollowChange?.(user, next);
    } catch {
      setIsFollowing(!next); // roll back on failure
    } finally {
      setIsPending(false);
    }
  }, [isFollowing, isPending, onFollowChange, user]);

  return (
    <div
      className={`flex items-center gap-3 rounded-xl bg-white p-3 shadow-sm ring-1 ring-slate-200 ${className}`}
    >
      <Avatar src={user.avatarUrl} name={user.name} />

      <div className="min-w-0 flex-1">
        <p className="truncate font-semibold text-slate-900">{user.name}</p>
        {user.handle && (
          <p className="truncate text-sm text-slate-500">@{user.handle}</p>
        )}
      </div>

      <button
        type="button"
        onClick={toggleFollow}
        disabled={isPending}
        aria-pressed={isFollowing}
        aria-busy={isPending}
        aria-label={
          isFollowing ? `Unfollow ${user.name}` : `Follow ${user.name}`
        }
        className={`shrink-0 rounded-full px-4 py-1.5 text-sm font-semibold transition-colors disabled:cursor-not-allowed disabled:opacity-60 ${
          isFollowing
            ? "border border-slate-300 bg-white text-slate-700 hover:border-rose-300 hover:text-rose-600"
            : "border border-transparent bg-slate-900 text-white hover:bg-slate-700"
        }`}
      >
        {isFollowing ? "Following" : "Follow"}
      </button>
    </div>
  );
}
```

### Component behavior & usage

Here's how the component handles interactions and what you can pass in.

- **Optimistic follow toggle** — Clicking the button flips the label immediately, then calls `onFollowChange`. If that promise rejects, the state rolls back to its previous value.
- **Avatar fallback** — If the image is missing or fails to load, the avatar shows the user's initials on a neutral background.
- **Accessible controls** — The button exposes `aria-pressed`, `aria-busy`, and a contextual `aria-label` like "Follow Jane Doe" or "Unfollow Jane Doe".
- **Flexible props** — You can control the initial follow state with `defaultFollowing` and pass any async or sync handler to `onFollowChange`.

