/* -------------------------------------------------------------------------- */
/* Shared types                                                               */
/* -------------------------------------------------------------------------- */

/** Anything that can be coerced into a valid `Date`. */
export type DateInput = Date | string | number;

/** BCP 47 language tag, e.g. `"en-US"`, `"de-DE"`. */
export type Locale = string;

/** ISO 4217 currency code, e.g. `"USD"`, `"EUR"`, `"JPY"`. */
export type CurrencyCode = string;

/** Preset width used by `Intl.DateTimeFormat`. */
export type DateStyleName = 'short' | 'medium' | 'long' | 'full';

/* -------------------------------------------------------------------------- */
/* Internals                                                                  */
/* -------------------------------------------------------------------------- */

const numberFormatters = new Map<string, Intl.NumberFormat>();
const dateFormatters = new Map<string, Intl.DateTimeFormat>();
const relativeFormatters = new Map<string, Intl.RelativeTimeFormat>();

/** Constructing `Intl` formatters is expensive, so keep them around. */
function cached<T>(cache: Map<string, T>, key: string, create: () => T): T {
  let value = cache.get(key);
  if (value === undefined) {
    value = create();
    cache.set(key, value);
  }
  return value;
}

/**
 * Coerce a {@link DateInput} into a `Date`.
 *
 * @throws {RangeError} If the input cannot be parsed as a valid date.
 */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}

