  currency?: CurrencyCode;
  /** How to render the currency. Defaults to `"symbol"`. */
  currencyDisplay?: 'symbol' | 'narrowSymbol' | 'code' | 'name';
  /** Render the bare number without any currency marker. Default `false`. */
  hideSymbol?: boolean;
}

export interface PriceOptions extends BasePriceOptions {
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
}

export interface CompactPriceOptions extends BasePriceOptions {
  /** `"short"` → `$1.2K`; `"long"` → `$1.2 thousand`. Default `"short"`. */
  display?: 'short' | 'long';
  maximumFractionDigits?: number;
}

/**
 * Format a monetary amount, e.g. `formatPrice(1234.5)` → `"$1,234.50"`.
 *
 * @example
 * formatPrice(1234.5, { locale: 'de-DE', currency: 'EUR' }); // "1.234,50 €"
 * formatPrice(9.9, { hideSymbol: true });                    // "9.90"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    locale,
    currency = 'USD',
    currencyDisplay = 'symbol',
    hideSymbol = false,
    minimumFractionDigits,
    maximumFractionDigits,
  } = options;

  const key = [
    'price',
    locale,
    currency,
    currencyDisplay,
    hideSymbol,
    minimumFractionDigits,
    maximumFractionDigits,
  ].join('|');

  const formatter = cached(numberFormatters, key, () =>
    new Intl.NumberFormat(locale, {
      style: hideSymbol ? 'decimal' : 'currency',
      currency,
      currencyDisplay,
      minimumFractionDigits,
      maximumFractionDigits,
    }),
  );

  return formatter.format(amount);
}

/**
 * Format a monetary amount in compact notation, e.g. `"$1.2K"`.
 *
 * @example
 * formatCompactPrice(1_250_000);                       // "$1.3M"
 * formatCompactPrice(1_250_000, { display: 'long' });  // "$1.3 million"
 */
export function formatCompactPrice(
  amount: number,
  options: CompactPriceOptions = {},
): string {
  const {
    locale,
    currency = 'USD',
    currencyDisplay = 'symbol',
    hideSymbol = false,
    display = 'short',
    maximumFractionDigits = 1,
  } = options;

  const key = [
    'compact',
    locale,
    currency,
    currencyDisplay,
    hideSymbol,
    display,
    maximumFractionDigits,
  ].join('|');

  const formatter = cached(numberFormatters, key, () =>
    new Intl.NumberFormat(locale, {
      style: hideSymbol ? 'decimal' : 'currency',
      currency,
      currencyDisplay,
      notation: 'compact',
      compactDisplay: display,
      maximumFractionDigits,
    }),
  );

  return formatter.format(amount);
}

/* -------------------------------------------------------------------------- */
/* Dates                                                                      */
/* -------------------------------------------------------------------------- */

export interface DateOptions {
  /** BCP 47 locale tag. Defaults to the runtime locale. */
  locale?: Locale;
  /** Default `"medium"`. */
  dateStyle?: DateStyleName;
  /** Omit for a date-only format. */
  timeStyle?: DateStyleName;
  /** IANA time zone, e.g. `"Europe/Berlin"`. Defaults to the runtime zone. */
  timeZone?: string;
}

/**
 * Format a date (and optionally a time).
 *
 * @example
 * formatDate('2024-03-05');                                  // "Mar 5, 2024"
 * formatDate(Date.now(), { dateStyle: 'full' });             // "Tuesday, March 5, 2024"
 * formatDate(new Date(), { timeStyle: 'short' });            // "3:42 PM"
 */
export function formatDate(input: DateInput, options: DateOptions = {}): string {
  const { locale, dateStyle = 'medium', timeStyle, timeZone } = options;

  const key = ['date', locale, dateStyle, timeStyle, timeZone].join('|');

  const formatter = cached(dateFormatters, key, () =>
    new Intl.DateTimeFormat(locale, { dateStyle, timeStyle, timeZone }),
  );

  return formatter.format(toDate(input));
}

/**
 * Format a date and time together. Shorthand for
 * `formatDate(input, { dateStyle: 'medium', timeStyle: 'short', ...options })`.
 *
 * @example
 * formatDateTime('2024-03-05T15:42:00Z'); // "Mar 5, 2024, 3:42 PM"
 */
export function formatDateTime(input: DateInput, options: DateOptions = {}): string {
  const { dateStyle = 'medium', timeStyle = 'short', ...rest } = options;
  return formatDate(input, { ...rest, dateStyle, timeStyle });
}

export interface RelativeTimeOptions {
  /** BCP 47 locale tag. Defaults to the runtime locale. */
  locale?: Locale;
  /** Reference point. Defaults to `Date.now()`. */
  base?: DateInput;
  /**
   * `"auto"` yields idiomatic phrases like `"yesterday"`;
   * `"always"` yields `"1 day ago"`. Default `"auto"`.
   */
  numeric?: 'always' | 'auto';
}

/** Ordered from smallest to largest; each `limit` is the size of the next unit. */
const RELATIVE_DIVISIONS: ReadonlyArray<{
  limit: number;
  unit: Intl.RelativeTimeFormatUnit;
}> = [
  { limit: 60, unit: 'second' },
  { limit: 60, unit: 'minute' },
  { limit: 24, unit: 'hour' },
  { limit: 7, unit: 'day' },
  { limit: 4.34524, unit: 'week' },
  { limit: 12, unit: 'month' },
  { limit: Number.POSITIVE_INFINITY, unit: 'year' },
];

/**
 * Format a date relative to a reference point.
 *
 * @example
 * formatRelativeTime(Date.now() - 3 * 86_400_000); // "3 days ago"
 * formatRelativeTime('2024-03-05', { base: '2024-03-08' }); // "3 days ago"
 */
export function formatRelativeTime(
  input: DateInput,
  options: RelativeTimeOptions = {},
): string {
  const { locale, base = Date.now(), numeric = 'auto' } = options;

  const key = ['relative', locale, numeric].join('|');
  const formatter = cached(relativeFormatters, key, () =>
    new Intl.RelativeTimeFormat(locale, { numeric }),
  );

  // Signed difference in seconds: negative = past, positive = future.
  let delta = (toDate(input).getTime() - toDate(base).getTime()) / 1000;

  for (const { limit, unit } of RELATIVE_DIVISIONS) {
    if (Math.abs(delta) < limit) {
      return formatter.format(Math.round(delta), unit);
    }
    delta /= limit;
  }

  // Unreachable: the final division has an infinite limit.
  return formatter.format(Math.round(delta), 'year');
}
```
### Formatting Helpers at a Glance

- **Price formatting** — `formatPrice` handles currency symbols, locale-specific separators, and optional decimal precision. `formatCompactPrice` shortens large amounts into readable units like `$1.2K` or `$1.3M`.
- **Date formatting** — `formatDate` and `formatDateTime` accept `Date`, ISO strings, or timestamps, with configurable date/time styles and time zones.
- **Relative time** — `formatRelativeTime` turns a date into phrases like `"3 days ago"` or `"yesterday"`, with an optional reference point.
- **Caching** — All `Intl` formatters are memoized by their option key, so repeated calls with the same settings reuse the same formatter instance.

```typescript
// format.ts

export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD";

export interface PriceOptions {
  currency?: CurrencyCode;
  locale?: string;
  /** Show the currency symbol (default: true) */
  showSymbol?: boolean;
  /** Minimum fraction digits (default: 2) */
  minFractionDigits?: number;
  /** Maximum fraction digits (default: 2) */
  maxFractionDigits?: number;
}

/**
 * Format a numeric amount as a localized price string.
 *
 * @example
 * formatPrice(1234.5)                          // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * formatPrice(9.99, { showSymbol: false })     // "9.99"
 */
export function formatPrice(
  amount: number,
  options: PriceOptions = {}
): string {
  const {
    currency = "USD",
    locale = "en-US",
    showSymbol = true,
    minFractionDigits = 2,
    maxFractionDigits = 2,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: amount must be a finite number, got ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: showSymbol ? "currency" : "decimal",
    currency: showSymbol ? currency : undefined,
    minimumFractionDigits: minFractionDigits,
    maximumFractionDigits: maxFractionDigits,
  }).format(amount);
}

/**
 * Parse a localized price string back into a number.
 * Strips currency symbols and normalizes separators.
 *
 * @example
 * parsePrice("$1,234.50")   // 1234.5
 * parsePrice("1.234,50 €")  // 1234.5
 */
export function parsePrice(input: string): number {
  const cleaned = input
    .replace(/[^\d.,-]/g, "")
    .replace(/\.(?=\d{3}(\D|$))/g, "") // remove thousands dots
    .replace(/,(?=\d{3}(\D|$))/g, "")  // remove thousands commas
    .replace(",", ".");                // decimal comma -> dot

  const value = Number.parseFloat(cleaned);
  if (Number.isNaN(value)) {
    throw new TypeError(`parsePrice: could not parse "${input}"`);
  }
  return value;
}

export type DateStyle = "short" | "medium" | "long" | "full";

export interface DateOptions {
  locale?: string;
  dateStyle?: DateStyle;
  timeStyle?: DateStyle;
  /** Include time in the output (default: false) */
  includeTime?: boolean;
}

/**
 * Format a Date (or ISO string / timestamp) as a localized date string.
 *
 * @example
 * formatDate(new Date("2024-03-15"))                       // "3/15/2024"
 * formatDate("2024-03-15", { dateStyle: "long" })          // "March 15, 2024"
 * formatDate(Date.now(), { includeTime: true })            // "3/15/2024, 2:30 PM"
 */
export function formatDate(
  value: Date | string | number,
  options: DateOptions = {}
): string {
  const {
    locale = "en-US",
    dateStyle = "short",
    timeStyle = "short",
    includeTime = false,
  } = options;

  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`formatDate: invalid date value "${value}"`);
  }

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    ...(includeTime ? { timeStyle } : {}),
  }).format(date);
}

/**
 * Format a date relative to now (e.g. "3 days ago", "in 2 hours").
 *
 * @example
 * formatRelativeDate(Date.now() - 86_400_000) // "yesterday"
 */
export function formatRelativeDate(
  value: Date | string | number,
  locale = "en-US"
): string {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`formatRelativeDate: invalid date value "${value}"`);
  }

  const diffMs = date.getTime() - Date.now();
  const diffSec = Math.round(diffMs / 1000);
  const diffMin = Math.round(diffSec / 60);
  const diffHour = Math.round(diffMin / 60);
  const diffDay = Math.round(diffHour / 24);

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  if (Math.abs(diffSec) < 60) return rtf.format(diffSec, "second");
  if (Math.abs(diffMin) < 60) return rtf.format(diffMin, "minute");
  if (Math.abs(diffHour) < 24) return rtf.format(diffHour, "hour");
  if (Math.abs(diffDay) < 30) return rtf.format(diffDay, "day");

  const diffMonth = Math.round(diffDay / 30);
  if (Math.abs(diffMonth) < 12) return rtf.format(diffMonth, "month");

  return rtf.format(Math.round(diffMonth / 12), "year");
}
