  options: FormatPriceOptions = {},
): string {
  const {
    currency = "USD",
    locale = "en-US",
    minimumFractionDigits = 2,
    maximumFractionDigits = 2,
    showSign = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: amount must be a finite number, got ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits,
    maximumFractionDigits,
    signDisplay: showSign ? "always" : "auto",
  }).format(amount);
}

/**
 * Format a number using a compact, human-friendly suffix.
 *
 * @example
 *   formatCompactPrice(1500)     // "$1.5K"
 *   formatCompactPrice(2_300_000) // "$2.3M"
 */
export function formatCompactPrice(
  amount: number,
  options: Omit<FormatPriceOptions, "minimumFractionDigits" | "maximumFractionDigits"> = {},
): string {
  const { currency = "USD", locale = "en-US" } = options;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(amount);
}

// ---------------------------------------------------------------------------
// Dates
// ---------------------------------------------------------------------------

export interface FormatDateOptions {
  /** BCP 47 locale. Defaults to "en-US". */
  locale?: string;
  /** Optional IANA time zone, e.g. "America/New_York". */
  timeZone?: string;
}

/** Format a date as "MM/DD/YYYY" (or locale equivalent). */
export function formatDate(
  date: Date | string | number,
  options: FormatDateOptions = {},
): string {
  const { locale = "en-US", timeZone } = options;
  return new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    timeZone,
  }).format(toDate(date));
}

/** Format a date with time, e.g. "01/15/2025, 3:45 PM". */
export function formatDateTime(
  date: Date | string | number,
  options: FormatDateOptions = {},
): string {
  const { locale = "en-US", timeZone } = options;
  return new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    timeZone,
  }).format(toDate(date));
}

/** Format a date in a long, readable form, e.g. "January 15, 2025". */
export function formatLongDate(
  date: Date | string | number,
  options: FormatDateOptions = {},
): string {
  const { locale = "en-US", timeZone } = options;
  return new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "long",
    day: "numeric",
    timeZone,
  }).format(toDate(date));
}

/**
 * Return a relative-time string like "3 days ago" or "in 2 hours".
 * `baseDate` defaults to now and is mostly useful for testing.
 */
export function formatRelativeDate(
  date: Date | string | number,
  options: FormatDateOptions & { baseDate?: Date } = {},
): string {
  const { locale = "en-US", baseDate = new Date() } = options;
  const target = toDate(date);
  const diffMs = target.getTime() - baseDate.getTime();
  const diffSeconds = Math.round(diffMs / 1000);

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, secondsPerUnit] of units) {
    if (Math.abs(diffSeconds) >= secondsPerUnit || unit === "second") {
      const value = Math.round(diffSeconds / secondsPerUnit);
      return rtf.format(value, unit);
    }
  }

  // Unreachable, but keeps TypeScript happy.
  return rtf.format(0, "second");
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

function toDate(value: Date | string | number): Date {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`Invalid date: ${String(value)}`);
  }
  return date;
}
