 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * formatPrice(9.99, { showSymbol: false })     // "9.99"
 */
export function formatPrice(
  amount: number,
  options: PriceOptions = {},
): string {
  const {
    currency = "USD",
    locale = "en-US",
    showSymbol = true,
    minimumFractionDigits,
    maximumFractionDigits,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: amount must be a finite number, got ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: showSymbol ? "currency" : "decimal",
    currency: showSymbol ? currency : undefined,
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

/**
 * Parse a localized price string back into a number.
 * Strips currency symbols and normalizes separators.
 *
 * @example
 * parsePrice("$1,234.50")   // 1234.5
 * parsePrice("1.234,50 €")  // 1234.5
 */
export function parsePrice(input: string): number {
  const cleaned = input
    .replace(/[^\d.,-]/g, "")
    .replace(/\.(?=\d{3}\b)/g, "") // remove thousands dots
    .replace(/,(?=\d{3}\b)/g, "")  // remove thousands commas
    .replace(",", ".");            // decimal comma -> dot

  const value = Number.parseFloat(cleaned);
  if (Number.isNaN(value)) {
    throw new TypeError(`parsePrice: could not parse "${input}"`);
  }
  return value;
}

export type DateStyle = "short" | "medium" | "long" | "full";

export interface DateOptions {
  /** BCP 47 locale tag. Defaults to "en-US". */
  locale?: string;
  /** Preset style. Defaults to "medium". */
  dateStyle?: DateStyle;
