 * formatDate("2024-03-15", { dateStyle: "full" })          // "Friday, March 15, 2024"
 * formatDate(Date.now(), { withTime: true })               // "Mar 15, 2024, 2:30 PM"
 */
export function formatDate(
  value: Date | string | number,
  options: DateOptions = {},
): string {
  const {
    locale = "en-US",
    dateStyle = "medium",
    withTime = false,
    timeStyle = "short",
  } = options;

  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`formatDate: invalid date value "${value}"`);
  }

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    ...(withTime ? { timeStyle } : {}),
  }).format(date);
}

/**
 * Format a date as a relative time string (e.g. "3 days ago", "in 2 hours").
 *
 * @example
 * formatRelative(new Date(Date.now() - 86_400_000)) // "yesterday"
 */
export function formatRelative(
  value: Date | string | number,
  baseDate: Date = new Date(),
  locale = "en-US",
): string {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`formatRelative: invalid date value "${value}"`);
  }

  const diffMs = date.getTime() - baseDate.getTime();
  const diffSec = Math.round(diffMs / 1000);
  const diffMin = Math.round(diffSec / 60);
  const diffHr = Math.round(diffMin / 60);
  const diffDay = Math.round(diffHr / 24);

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  if (Math.abs(diffSec) < 60) return rtf.format(diffSec, "second");
  if (Math.abs(diffMin) < 60) return rtf.format(diffMin, "minute");
  if (Math.abs(diffHr) < 24) return rtf.format(diffHr, "hour");
  if (Math.abs(diffDay) < 30) return rtf.format(diffDay, "day");
  if (Math.abs(diffDay) < 365) return rtf.format(Math.round(diffDay / 30), "month");
  return rtf.format(Math.round(diffDay / 365), "year");
}
