- **Locale-aware** — pass any BCP 47 tag (`"en-GB"`, `"ja-JP"`, `"pt-BR"`, etc.).
- **Strict input** — throws on `NaN`/`Infinity` amounts and invalid dates rather than silently producing `"NaN"`.
- **`parsePrice` caveat** — the heuristic handles common US/EU formats but is not a full locale parser. For strict parsing, prefer `Intl.NumberFormat` with a known locale and a dedicated library.

# `format.ts`

A small, dependency-free TypeScript module for formatting prices and dates.

```ts
// format.ts

export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD";

export interface PriceOptions {
  /** ISO 4217 currency code. Defaults to "USD". */
  currency?: CurrencyCode;
  /** BCP 47 locale tag. Defaults to "en-US". */
  locale?: string;
  /** Show the currency symbol. Defaults to true. */
  showSymbol?: boolean;
  /** Minimum fraction digits. Defaults to currency-appropriate value. */
  minimumFractionDigits?: number;
  /** Maximum fraction digits. Defaults to currency-appropriate value. */
  maximumFractionDigits?: number;
}

/**
 * Format a numeric amount as a localized price string.
 *
 * @example
 *   formatPrice(1234.5)                          // "$1,234.50"
 *   formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 *   formatPrice(9.99, { showSymbol: false })     // "9.99"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    currency = "USD",
    locale = "en-US",
    showSymbol = true,
    minimumFractionDigits,
    maximumFractionDigits,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: amount must be a finite number, got ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: showSymbol ? "currency" : "decimal",
    currency,
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

/**
 * Parse a localized price string back into a number.
 * Strips currency symbols and normalizes separators.
 *
 * @example
 *   parsePrice("$1,234.50")   // 1234.5
 *   parsePrice("1.234,50 €")  // 1234.5
 */
export function parsePrice(input: string): number {
  const cleaned = input
    .replace(/[^\d.,-]/g, "") // drop symbols, spaces, letters
    .replace(/\.(?=\d{3}\b)/g, "") // remove thousands dots
    .replace(/,(?=\d{3}\b)/g, "") // remove thousands commas
    .replace(",", "."); // decimal comma -> dot

  const value = Number.parseFloat(cleaned);
  if (Number.isNaN(value)) {
    throw new TypeError(`parsePrice: could not parse "${input}"`);
  }
  return value;
}

// ---------------------------------------------------------------------------
// Dates
// ---------------------------------------------------------------------------

export type DateInput = Date | string | number;

export type DateStyle = "short" | "medium" | "long" | "full";

export interface DateOptions {
  /** BCP 47 locale tag. Defaults to "en-US". */
  locale?: string;
  /** Preset style. Defaults to "medium". */
  style?: DateStyle;
  /** Include time in the output. Defaults to false. */
  withTime?: boolean;
  /** IANA time zone, e.g. "America/New_York". Defaults to runtime zone. */
  timeZone?: string;
}

function toDate(input: DateInput): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`formatDate: invalid date input "${String(input)}"`);
  }
  return date;
}

/**
 * Format a date (and optionally time) using Intl.DateTimeFormat.
 *
 * @example
 *   formatDate("2024-03-15")                       // "Mar 15, 2024"
 *   formatDate(new Date(), { withTime: true })     // "Mar 15, 2024, 2:30 PM"
 *   formatDate("2024-03-15", { style: "full" })    // "Friday, March 15, 2024"
 */
export function formatDate(input: DateInput, options: DateOptions = {}): string {
  const { locale = "en-US", style = "medium", withTime = false, timeZone } = options;
  const date = toDate(input);

  return new Intl.DateTimeFormat(locale, {
    dateStyle: style,
    ...(withTime ? { timeStyle: "short" as const } : {}),
    ...(timeZone ? { timeZone } : {}),
  }).format(date);
}

/**
 * Format a date as a relative time string ("3 days ago", "in 2 hours").
 *
 * @example
 *   formatRelativeDate(Date.now() - 86_400_000) // "yesterday"
 *   formatRelativeDate(Date.now() + 3_600_000)  // "in 1 hour"
 */
export function formatRelativeDate(
  input: DateInput,
  options: { locale?: string; baseDate?: DateInput } = {},
): string {
  const { locale = "en-US", baseDate = new Date() } = options;
  const target = toDate(input);
  const base = toDate(baseDate);

  const diffSeconds = (target.getTime() - base.getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  for (const [unit, secondsInUnit] of units) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return rtf.format(0, "second");
}
