export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY" | "CAD" | "AUD";

export interface PriceOptions {
  currency?: CurrencyCode;
  locale?: string;
  /** Show cents even when they are zero (e.g. $10.00 vs $10). */
  showZeroCents?: boolean;
}

/**
 * Format a numeric amount as a localized price string.
 *
 * @example
 *   formatPrice(1234.5)                          // "$1,234.50"
 *   formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 *   formatPrice(10, { showZeroCents: false })    // "$10"
 */
export function formatPrice(
  amount: number,
  options: PriceOptions = {},
): string {
  const {
    currency = "USD",
    locale = "en-US",
    showZeroCents = true,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: amount must be a finite number, got ${amount}`);
  }

  const fractionDigits = showZeroCents || amount % 1 !== 0 ? 2 : 0;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  }).format(amount);
}

/**
 * Parse a localized price string back into a number.
 * Returns `null` if the input cannot be parsed.
 *
 * @example
 *   parsePrice("$1,234.50")   // 1234.5
 *   parsePrice("1.234,50 €", "de-DE") // 1234.5
 */
export function parsePrice(input: string, locale = "en-US"): number | null {
  const parts = new Intl.NumberFormat(locale).formatToParts(12345.6);
  const group = parts.find((p) => p.type === "group")?.value ?? ",";
  const decimal = parts.find((p) => p.type === "decimal")?.value ?? ".";

  const cleaned = input
    .replace(new RegExp(`\\${group}`, "g"), "")
    .replace(decimal, ".")
    .replace(/[^\d.\-]/g, "");

  const value = Number.parseFloat(cleaned);
  return Number.isFinite(value) ? value : null;
}

