    locale = "en-US",
    dateStyle = "short",
    timeStyle = "short",
    withTime = false,
  } = options;

  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`formatDate: invalid date value: ${String(value)}`);
  }

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    ...(withTime ? { timeStyle } : {}),
