```ts
/**
 * Small formatting helpers for prices and dates.
 * All functions are pure and locale-aware via `Intl`.
 */

// ---------- Prices ----------

export interface PriceOptions {
  /** ISO 4217 currency code, e.g. "USD", "EUR", "JPY". Default: "USD". */
  currency?: string;
  /** BCP 47 locale, e.g. "en-US", "de-DE". Default: "en-US". */
  locale?: string;
  /** Show cents even when they are zero. Default: true. */
  showCents?: boolean;
  /** Use compact notation (e.g. "$1.2K"). Default: false. */
  compact?: boolean;
}

/**
 * Format a numeric amount as a localized currency string.
 *
 * @example
 *   formatPrice(1234.5)                       // "$1,234.50"
 *   formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 *   formatPrice(1234.5, { compact: true })    // "$1.2K"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    currency = "USD",
    locale = "en-US",
    showCents = true,
    compact = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: amount must be a finite number, got ${amount}`);
  }

  const fractionDigits = showCents ? undefined : 0;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
    notation: compact ? "compact" : "standard",
  }).format(amount);
}

/**
 * Parse a user-entered price string into a number.
 * Strips currency symbols, spaces, and thousands separators.
 * Returns `null` if the input cannot be parsed.
 *
 * @example
 *   parsePrice("$1,234.50") // 1234.5
 *   parsePrice("1.234,50 €") // 1234.5  (assumes comma is decimal)
 */
export function parsePrice(input: string): number | null {
  if (typeof input !== "string") return null;

  const cleaned = input
    .replace(/[^\d.,-]/g, "") // drop currency symbols, spaces, letters
    .trim();

  if (!cleaned) return null;

  // Decide which separator is the decimal one: the last one wins.
  const lastComma = cleaned.lastIndexOf(",");
  const lastDot = cleaned.lastIndexOf(".");
  const decimalSep = lastComma > lastDot ? "," : ".";
  const thousandSep = decimalSep === "," ? "." : ",";

  const normalized = cleaned
    .split(thousandSep)
    .join("")
    .replace(decimalSep, ".");

  const value = Number(normalized);
  return Number.isFinite(value) ? value : null;
}

// ---------- Dates ----------

