 * Format a date with a long, human-readable style.
 *
 * @example
 *   formatDateLong("2024-03-15") // "March 15, 2024"
 */
export function formatDateLong(input: DateInput, options: DateOptions = {}): string {
  const { locale = "en-US", timeZone } = options;
  return new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "long",
    day: "numeric",
    timeZone,
