formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }); // "1.234,50 €"
formatPrice(1234.5, { compact: true });                 // "$1.2K"
formatPrice(9.99, { showCents: false });                // "$10"

parsePrice("$1,234.50");                                // 1234.5
parsePrice("1.234,50 €");                               // 1234.5
parsePrice("not a price");                              // null

formatDate("2024-03-15");                               // "3/15/2024"
formatDateLong("2024-03-15");                           // "March 15, 2024"
formatDateTime("2024-03-15T14:30:00Z");                 // "3/15/2024, 2:30 PM"
formatRelativeDate(Date.now() - 3 * 86_400_000);        // "3 days ago"
```

## Notes

- **No dependencies** — everything uses the built-in `Intl` API.
- **Locale-aware** — pass any BCP 47 locale; defaults to `en-US`.
- **Strict inputs** — `formatPrice` throws on non-finite numbers; date helpers throw on invalid dates. `parsePrice` returns `null` instead of throwing, since it's meant for user input.
- **`parsePrice` heuristic** — it assumes the *last* separator (`.` or `,`) is the decimal one, which handles both `1,234.50` and `1.234,50` correctly. If you know the locale up front, you can simplify it by passing the locale's decimal separator explicitly.

Here's a small TypeScript module with helper functions for formatting prices and dates, using the built-in Intl APIs.
```typescript
/**
 * format.ts
 *
 * Small, dependency-free helpers for formatting prices and dates.
 *
 * - Locale-aware via the built-in `Intl` APIs.
 * - Never throws: missing or invalid input returns a fallback string.
 * - `Intl` formatters are cached, so repeated calls are cheap.
 *
 * Requires `lib: ["ES2020"]` (or later) in tsconfig for `Intl.RelativeTimeFormat`.
 */

/* -------------------------------------------------------------------------- */
/* Shared                                                                     */
/* -------------------------------------------------------------------------- */

export type PriceInput = number | string | null | undefined;
export type DateInput = Date | string | number | null | undefined;

const DEFAULT_LOCALE = 'en-US';
const DEFAULT_FALLBACK = '—';

const numberFormats = new Map<string, Intl.NumberFormat>();
const dateFormats = new Map<string, Intl.DateTimeFormat>();
const relativeFormats = new Map<string, Intl.RelativeTimeFormat>();

function memo<T>(cache: Map<string, T>, key: string, create: () => T): T {
  const hit = cache.get(key);
  if (hit !== undefined) return hit;
  const created = create();
  cache.set(key, created);
  return created;
}

function getNumberFormat(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  return memo(numberFormats, `${locale}|${JSON.stringify(options)}`, () => new Intl.NumberFormat(locale, options));
}

function getDateFormat(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  return memo(dateFormats, `${locale}|${JSON.stringify(options)}`, () => new Intl.DateTimeFormat(locale, options));
}

function getRelativeFormat(locale: string, options: Intl.RelativeTimeFormatOptions): Intl.RelativeTimeFormat {
  return memo(relativeFormats, `${locale}|${JSON.stringify(options)}`, () => new Intl.RelativeTimeFormat(locale, options));
}

function toNumber(value: PriceInput): number | null {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value === 'string') {
    const parsed = Number(value.trim());
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

function toDate(value: DateInput): Date | null {
  if (value === null || value === undefined) return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

/* -------------------------------------------------------------------------- */
/* Prices                                                                     */
/* -------------------------------------------------------------------------- */

export interface PriceFormatOptions {
  /** BCP 47 locale tag, e.g. `"en-US"`, `"de-DE"`. Defaults to `"en-US"`. */
  locale?: string;
  /** ISO 4217 currency code, e.g. `"USD"`, `"EUR"`. Defaults to `"USD"`. */
  currency?: string;
  /** Defaults to the currency's standard number of digits. */
  minimumFractionDigits?: number;
  /** Defaults to the currency's standard number of digits. */
  maximumFractionDigits?: number;
  /** Use compact notation: `$1.2K`, `$3.4M`. */
  compact?: boolean;
  /** Prefix positive values with `+`. */
  showSign?: boolean;
  /** Returned when the value is missing or invalid. */
  fallback?: string;
}

/** Formats a number as a currency string, e.g. `"$1,234.50"`. */
export function formatPrice(value: PriceInput, options: PriceFormatOptions = {}): string {
  const {
    locale = DEFAULT_LOCALE,
    currency = 'USD',
    minimumFractionDigits,
    maximumFractionDigits,
    compact = false,
    showSign = false,
    fallback = DEFAULT_FALLBACK,
  } = options;

  const amount = toNumber(value);
  if (amount === null) return fallback;

  return getNumberFormat(locale, {
    style: 'currency',
    currency,
    notation: compact ? 'compact' : 'standard',
    minimumFractionDigits,
    maximumFractionDigits,
    signDisplay: showSign ? 'exceptZero' : 'auto',
  }).format(amount);
}

/** Shorthand for `formatPrice(value, { ...options, compact: true })`. */
export function formatCompactPrice(
  value: PriceInput,
  options: Omit<PriceFormatOptions, 'compact'> = {},
): string {
  return formatPrice(value, { ...options, compact: true });
}

export interface PercentFormatOptions {
  locale?: string;
  /** Digits after the decimal point. Defaults to `1`. */
  fractionDigits?: number;
  fallback?: string;
}

/** Formats a **ratio** as a percentage: `0.256` → `"25.6%"`. */
export function formatPercent(value: number | null | undefined, options: PercentFormatOptions = {}): string {
  const { locale = DEFAULT_LOCALE, fractionDigits = 1, fallback = DEFAULT_FALLBACK } = options;
  if (typeof value !== 'number' || !Number.isFinite(value)) return fallback;

  return getNumberFormat(locale, {
    style: 'percent',
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  }).format(value);
}

export interface ParsePriceOptions {
  /** Force a decimal separator instead of inferring it. */
  decimalSeparator?: ',' | '.';
}

/**
 * Parses a human-entered price string into a number.
 *
 * Ambiguity is resolved with two rules:
 *  - when both `,` and `.` appear, the **last** one is the decimal separator;
 *  - a single separator followed by exactly three digits is treated as a
 *    grouping separator (`"1,234"` → `1234`).
 *
 * Returns `null` when the input cannot be parsed.
 */
export function parsePrice(input: PriceInput, options: ParsePriceOptions = {}): number | null {
  if (typeof input === 'number') return Number.isFinite(input) ? input : null;
  if (typeof input !== 'string') return null;

  const cleaned = input.replace(/[^\d.,-]/g, '');
  if (!cleaned) return null;

  const decimalSep = options.decimalSeparator ?? inferDecimalSeparator(cleaned);

  const normalized = decimalSep
    ? cleaned.split(decimalSep === ',' ? '.' : ',').join('').replace(decimalSep, '.')
    : cleaned.replace(/[.,]/g, '');

  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : null;
}

function inferDecimalSeparator(cleaned: string): ',' | '.' | null {
  const lastComma = cleaned.lastIndexOf(',');
  const lastDot = cleaned.lastIndexOf('.');

  if (lastComma !== -1 && lastDot !== -1) {
    return lastComma > lastDot ? ',' : '.';
  }

  const sep = lastComma !== -1 ? ',' : lastDot !== -1 ? '.' : null;
  if (!sep) return null;

  // Repeated separator → grouping only, e.g. "1.234.567".
  if (cleaned.indexOf(sep) !== cleaned.lastIndexOf(sep)) return null;

  // A single separator followed by exactly three digits → grouping, e.g. "1,234".
  if (/^\d{3}$/.test(cleaned.slice(cleaned.lastIndexOf(sep) + 1))) return null;

  return sep;
}

/* -------------------------------------------------------------------------- */
/* Dates                                                                      */
/* -------------------------------------------------------------------------- */

export interface DateFormatOptions {
  /** BCP 47 locale tag. Defaults to `"en-US"`. */
  locale?: string;
  /** IANA time zone, e.g. `"Europe/Berlin"`. Defaults to the runtime's zone. */
  timeZone?: string;
  /** Returned when the value is missing or invalid. */
  fallback?: string;
}

/** Formats a date, e.g. `"Jan 5, 2025"`. */
export function formatDate(value: DateInput, options: DateFormatOptions = {}): string {
  const { locale = DEFAULT_LOCALE, timeZone, fallback = DEFAULT_FALLBACK } = options;
  const date = toDate(value);
  if (!date) return fallback;

  return getDateFormat(locale, { dateStyle: 'medium', timeZone }).format(date);
}

/** Formats a date and time, e.g. `"Jan 5, 2025, 2:30 PM"`. */
export function formatDateTime(value: DateInput, options: DateFormatOptions = {}): string {
  const { locale = DEFAULT_LOCALE, timeZone, fallback = DEFAULT_FALLBACK } = options;
  const date = toDate(value);
  if (!date) return fallback;

  return getDateFormat(locale, { dateStyle: 'medium', timeStyle: 'short', timeZone }).format(date);
}

/** Formats a date as `YYYY-MM-DD` in **local** time (no UTC shift). */
export function toISODate(value: DateInput): string | null {
  const date = toDate(value);
  if (!date) return null;

  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

export interface RelativeTimeOptions {
  locale?: string;
  /** Reference point. Defaults to `new Date()`. */
  now?: DateInput;
  fallback?: string;
}

type RelativeUnit = 'year' | 'month' | 'week' | 'day' | 'hour' | 'minute' | 'second';

const RELATIVE_UNITS: ReadonlyArray<readonly [RelativeUnit, number]> = [
  ['year', 365 * 24 * 60 * 60 * 1000],
  ['month', 30 * 24 * 60 * 60 * 1000],
  ['week', 7 * 24 * 60 * 60 * 1000],
  ['day', 24 * 60 * 60 * 1000],
  ['hour', 60 * 60 * 1000],
  ['minute', 60 * 1000],
  ['second', 1000],
];

/** Formats a date relative to now, e.g. `"3 days ago"`, `"in 2 hours"`. */
export function formatRelativeTime(value: DateInput, options: RelativeTimeOptions = {}): string {
  const { locale = DEFAULT_LOCALE, now = new Date(), fallback = DEFAULT_FALLBACK } = options;

  const date = toDate(value);
  const reference = toDate(now);
  if (!date || !reference) return fallback;

  const diffMs = date.getTime() - reference.getTime();
  const absMs = Math.abs(diffMs);

  for (const [unit, unitMs] of RELATIVE_UNITS) {
    if (absMs >= unitMs || unit === 'second') {
      const amount = Math.round(diffMs / unitMs);
      return getRelativeFormat(locale, { numeric: 'auto' }).format(amount, unit);
    }
  }

  return fallback;
}
```
### Formatting Helpers at a Glance

The module groups its helpers into price and date utilities, each with sensible defaults and safe fallbacks.

- **Price formatting** – `formatPrice` handles currency symbols, decimal places, compact notation, and optional plus signs. `formatCompactPrice` is a shortcut for compact output, while `formatPercent` turns ratios into percentages.
- **Price parsing** – `parsePrice` converts human-entered strings like `"1,234.50"` or `"1.234,50"` into numbers, using a simple rule to infer the decimal separator.
- **Date formatting** – `formatDate` and `formatDateTime` produce locale-aware strings, and `toISODate` returns a local `YYYY-MM-DD` string without timezone shifts.
- **Relative time** – `formatRelativeTime` expresses dates as `"3 days ago"` or `"in 2 hours"`, with an optional reference point.
- **Caching and safety** – All Intl formatters are cached, and invalid or missing inputs return a configurable fallback instead of throwing.
---

**Optimization Tip:** You can adjust the default locale and fallback by editing `DEFAULT_LOCALE` and `DEFAULT_FALLBACK` near the top of the module.

