```typescript
/**
 * Small formatting helpers for prices and dates.
 * Uses the built-in Intl API — no external dependencies.
 */

// ---------- Prices ----------

export interface PriceOptions {
  /** ISO 4217 currency code, e.g. "USD", "EUR", "JPY". Default: "USD". */
  currency?: string;
  /** BCP 47 locale, e.g. "en-US", "de-DE". Default: "en-US". */
  locale?: string;
  /** Minimum fraction digits. Defaults to the currency's standard (2 for USD). */
  minimumFractionDigits?: number;
  /** Maximum fraction digits. Defaults to the currency's standard. */
  maximumFractionDigits?: number;
}

/**
 * Format a numeric amount as a localized currency string.
 *
 * @example
 *   formatPrice(1234.5)                       // "$1,234.50"
 *   formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    currency = "USD",
    locale = "en-US",
    minimumFractionDigits,
    maximumFractionDigits,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: amount must be a finite number, got ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

/**
 * Format a price in the smallest currency unit (e.g. cents).
 *
 * @example
 *   formatPriceFromCents(123450) // "$1,234.50"
 */
export function formatPriceFromCents(
  cents: number,
  options: PriceOptions = {},
): string {
  return formatPrice(cents / 100, options);
}

// ---------- Dates ----------

export type DateInput = Date | string | number;

export type DateStyle = "short" | "medium" | "long" | "full";

export interface DateOptions {
  /** BCP 47 locale. Default: "en-US". */
  locale?: string;
  /** Preset style for date portion. Default: "medium". */
  dateStyle?: DateStyle;
  /** Preset style for time portion. If omitted, no time is shown. */
  timeStyle?: DateStyle;
  /** IANA time zone, e.g. "America/New_York". Defaults to the runtime's zone. */
  timeZone?: string;
}

function toDate(input: DateInput): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`formatDate: invalid date input: ${String(input)}`);
  }
  return date;
}

/**
 * Format a date (and optionally a time) using Intl.DateTimeFormat.
 *
 * @example
 *   formatDate("2024-03-15")                                  // "Mar 15, 2024"
 *   formatDate(new Date(), { dateStyle: "full", timeStyle: "short" })
 *   formatDate(Date.now(), { locale: "de-DE", dateStyle: "short" }) // "15.03.24"
 */
export function formatDate(input: DateInput, options: DateOptions = {}): string {
  const {
    locale = "en-US",
    dateStyle = "medium",
    timeStyle,
    timeZone,
  } = options;

  const date = toDate(input);

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    ...(timeStyle ? { timeStyle } : {}),
    ...(timeZone ? { timeZone } : {}),
  }).format(date);
}

/**
 * Format a date as a relative time string ("3 days ago", "in 2 hours").
 *
 * @example
 *   formatRelativeDate(Date.now() - 86_400_000) // "yesterday"
 */
export function formatRelativeDate(
  input: DateInput,
  options: { locale?: string; baseDate?: DateInput } = {},
): string {
  const { locale = "en-US", baseDate = new Date() } = options;
  const date = toDate(input);
  const base = toDate(baseDate);

  const diffSeconds = (date.getTime() - base.getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  const divisions: Array<[number, Intl.RelativeTimeFormatUnit]> = [
    [60, "second"],
    [60, "minute"],
    [24, "hour"],
    [7, "day"],
    [4.34524, "week"],
    [12, "month"],
    [Number.POSITIVE_INFINITY, "year"],
  ];

  let value = diffSeconds;
  for (const [amount, unit] of divisions) {
    if (Math.abs(value) < amount) {
      return rtf.format(Math.round(value), unit);
    }
    value /= amount;
  }
  return rtf.format(Math.round(value), "year");
}
