## Notes

- **No dependencies** — everything is built on `Intl`, which is available in Node 14+ and all modern browsers.
- **Errors are explicit** — invalid numbers/dates throw rather than silently returning `"Invalid Date"`.
- **`formatPriceFromCents`** is handy when your backend stores amounts as integers (Stripe, most payment APIs).
- **`formatRelativeDate`** uses `Intl.RelativeTimeFormat` with `numeric: "auto"`, so you get `"yesterday"` instead of `"1 day ago"` where the locale supports it.
- If you need to support very old runtimes, add an `Intl` polyfill — otherwise the module is self-contained.

# Format Helpers Module

Here's a small, dependency-free TypeScript module with helpers for formatting prices and dates.

```ts
// format.ts

/**
 * Format a numeric amount as a localized price string.
 *
 * @example
 *   formatPrice(1234.5)                    // "$1,234.50"
 *   formatPrice(1234.5, { currency: 'EUR', locale: 'de-DE' }) // "1.234,50 €"
 */
export function formatPrice(
  amount: number,
  options: {
    currency?: string;
    locale?: string;
    /** Show the currency symbol. Default: true */
    withSymbol?: boolean;
  } = {}
): string {
  const { currency = 'USD', locale = 'en-US', withSymbol = true } = options;

  if (!Number.isFinite(amount)) return '—';

  return new Intl.NumberFormat(locale, {
    style: withSymbol ? 'currency' : 'decimal',
    currency,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);
}

/**
 * Format a price range, collapsing to a single value when min === max.
 *
 * @example
 *   formatPriceRange(10, 20)  // "$10.00 – $20.00"
 *   formatPriceRange(10, 10)  // "$10.00"
 */
export function formatPriceRange(
  min: number,
  max: number,
  options?: Parameters<typeof formatPrice>[1]
): string {
  if (min === max) return formatPrice(min, options);
  return `${formatPrice(min, options)} – ${formatPrice(max, options)}`;
}

/**
 * Format a date in a short, human-friendly form.
 *
 * @example
 *   formatDate(new Date('2024-03-05'))       // "Mar 5, 2024"
 *   formatDate('2024-03-05', 'de-DE')        // "5. März 2024"
 */
export function formatDate(
  input: Date | string | number,
  locale = 'en-US',
  options: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  }
): string {
  const date = toDate(input);
  if (!date) return '—';
  return new Intl.DateTimeFormat(locale, options).format(date);
}

/**
 * Format a date + time, e.g. "Mar 5, 2024, 2:30 PM".
 */
export function formatDateTime(
  input: Date | string | number,
  locale = 'en-US'
): string {
  return formatDate(input, locale, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

/**
 * Return a relative time string, e.g. "3 days ago" or "in 2 hours".
 */
export function formatRelative(
  input: Date | string | number,
  locale = 'en-US'
): string {
  const date = toDate(input);
  if (!date) return '—';

  const diffMs = date.getTime() - Date.now();
  const diffSeconds = Math.round(diffMs / 1000);

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ['year', 60 * 60 * 24 * 365],
    ['month', 60 * 60 * 24 * 30],
    ['week', 60 * 60 * 24 * 7],
    ['day', 60 * 60 * 24],
    ['hour', 60 * 60],
    ['minute', 60],
    ['second', 1],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: 'auto' });

  for (const [unit, secondsPerUnit] of units) {
    if (Math.abs(diffSeconds) >= secondsPerUnit || unit === 'second') {
      return rtf.format(Math.round(diffSeconds / secondsPerUnit), unit);
    }
  }
  return 'just now';
}

/** Internal: coerce input to a valid Date or return null. */
function toDate(input: Date | string | number): Date | null {
  const date = input instanceof Date ? input : new Date(input);
  return Number.isNaN(date.getTime()) ? null : date;
}
```

## Notes on design choices

- **`Intl` over libraries** — no dependencies, fully locale-aware, and works in Node and browsers.
- **Invalid input handling** — `formatPrice` guards against `NaN`/`Infinity`; the date helpers return an em-dash for unparseable input instead of throwing.
- **Sensible defaults** — `en-US` / `USD`, with optional overrides for locale and currency.
- **`formatPriceRange`** — a common UI need (e.g. product listings); collapses to a single value when min equals max.
- **`formatRelative`** — uses `Intl.RelativeTimeFormat`, so you get correct pluralization in any locale.

## Usage

```ts
import { formatPrice, formatDate, formatRelative } from './format';

formatPrice(49.9);                          // "$49.90"
formatPrice(49.9, { currency: 'JPY', locale: 'ja-JP' }); // "￥50"
formatDate('2024-03-05');                   // "Mar 5, 2024"
formatRelative(Date.now() - 3 * 3600_000);  // "3 hours ago"
```

If you need this to run in older environments without full ICU support (e.g. Node 12 without `--with-intl=full-icu`), you may want to pin the locale or ship a polyfill.

