 * Format a date using locale-aware presets.
 *
 * @example
 * formatDate("2024-03-15")                       // "Mar 15, 2024"
 * formatDate(new Date(), { dateStyle: "full" })  // "Friday, March 15, 2024"
 * formatDate(Date.now(), { dateStyle: "short", timeStyle: "short" })
 * // "3/15/24, 2:30 PM"
 */
export function formatDate(input: DateInput, options: DateOptions = {}): string {
  const {
    locale = "en-US",
    dateStyle = "medium",
    timeStyle,
    timeZone,
  } = options;

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    ...(timeStyle ? { timeStyle } : {}),
    ...(timeZone ? { timeZone } : {}),
  }).format(toDate(input));
}

/**
 * Format a date as a relative time string (e.g. "3 days ago", "in 2 hours").
 *
 * @example
 * formatRelativeTime(Date.now() - 60_000)   // "1 minute ago"
 * formatRelativeTime(Date.now() + 7200_000) // "in 2 hours"
 */
export function formatRelativeTime(
  input: DateInput,
  options: { locale?: string; base?: DateInput; numeric?: "always" | "auto" } = {},
): string {
  const { locale = "en-US", base = Date.now(), numeric = "auto" } = options;

  const target = toDate(input).getTime();
  const reference = toDate(base).getTime();
  const deltaSeconds = (target - reference) / 1000;

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric });

  for (const [unit, secondsPerUnit] of units) {
    if (Math.abs(deltaSeconds) >= secondsPerUnit || unit === "second") {
      return rtf.format(Math.round(deltaSeconds / secondsPerUnit), unit);
    }
  }

  // Unreachable, but satisfies the type checker.
  return rtf.format(0, "second");
}
```

## Usage

```ts
import {
  formatPrice,
  formatNumber,
  formatDate,
  formatRelativeTime,
} from "./format";

formatPrice(19.99);                                            // "$19.99"
formatPrice(19.99, { currency: "JPY", locale: "ja-JP" });      // "￥20"
formatNumber(1234567.89, { maximumFractionDigits: 2 });        // "1,234,567.89"

formatDate("2024-03-15");                                      // "Mar 15, 2024"
formatDate("2024-03-15", { dateStyle: "full", locale: "fr-FR" });
// "vendredi 15 mars 2024"

formatRelativeTime(Date.now() - 3 * 86_400_000);               // "3 days ago"
```

## Notes

- **Zero dependencies** — relies on `Intl`, which is available in all modern browsers and Node.js (Node 14+ has full ICU by default).
- **Validation** — `formatPrice` throws on `NaN`/`Infinity`; `formatDate` throws on invalid dates.
- **Locale-aware** — every function accepts a `locale` option so you can wire it up to user preferences.
- **Tree-shakeable** — each helper is a standalone named export.

# `format.ts` — Price & Date Formatting Helpers

```ts
// format.ts

/** ISO 4217 currency codes we explicitly support (extend as needed). */
export type CurrencyCode =
  | "USD"
  | "EUR"
  | "GBP"
  | "JPY"
  | "CAD"
  | "AUD";

export interface PriceOptions {
  /** BCP-47 locale tag, e.g. "en-US", "de-DE". Defaults to "en-US". */
  locale?: string;
  /** Currency code. Defaults to "USD". */
  currency?: CurrencyCode;
  /** Minimum fraction digits. Defaults to the currency's standard (2, or 0 for JPY). */
  minimumFractionDigits?: number;
  /** Maximum fraction digits. Defaults to the currency's standard. */
  maximumFractionDigits?: number;
  /** Show the currency symbol (default) or the code, e.g. "USD". */
  display?: "symbol" | "code" | "name";
}

/**
 * Format a numeric amount as a localized currency string.
 * Returns an empty string for non-finite input.
 *
 * @example formatPrice(1234.5)                  // "$1,234.50"
 * @example formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }) // "1.234,50 €"
 */
export function formatPrice(
  amount: number,
  options: PriceOptions = {},
): string {
  if (!Number.isFinite(amount)) return "";

  const {
    locale = "en-US",
    currency = "USD",
    minimumFractionDigits,
    maximumFractionDigits,
    display = "symbol",
  } = options;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    currencyDisplay: display,
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

/**
 * Format a number as a plain localized number (no currency symbol).
 *
 * @example formatNumber(1234.5, "de-DE") // "1.234,5"
 */
export function formatNumber(
  value: number,
  locale = "en-US",
  options: Intl.NumberFormatOptions = {},
): string {
  if (!Number.isFinite(value)) return "";
  return new Intl.NumberFormat(locale, options).format(value);
}

export type DateInput = Date | string | number;

export interface DateOptions {
  locale?: string;
  /** Preset style. Defaults to "medium". */
  dateStyle?: "full" | "long" | "medium" | "short";
  /** Optional time style; when set, time is included. */
  timeStyle?: "full" | "long" | "medium" | "short";
  /** IANA time zone, e.g. "America/New_York". Defaults to the runtime's zone. */
  timeZone?: string;
}

/**
 * Format a date (or date-like value) using Intl.DateTimeFormat.
 * Returns an empty string for invalid input.
 *
 * @example formatDate(new Date())                                    // "Nov 14, 2025"
 * @example formatDate("2025-11-14T10:30:00Z", { timeStyle: "short" }) // "Nov 14, 2025, 10:30 AM"
 */
export function formatDate(input: DateInput, options: DateOptions = {}): string {
  const date = toDate(input);
  if (!date) return "";

  const {
    locale = "en-US",
    dateStyle = "medium",
    timeStyle,
    timeZone,
  } = options;

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    timeStyle,
    timeZone,
  }).format(date);
}

/**
 * Format a date as an ISO-8601 date string (YYYY-MM-DD), timezone-independent
 * for `Date` objects (uses local components).
 *
 * @example formatISODate(new Date(2025, 10, 14)) // "2025-11-14"
 */
export function formatISODate(input: DateInput): string {
  const date = toDate(input);
  if (!date) return "";

  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

/**
 * Format a relative time string, e.g. "3 days ago", "in 2 hours".
 * Uses `Intl.RelativeTimeFormat` under the hood.
 *
 * @example formatRelativeTime(-3, "day") // "3 days ago"
 * @example formatRelativeTime(2, "hour", "de-DE") // "in 2 Stunden"
 */
export function formatRelativeTime(
  value: number,
  unit: Intl.RelativeTimeFormatUnit,
  locale = "en-US",
): string {
  return new Intl.RelativeTimeFormat(locale, { numeric: "auto" }).format(
    value,
    unit,
  );
}

/* ----------------------------- internal utils ---------------------------- */

/** Coerce a Date | string | number into a valid Date, or return null. */
function toDate(input: DateInput): Date | null {
  const date = input instanceof Date ? input : new Date(input);
  return Number.isNaN(date.getTime()) ? null : date;
}
```

