 *
 * @example
 * formatPrice(1234.5)                       // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * formatPrice(9.99, { showCurrency: false }) // "9.99"
 */
export function formatPrice(
  amount: number,
  options: PriceFormatOptions = {},
): string {
  const {
    currency = "USD",
    locale = "en-US",
    showCurrency = true,
    minimumFractionDigits,
    maximumFractionDigits,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: amount must be a finite number, got ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: showCurrency ? "currency" : "decimal",
    currency,
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

/**
 * Format a minor-unit integer (e.g. cents) as a currency string.
 *
 * @example
 * formatPriceFromCents(1999) // "$19.99"
 */
export function formatPriceFromCents(
  cents: number,
  options: PriceFormatOptions = {},
): string {
  if (!Number.isInteger(cents)) {
    throw new TypeError(`formatPriceFromCents: cents must be an integer, got ${cents}`);
  }
  return formatPrice(cents / 100, options);
}

/* ------------------------------------------------------------------ */
/*  Date formatting                                                    */
/* ------------------------------------------------------------------ */

export type DateInput = Date | string | number;

function toDate(value: DateInput): Date {
  const d = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(d.getTime())) {
    throw new TypeError(`Invalid date input: ${String(value)}`);
  }
  return d;
}

/**
 * Format a date as a short localized date string.
 *
 * @example
 * formatDate("2024-03-05") // "3/5/2024"
 */
export function formatDate(
  value: DateInput,
  locale = "en-US",
  options: Intl.DateTimeFormatOptions = { dateStyle: "short" },
): string {
  return new Intl.DateTimeFormat(locale, options).format(toDate(value));
}

/**
 * Format a date as a localized time string.
 *
 * @example
 * formatTime("2024-03-05T14:30:00Z") // "2:30 PM"
 */
export function formatTime(
  value: DateInput,
  locale = "en-US",
  options: Intl.DateTimeFormatOptions = { timeStyle: "short" },
): string {
  return new Intl.DateTimeFormat(locale, options).format(toDate(value));
}

/**
 * Format a date as a full localized date-time string.
 *
 * @example
 * formatDateTime("2024-03-05T14:30:00Z") // "3/5/2024, 2:30 PM"
 */
export function formatDateTime(
  value: DateInput,
  locale = "en-US",
  options: Intl.DateTimeFormatOptions = { dateStyle: "medium", timeStyle: "short" },
): string {
  return new Intl.DateTimeFormat(locale, options).format(toDate(value));
}

/**
 * Return a human-readable relative time string ("3 hours ago", "in 2 days").
 *
 * @example
 * formatRelativeTime(Date.now() - 60_000) // "1 minute ago"
 */
export function formatRelativeTime(
  value: DateInput,
  locale = "en-US",
  base: DateInput = Date.now(),
): string {
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  const diffMs = toDate(value).getTime() - toDate(base).getTime();
  const diffSec = Math.round(diffMs / 1000);

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year",   60 * 60 * 24 * 365],
    ["month",  60 * 60 * 24 * 30],
    ["week",   60 * 60 * 24 * 7],
    ["day",    60 * 60 * 24],
    ["hour",   60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  for (const [unit, secondsInUnit] of units) {
    if (Math.abs(diffSec) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSec / secondsInUnit), unit);
    }
  }
  /* istanbul ignore next — unreachable */
  return "now";
}

/**
 * Parse a user-entered price string into a number, tolerating common
 * formatting (currency symbols, thousands separators, both `.` and `,`).
 *
 * @example
 * parsePrice("$1,234.50")  // 1234.5
 * parsePrice("1.234,50 €") // 1234.5
 */
export function parsePrice(input: string): number {
  const cleaned = input.replace(/[^\d.,-]/g, "").trim();
  if (!cleaned) return NaN;

  const lastComma = cleaned.lastIndexOf(",");
  const lastDot = cleaned.lastIndexOf(".");

  let normalized: string;
  if (lastComma > lastDot) {
    // European style: "1.234,50" → "1234.50"
    normalized = cleaned.replace(/\./g, "").replace(",", ".");
  } else {
    // US style: "1,234.50" → "1234.50"
    normalized = cleaned.replace(/,/g, "");
  }

  return Number.parseFloat(normalized);
}
