 * Formats a Date (or ISO string / timestamp) as a localized string.
 *
 * @example
 * formatDate(new Date())                                  // "Oct 15, 2025"
 * formatDate('2025-10-15T12:00:00Z', { timeStyle: 'short' }) // "Oct 15, 2025, 12:00 PM"
 */
export function formatDate(
  input: Date | string | number,
  options: DateFormatOptions = {}
): string {
