/**
 * Formats a date as a relative time string, e.g. "3 days ago", "in 2 hours".
 */
export function formatRelativeDate(
  input: Date | string | number,
  baseDate: Date = new Date(),
  locale: string = 'en-US'
): string {
  const date = toDate(input);
  const diffMs = date.getTime() - baseDate.getTime();
  const diffSeconds = Math.round(diffMs / 1000);

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: 'auto' });
  const thresholds: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ['year', 60 * 60 * 24 * 365],
    ['month', 60 * 60 * 24 * 30],
    ['week', 60 * 60 * 24 * 7],
    ['day', 60 * 60 * 24],
    ['hour', 60 * 60],
    ['minute', 60],
    ['second', 1],
  ];

  for (const [unit, secondsInUnit] of thresholds) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === 'second') {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return rtf.format(0, 'second');
}

/** Internal helper: normalizes input to a Date, throwing on invalid input. */
function toDate(input: Date | string | number): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`Invalid date input: ${String(input)}`);
  }
  return date;
