): string {
  const { locale = 'en-US', style = 'medium', timeZone } = options;
  const date = toDate(value);

  return new Intl.DateTimeFormat(locale, {
    dateStyle: style,
    timeStyle: 'short',
    timeZone,
  }).format(date);
}

/**
 * Format a date range, collapsing shared parts where the locale allows.
 * @example formatDateRange(start, end) // "Nov 14 – 20, 2024"
 */
export function formatDateRange(
  start: Date | string | number,
  end: Date | string | number,
  options: DateOptions = {},
): string {
  const { locale = 'en-US', style = 'medium', timeZone } = options;
  const formatter = new Intl.DateTimeFormat(locale, {
    dateStyle: style,
    timeZone,
  });
  return formatter.formatRange(toDate(start), toDate(end));
}

/** Convert a Date | string | number into a valid Date, throwing on invalid input. */
function toDate(value: Date | string | number): Date {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date value: ${String(value)}`);
  }
  return date;
}
```

Usage:

```typescript
import { formatPrice, formatDate, formatDateTime, formatDateRange } from './format';

formatPrice(1234.5);                          // "$1,234.50"
formatPrice(1234.5, { currency: 'EUR', locale: 'de-DE' }); // "1.234,50 €"

formatDate(new Date());                       // "Nov 14, 2024"
formatDate('2024-11-14', { style: 'full' });  // "Thursday, November 14, 2024"

formatDateTime(Date.now());                   // "Nov 14, 2024, 3:45 PM"

formatDateRange('2024-11-14', '2024-11-20');  // "Nov 14 – 20, 2024"
```

A few notes on the design:

- **All formatting** goes through `Intl`, so you get correct locale behavior for free (thousands separators, currency symbol placement, month names, etc.).
- **Options are explicit** rather than positional, so callers can override just what they need.
- **Invalid input throws** — `Intl` would otherwise produce `"Invalid Date"` or `"NaN"` silently, which is usually worse than failing fast.
- **`formatDateRange`** uses `Intl.DateTimeFormat#formatRange`, which automatically collapses repeated parts (`Nov 14 – 20, 2024` instead of `Nov 14, 2024 – Nov 20, 2024`).

```typescript
// format.ts

/** Supported currency codes (extend as needed). */
export type CurrencyCode = "USD" | "EUR" | "GBP" | "JPY";

/** Options for `formatPrice`. */
export interface PriceOptions {
  /** ISO 4217 currency code. Defaults to `"USD"`. */
  currency?: CurrencyCode;
  /** BCP 47 locale tag. Defaults to `"en-US"`. */
  locale?: string;
  /** Show fractional digits even when they are `.00`. Defaults to `true`. */
  showCents?: boolean;
  /** Use compact notation (e.g. `$1.2K`). Defaults to `false`. */
  compact?: boolean;
}

/**
 * Format a numeric amount as a localized price string.
 *
 * @example
 *   formatPrice(1234.5)                                  // "$1,234.50"
 *   formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 *   formatPrice(1234.5, { compact: true })               // "$1.2K"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    currency = "USD",
    locale = "en-US",
    showCents = true,
    compact = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: amount must be a finite number, got ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
    minimumFractionDigits: showCents ? 2 : 0,
    maximumFractionDigits: showCents ? 2 : 0,
  }).format(amount);
}

/** Supported date output styles. */
export type DateStyle = "short" | "medium" | "long" | "iso";

/** Options for `formatDate`. */
export interface DateOptions {
  /** BCP 47 locale tag. Defaults to `"en-US"`. */
  locale?: string;
  /** Output style. Defaults to `"medium"`. */
  style?: DateStyle;
  /** IANA time zone, e.g. `"Europe/Berlin"`. Defaults to the runtime zone. */
  timeZone?: string;
}

/**
 * Format a `Date` (or date-like value) as a localized string.
 *
 * @example
 *   formatDate(new Date("2024-03-15"))               // "Mar 15, 2024"
 *   formatDate("2024-03-15", { style: "iso" })       // "2024-03-15"
 *   formatDate(new Date(), { style: "long", locale: "fr-FR" })
 */
export function formatDate(
  input: Date | string | number,
  options: DateOptions = {},
): string {
  const { locale = "en-US", style = "medium", timeZone } = options;
  const date = input instanceof Date ? input : new Date(input);

  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`formatDate: invalid date input "${String(input)}"`);
  }

  if (style === "iso") {
    // ISO 8601 date only (YYYY-MM-DD), independent of locale.
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, "0");
    const d = String(date.getDate()).padStart(2, "0");
    return `${y}-${m}-${d}`;
  }

  return new Intl.DateTimeFormat(locale, {
    dateStyle: style,
    timeZone,
  }).format(date);
}

/**
 * Format a date relative to now, e.g. `"3 days ago"` or `"in 2 hours"`.
 *
 * @example
 *   formatRelativeDate(Date.now() - 3 * 86400_000) // "3 days ago"
 */
export function formatRelativeDate(
  input: Date | string | number,
  locale = "en-US",
): string {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`formatRelativeDate: invalid date input "${String(input)}"`);
  }

  const diffSeconds = (date.getTime() - Date.now()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  const thresholds: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  for (const [unit, secondsInUnit] of thresholds) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }

  // Unreachable, but keeps TypeScript happy.
  return rtf.format(0, "second");
}
```

Notes on the design:

- **`Intl`-based** — no external dependencies, and output is locale-aware out of the box.
- **Strict input validation** — non-finite numbers and invalid dates throw early with clear messages rather than silently producing `"NaN"`.
- **`compact` option** — handy for dashboards and charts where space is tight.
- **`iso` style** — bypasses `Intl` deliberately, since ISO 8601 is meant to be locale-independent (useful for API payloads or `<input type="date">` values).
- **`formatRelativeDate`** — picks the largest sensible unit, mirroring how `Intl.RelativeTimeFormat` is typically used.

```typescript
// format.ts
// Small helpers for formatting prices and dates using the built-in Intl APIs.

export type PriceOptions = {
  /** ISO 4217 currency code, e.g. "USD", "EUR", "JPY". Defaults to "USD". */
  currency?: string;
  /** BCP 47 locale tag, e.g. "en-US", "de-DE". Defaults to runtime locale. */
  locale?: string;
  /** Show currency symbol/code. Defaults to true. */
  showCurrency?: boolean;
  /** Minimum fraction digits. Defaults to currency's standard (e.g. 2 for USD). */
  minimumFractionDigits?: number;
  /** Maximum fraction digits. Defaults to currency's standard. */
  maximumFractionDigits?: number;
};

/**
 * Format a numeric amount as a localized price string.
 *
 * formatPrice(1234.5)                          // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 * formatPrice(1234.5, { showCurrency: false }) // "1,234.50"
 */
export function formatPrice(
  amount: number,
  options: PriceOptions = {}
): string {
  const {
    currency = "USD",
    locale,
    showCurrency = true,
    minimumFractionDigits,
    maximumFractionDigits,
  } = options;

  if (!Number.isFinite(amount)) {
    return "—";
  }

  return new Intl.NumberFormat(locale, {
    style: showCurrency ? "currency" : "decimal",
    currency: showCurrency ? currency : undefined,
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

export type DateInput = Date | string | number;

export type DateFormatPreset =
  | "short"   // 12/31/2024
  | "medium"  // Dec 31, 2024
  | "long"    // December 31, 2024
  | "full"    // Tuesday, December 31, 2024
  | "iso";    // 2024-12-31

export type DateOptions = {
  /** BCP 47 locale tag. Defaults to runtime locale. */
  locale?: string;
  /** Preset style or a custom Intl.DateTimeFormatOptions object. */
  format?: DateFormatPreset | Intl.DateTimeFormatOptions;
  /** Include time component (ignored for "iso"). */
  includeTime?: boolean;
};

function toDate(input: DateInput): Date | null {
  const d = input instanceof Date ? input : new Date(input);
  return Number.isNaN(d.getTime()) ? null : d;
}

/**
 * Format a date (Date, ISO string, or timestamp) as a localized string.
 *
 * formatDate("2024-12-31")                          // "Dec 31, 2024"
 * formatDate("2024-12-31", { format: "iso" })       // "2024-12-31"
 * formatDate(new Date(), { includeTime: true })     // "Dec 31, 2024, 3:45 PM"
 */
export function formatDate(input: DateInput, options: DateOptions = {}): string {
  const { locale, format = "medium", includeTime = false } = options;
  const date = toDate(input);
  if (!date) return "—";

  if (format === "iso") {
    const yyyy = date.getFullYear().toString().padStart(4, "0");
    const mm = (date.getMonth() + 1).toString().padStart(2, "0");
    const dd = date.getDate().toString().padStart(2, "0");
    return `${yyyy}-${mm}-${dd}`;
  }

  const base: Intl.DateTimeFormatOptions =
    typeof format === "string"
      ? { dateStyle: format }
      : format;

  const opts: Intl.DateTimeFormatOptions = includeTime
    ? { ...base, timeStyle: "short" }
    : base;

  return new Intl.DateTimeFormat(locale, opts).format(date);
}

/**
 * Human-friendly relative time, e.g. "3 days ago", "in 2 hours".
 */
export function formatRelativeDate(
  input: DateInput,
  options: { locale?: string; baseDate?: DateInput } = {}
): string {
  const { locale, baseDate = new Date() } = options;
  const date = toDate(input);
  const base = toDate(baseDate);
  if (!date || !base) return "—";

  const diffSeconds = (date.getTime() - base.getTime()) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  for (const [unit, secondsInUnit] of units) {
    if (Math.abs(diffSeconds) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSeconds / secondsInUnit), unit);
    }
  }
  return rtf.format(0, "second");
}
```

