Notes:
- Uses only built-in `Intl` — no dependencies.
- All functions return `"—"` for invalid input rather than throwing.
- `formatDate` accepts `Date`, ISO string, or timestamp; `"iso"` preset gives a stable machine-readable format for APIs/logs.

```typescript
// format.ts

/**
 * Formatting helpers for prices and dates.
 * All functions are pure and locale-aware.
 */

type CurrencyCode = string; // e.g. "USD", "EUR", "JPY"
type Locale = string;       // e.g. "en-US", "de-DE"

// ---------------------------------------------------------------------------
// Prices
// ---------------------------------------------------------------------------

const defaultCurrency: CurrencyCode = "USD";
const defaultLocale: Locale = "en-US";

/**
 * Format a numeric amount as a localized currency string.
 *
 * @example
 *   formatPrice(1234.5)                  // "$1,234.50"
 *   formatPrice(1234.5, "EUR", "de-DE")  // "1.234,50 €"
 */
export function formatPrice(
  amount: number,
  currency: CurrencyCode = defaultCurrency,
  locale: Locale = defaultLocale,
): string {
  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: amount must be a finite number, got ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);
}

/**
 * Format a numeric amount as a plain localized number (no currency symbol).
 *
 * @example
 *   formatNumber(1234.5)                 // "1,234.5"
 *   formatNumber(1234.5, "de-DE", 2)     // "1.234,50"
 */
export function formatNumber(
  value: number,
  locale: Locale = defaultLocale,
  fractionDigits = 2,
): string {
  if (!Number.isFinite(value)) {
    throw new TypeError(`formatNumber: value must be a finite number, got ${value}`);
  }

  return new Intl.NumberFormat(locale, {
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  }).format(value);
}

/**
 * Parse a user-entered price string into a number.
 * Handles thousands separators, currency symbols, and both `.`/`,` decimals.
 *
 * @example
 *   parsePrice("$1,234.50")  // 1234.5
 *   parsePrice("1.234,50 €") // 1234.5
 */
export function parsePrice(input: string): number | null {
  if (!input) return null;

  // Strip everything except digits, separators, and a leading minus sign.
  const cleaned = input.replace(/[^\d.,-]/g, "").trim();
  if (!cleaned) return null;

  const lastComma = cleaned.lastIndexOf(",");
  const lastDot = cleaned.lastIndexOf(".");
  const decimalSep = lastComma > lastDot ? "," : ".";
  const thousandSep = decimalSep === "," ? "." : ",";

  const normalized = cleaned
    .split(thousandSep)
    .join("")
    .replace(decimalSep, ".");

  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : null;
}

// ---------------------------------------------------------------------------
// Dates
// ---------------------------------------------------------------------------

type DateInput = Date | string | number;

function toDate(input: DateInput): Date {
  const d = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(d.getTime())) {
    throw new RangeError(`Invalid date input: ${String(input)}`);
  }
  return d;
}

/**
 * Format a date using a small set of named presets, or a custom Intl config.
 *
 * @example
 *   formatDate(new Date(), "short")   // "1/15/24"
 *   formatDate(new Date(), "long")    // "January 15, 2024"
 *   formatDate(new Date(), "iso")     // "2024-01-15"
 */
export function formatDate(
  input: DateInput,
  preset: "short" | "medium" | "long" | "iso" = "medium",
  locale: Locale = defaultLocale,
): string {
  const date = toDate(input);

  if (preset === "iso") {
    return date.toISOString().slice(0, 10);
  }

  const options: Intl.DateTimeFormatOptions =
    preset === "short"
      ? { year: "2-digit", month: "numeric", day: "numeric" }
      : preset === "long"
        ? { year: "numeric", month: "long", day: "numeric" }
        : { year: "numeric", month: "short", day: "numeric" };

  return new Intl.DateTimeFormat(locale, options).format(date);
}

/**
 * Format a date and time together.
 *
 * @example
 *   formatDateTime(new Date()) // "Jan 15, 2024, 3:42 PM"
 */
export function formatDateTime(
  input: DateInput,
  locale: Locale = defaultLocale,
): string {
  const date = toDate(input);
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

/**
 * Human-friendly relative time, e.g. "3 days ago", "in 2 hours".
 * Uses `Intl.RelativeTimeFormat` for locale correctness.
 */
export function formatRelative(
  input: DateInput,
  base: DateInput = new Date(),
  locale: Locale = defaultLocale,
): string {
  const date = toDate(input);
  const reference = toDate(base);
  const diffMs = date.getTime() - reference.getTime();
  const diffSec = Math.round(diffMs / 1000);

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, secondsInUnit] of units) {
    if (Math.abs(diffSec) >= secondsInUnit || unit === "second") {
      return rtf.format(Math.round(diffSec / secondsInUnit), unit);
    }
  }

  // Unreachable, but keeps TypeScript happy.
  return rtf.format(0, "second");
}
```

