// useOnlineStatus.ts
import { useSyncExternalStore } from 'react';

function subscribe(callback: () => void): () => void {
  window.addEventListener('online', callback);
  window.addEventListener('offline', callback);
  return () => {
    window.removeEventListener('online', callback);
    window.removeEventListener('offline', callback);
  };
}

function getSnapshot(): boolean {
  return navigator.onLine;
}

// Assume online during SSR / hydration to avoid a flash of "offline" UI.
function getServerSnapshot(): boolean {
  return true;
}

/**
 * Tracks whether the browser is currently online.
 * Re-renders whenever the `online` or `offline` window events fire.
 */
export function useOnlineStatus(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}
```

Usage:

```tsx
import { useOnlineStatus } from './useOnlineStatus';

function StatusBar() {
  const isOnline = useOnlineStatus();
  return <span>{isOnline ? '🟢 Online' : '🔴 Offline'}</span>;
}
```

Notes:
- `useSyncExternalStore` (React 18+) is the idiomatic way to subscribe to an external store like `navigator.onLine` — it avoids tearing and handles SSR via the third argument.
- `navigator.onLine` is a best-effort signal: it only tells you whether the browser thinks it has a network interface, not whether the internet is actually reachable. For real reachability, pair it with a fetch/ping check.
- If you're on React 17 or earlier, swap `useSyncExternalStore` for `useState` + `useEffect` that adds the same listeners and calls `setIsOnline(navigator.onLine)`.

