```jsx
import { useState } from "react";
import "./UserCard.css";

export default function UserCard({ user, onFollowChange }) {
  const [isFollowing, setIsFollowing] = useState(Boolean(user.isFollowing));
  const [isPending, setIsPending] = useState(false);
  const [avatarFailed, setAvatarFailed] = useState(false);

  async function handleToggleFollow() {
    const next = !isFollowing;
    setIsFollowing(next);          // optimistic update
    setIsPending(true);
    try {
      await onFollowChange?.(user.id, next);
    } catch (err) {
      setIsFollowing(!next);       // roll back on failure
      console.error("Failed to update follow state", err);
    } finally {
      setIsPending(false);
    }
  }

  const initials = user.name
    .split(" ")
    .map((part) => part[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();

  return (
    <article className="user-card">
      <div className="user-card__avatar">
        {avatarFailed || !user.avatarUrl ? (
          <span aria-hidden="true">{initials}</span>
        ) : (
          <img
            src={user.avatarUrl}
            alt={`${user.name}'s avatar`}
            onError={() => setAvatarFailed(true)}
          />
        )}
      </div>

      <div className="user-card__info">
        <h3 className="user-card__name">{user.name}</h3>
        {user.handle && <p className="user-card__handle">@{user.handle}</p>}
      </div>

      <button
        type="button"
        className={`user-card__button ${isFollowing ? "is-following" : ""}`}
        onClick={handleToggleFollow}
        disabled={isPending}
        aria-pressed={isFollowing}
      >
        {isPending ? "…" : isFollowing ? "Following" : "Follow"}
      </button>
    </article>
  );
}
```

