type UserProfileProps = {
  name: string;
  avatarUrl?: string;
  initialFollowers?: number;
  /** Called whenever the follow state changes. */
  onFollowChange?: (isFollowing: boolean) => void;
};

export function UserProfile({
  name,
  avatarUrl,
  initialFollowers = 0,
  onFollowChange,
}: UserProfileProps) {
  const [isFollowing, setIsFollowing] = useState(false);
  const [followers, setFollowers] = useState(initialFollowers);
  const [avatarFailed, setAvatarFailed] = useState(false);

  const handleToggle = () => {
    const next = !isFollowing;
    setIsFollowing(next);
    setFollowers((count) => count + (next ? 1 : -1));
    onFollowChange?.(next);
  };

  const initials = name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();

  return (
    <div style={styles.card}>
      {avatarUrl && !avatarFailed ? (
        <img
          src={avatarUrl}
          alt={`${name}'s avatar`}
          onError={() => setAvatarFailed(true)}
          style={styles.avatar}
        />
      ) : (
        <div style={styles.avatarFallback} aria-hidden="true">
          {initials}
        </div>
      )}

      <div style={styles.info}>
        <span style={styles.name}>{name}</span>
        <span style={styles.meta}>
          {followers.toLocaleString()} {followers === 1 ? "follower" : "followers"}
        </span>
      </div>

      <button
        type="button"
        onClick={handleToggle}
        aria-pressed={isFollowing}
        style={{
          ...styles.button,
          ...(isFollowing ? styles.buttonFollowing : styles.buttonFollow),
        }}
      >
        {isFollowing ? "Following" : "Follow"}
