import { useState } from "react";
import "./UserProfile.css";

export default function UserProfile({
  user,
  onFollowChange,          // optional: (userId, isFollowing) => void
  size = 48,
}) {
  const [isFollowing, setIsFollowing] = useState(user.isFollowing ?? false);
  const [isPending, setIsPending] = useState(false);

  async function handleToggle() {
    // Optimistic update; revert if the request fails.
    const next = !isFollowing;
    setIsFollowing(next);
    setIsPending(true);
    try {
      await onFollowChange?.(user.id, next);
    } catch (err) {
      setIsFollowing(!next); // roll back
      console.error("Failed to update follow state", err);
    } finally {
      setIsPending(false);
    }
  }

  return (
    <article className="user-profile">
      <img
        className="user-profile__avatar"
        src={user.avatarUrl}
        alt=""                       // decorative: the name is right next to it
        width={size}
        height={size}
        onError={(e) => {
          e.currentTarget.src = fallbackAvatar(user.name);
        }}
      />

      <div className="user-profile__info">
        <h3 className="user-profile__name">{user.name}</h3>
        {user.handle && (
          <p className="user-profile__handle">@{user.handle}</p>
        )}
      </div>

      <button
        type="button"
        className={`user-profile__button ${
          isFollowing ? "is-following" : "is-follow"
        }`}
        onClick={handleToggle}
        disabled={isPending}
        aria-pressed={isFollowing}
      >
        {isPending ? "…" : isFollowing ? "Following" : "Follow"}
      </button>
    </article>
  );
}

function fallbackAvatar(name = "?") {
  const initials = name
    .split(" ")
    .map((part) => part[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();
  return `https://ui-avatars.com/api/?name=${encodeURIComponent(
    initials
  )}&background=random`;
}
