## `UserProfile.tsx`

```tsx
import { useState } from "react";
import "./UserProfile.css";

export type User = {
  id: string;
  name: string;
  avatarUrl?: string;
  isFollowing?: boolean;
};

type UserProfileProps = {
  user: User;
  /** Called when the follow state changes. Return a promise to show a pending state. */
  onFollowChange?: (userId: string, isFollowing: boolean) => void | Promise<void>;
};

function initials(name: string) {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("");
}

export default function UserProfile({ user, onFollowChange }: UserProfileProps) {
  const [isFollowing, setIsFollowing] = useState(Boolean(user.isFollowing));
  const [isPending, setIsPending] = useState(false);
  const [avatarFailed, setAvatarFailed] = useState(false);

  async function toggleFollow() {
    const next = !isFollowing;
    setIsFollowing(next); // optimistic update
    setIsPending(true);
    try {
      await onFollowChange?.(user.id, next);
    } catch (error) {
      setIsFollowing(!next); // roll back on failure
      console.error("Failed to update follow state", error);
    } finally {
      setIsPending(false);
    }
  }

  const showImage = user.avatarUrl && !avatarFailed;

  return (
    <article className="user-profile">
      <div className="user-profile__avatar" aria-hidden="true">
        {showImage ? (
          <img
            src={user.avatarUrl}
            alt=""
            width={56}
            height={56}
            onError={() => setAvatarFailed(true)}
          />
        ) : (
          <span className="user-profile__initials">{initials(user.name)}</span>
        )}
      </div>

      <div className="user-profile__info">
        <h3 className="user-profile__name">{user.name}</h3>
      </div>

      <button
        type="button"
        className={`user-profile__follow ${isFollowing ? "is-following" : ""}`}
        onClick={toggleFollow}
        disabled={isPending}
        aria-pressed={isFollowing}
        aria-label={`${isFollowing ? "Unfollow" : "Follow"} ${user.name}`}
      >
        {isPending ? "…" : isFollowing ? "Following" : "Follow"}
      </button>
    </article>
  );
}
```

