## `UserCard.tsx`

```tsx
import { useState } from "react";
import "./UserCard.css";

export type UserCardProps = {
  /** Display name of the user. */
  name: string;
  /** Avatar image URL. Falls back to initials if missing or broken. */
  avatarUrl?: string;
  /** Optional @handle shown under the name. */
  handle?: string;
  /** Initial follow state (uncontrolled). */
  isFollowing?: boolean;
  /**
   * Called with the desired new state. May return a Promise — if it
   * rejects, the button reverts to its previous state.
   */
  onFollowChange?: (following: boolean) => void | Promise<void>;
  /** Disables the follow button entirely. */
  disabled?: boolean;
};

function initialsOf(name: string) {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("");
}

export function UserCard({
  name,
  avatarUrl,
  handle,
  isFollowing = false,
  onFollowChange,
  disabled = false,
}: UserCardProps) {
  const [following, setFollowing] = useState(isFollowing);
  const [pending, setPending] = useState(false);
  const [avatarBroken, setAvatarBroken] = useState(false);

  const showImage = Boolean(avatarUrl) && !avatarBroken;

  async function toggleFollow() {
    const next = !following;

    // Optimistic update so the UI feels instant.
    setFollowing(next);
    setPending(true);

    try {
      await onFollowChange?.(next);
    } catch (error) {
      // Roll back if the request failed.
      setFollowing(!next);
      console.error("Failed to update follow state:", error);
    } finally {
      setPending(false);
    }
  }

  return (
    <article className="user-card">
      <div className="user-card__avatar" aria-hidden="true">
        {showImage ? (
          <img
            src={avatarUrl}
            alt=""
            className="user-card__avatar-img"
            onError={() => setAvatarBroken(true)}
          />
        ) : (
          <span className="user-card__avatar-initials">{initialsOf(name)}</span>
        )}
      </div>

      <div className="user-card__info">
        <h3 className="user-card__name">{name}</h3>
        {handle && <p className="user-card__handle">@{handle}</p>}
      </div>

      <button
        type="button"
        className={`user-card__button ${
          following ? "user-card__button--following" : ""
        }`}
        onClick={toggleFollow}
        disabled={disabled || pending}
        aria-pressed={following}
        aria-busy={pending}
        aria-label={`${following ? "Unfollow" : "Follow"} ${name}`}
      >
        {pending ? "…" : following ? "Following" : "Follow"}
      </button>
    </article>
  );
}
```

