/**
 * Small, dependency-free helpers for formatting prices and dates.
 *
 * Requires TypeScript `lib: ["ES2020"]` or later (for `Intl.RelativeTimeFormat`
 * and the `dateStyle` / `timeStyle` date options).
 */

/* -------------------------------------------------------------------------- */
/* Errors                                                                     */
/* -------------------------------------------------------------------------- */

export class FormatError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "FormatError";
  }
}

/* -------------------------------------------------------------------------- */
/* Formatter cache (constructing Intl formatters is expensive)               */
/* -------------------------------------------------------------------------- */

const numberFormatters = new Map<string, Intl.NumberFormat>();
const dateFormatters = new Map<string, Intl.DateTimeFormat>();
const relativeFormatters = new Map<string, Intl.RelativeTimeFormat>();

/** Clears the memoized formatters. Useful in tests. */
export function clearFormatterCache(): void {
  numberFormatters.clear();
  dateFormatters.clear();
  relativeFormatters.clear();
}

function getNumberFormat(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let formatter = numberFormatters.get(key);
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options);
    numberFormatters.set(key, formatter);
  }
  return formatter;
}

function getDateFormat(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let formatter = dateFormatters.get(key);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, options);
    dateFormatters.set(key, formatter);
  }
  return formatter;
}

function getRelativeFormat(
  locale: string,
  options: Intl.RelativeTimeFormatOptions,
): Intl.RelativeTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let formatter = relativeFormatters.get(key);
  if (!formatter) {
    formatter = new Intl.RelativeTimeFormat(locale, options);
    relativeFormatters.set(key, formatter);
  }
  return formatter;
}

/* -------------------------------------------------------------------------- */
/* Prices                                                                     */
/* -------------------------------------------------------------------------- */

export interface PriceFormatOptions {
  /** BCP-47 locale. Default: `"en-US"`. */
  locale?: string;
  /** ISO 4217 currency code. Default: `"USD"`. */
  currency?: string;
  /** How to render the currency. Default: `"symbol"`. */
  currencyDisplay?: "symbol" | "narrowSymbol" | "code" | "name";
  /** Override the currency's default number of fraction digits. */
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  /** Use compact notation, e.g. `1.2K`. Default: `false`. */
  compact?: boolean;
  /** Prefix positive values with `+`. Default: `false`. */
  showSign?: boolean;
}

/**
 * Formats a monetary amount, e.g. `formatPrice(1234.5)` → `"$1,234.50"`.
 *
 * @throws {FormatError} if `value` is not a finite number.
 */
export function formatPrice(value: number, options: PriceFormatOptions = {}): string {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new FormatError(`Invalid price: ${String(value)}`);
  }

  const {
    locale = "en-US",
    currency = "USD",
    currencyDisplay = "symbol",
    minimumFractionDigits,
    maximumFractionDigits,
    compact = false,
    showSign = false,
  } = options;

  const intlOptions: Intl.NumberFormatOptions = {
    style: "currency",
    currency,
    currencyDisplay,
    notation: compact ? "compact" : "standard",
  };

  if (minimumFractionDigits !== undefined) {
    intlOptions.minimumFractionDigits = minimumFractionDigits;
  }
  if (maximumFractionDigits !== undefined) {
    intlOptions.maximumFractionDigits = maximumFractionDigits;
  }
  if (showSign) {
    intlOptions.signDisplay = "exceptZero";
  }

  return getNumberFormat(locale, intlOptions).format(value);
}

/**
 * Formats a price range, e.g. `"$10.00 – $20.00"`. Reversed bounds are swapped.
 */
export function formatPriceRange(
  min: number,
  max: number,
  options: PriceFormatOptions = {},
): string {
  const [low, high] = min <= max ? [min, max] : [max, min];
  return `${formatPrice(low, options)} – ${formatPrice(high, options)}`;
}

/**
 * Formats a plain number (no currency), e.g. `formatNumber(0.42)` → `"0.42"`.
 */
export function formatNumber(
  value: number,
  options: Intl.NumberFormatOptions & { locale?: string } = {},
): string {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new FormatError(`Invalid number: ${String(value)}`);
  }
  const { locale = "en-US", ...intlOptions } = options;
  return getNumberFormat(locale, intlOptions).format(value);
}

/**
 * Rounds to a fixed number of decimals without float drift.
 * `roundTo(1.005, 2)` → `1.01`
 */
export function roundTo(value: number, decimals = 2): number {
  if (!Number.isFinite(value)) {
    throw new FormatError(`Invalid number: ${String(value)}`);
  }
  const factor = 10 ** decimals;
  return Math.round((value + Number.EPSILON) * factor) / factor;
}

/* -------------------------------------------------------------------------- */
/* Dates                                                                      */
/* -------------------------------------------------------------------------- */

export type DateInput = Date | string | number;

export interface DateFormatOptions {
  /** BCP-47 locale. Default: `"en-US"`. */
  locale?: string;
  /** IANA time zone, e.g. `"Europe/Berlin"`. Default: the runtime's zone. */
  timeZone?: string;
  /** Convenience preset; ignored if `dateStyle`/`timeStyle` are given. */
  format?: "date" | "time" | "datetime";
  dateStyle?: "full" | "long" | "medium" | "short";
  timeStyle?: "full" | "long" | "medium" | "short";
  year?: "numeric" | "2-digit";
  month?: "numeric" | "2-digit" | "long" | "short" | "narrow";
  day?: "numeric" | "2-digit";
  weekday?: "long" | "short" | "narrow";
  hour?: "numeric" | "2-digit";
  minute?: "numeric" | "2-digit";
  second?: "numeric" | "2-digit";
  hour12?: boolean;
  timeZoneName?: "long" | "short" | "shortOffset" | "longOffset" | "shortGeneric" | "longGeneric";
}

/**
 * Normalizes a date input to a `Date`.
 *
 * Note: ISO date-only strings (`"2024-01-01"`) are parsed as **UTC**, while
 * date-time strings without an offset (`"2024-01-01T10:00"`) are parsed as
 * **local time**. Pass an explicit offset or a `Date` to avoid ambiguity.
 *
 * @throws {FormatError} if the value cannot be parsed.
 */
export function toDate(value: DateInput): Date {
  const date = value instanceof Date ? new Date(value.getTime()) : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new FormatError(`Invalid date: ${String(value)}`);
  }
  return date;
}

/**
 * Formats a date, e.g. `formatDate(new Date())` → `"1/15/2024"`.
 */
export function formatDate(value: DateInput, options: DateFormatOptions = {}): string {
  const date = toDate(value);
  const { locale = "en-US", format, ...rest } = options;

  const intlOptions: Intl.DateTimeFormatOptions = {};

  if (rest.dateStyle || rest.timeStyle) {
    if (rest.dateStyle) intlOptions.dateStyle = rest.dateStyle;
    if (rest.timeStyle) intlOptions.timeStyle = rest.timeStyle;
  } else if (format === "date") {
    intlOptions.dateStyle = "medium";
  } else if (format === "time") {
    intlOptions.timeStyle = "short";
  } else if (format === "datetime") {
    intlOptions.dateStyle = "medium";
    intlOptions.timeStyle = "short";
  } else {
    // Copy any explicitly provided component options.
    for (const [key, val] of Object.entries(rest)) {
      if (val !== undefined) {
        (intlOptions as Record<string, unknown>)[key] = val;
      }
    }
  }

  if (rest.timeZone) intlOptions.timeZone = rest.timeZone;
  if (rest.hour12 !== undefined) intlOptions.hour12 = rest.hour12;

  return getDateFormat(locale, intlOptions).format(date);
}

/** Formats only the time portion, e.g. `"3:04 PM"`. */
export function formatTime(value: DateInput, options: DateFormatOptions = {}): string {
  return formatDate(value, { ...options, format: "time" });
}

/** Formats date + time, e.g. `"Jan 15, 2024, 3:04 PM"`. */
export function formatDateTime(value: DateInput, options: DateFormatOptions = {}): string {
  return formatDate(value, { ...options, format: "datetime" });
}

export interface RelativeTimeOptions {
  /** BCP-47 locale. Default: `"en-US"`. */
  locale?: string;
  /** Reference point. Default: now. */
  now?: DateInput;
  /** `"auto"` renders "yesterday" instead of "1 day ago". Default: `"auto"`. */
  numeric?: "always" | "auto";
  style?: "long" | "short" | "narrow";
}

/**
 * Formats a date relative to another point in time, e.g. `"3 days ago"`.
 */
export function formatRelativeTime(
  value: DateInput,
  options: RelativeTimeOptions = {},
): string {
  const { locale = "en-US", now, numeric = "auto", style = "long" } = options;

  const date = toDate(value);
  const reference = now === undefined ? new Date() : toDate(now);
  const diffSeconds = (date.getTime() - reference.getTime()) / 1000;

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  for (const [unit, seconds] of units) {
    if (Math.abs(diffSeconds) >= seconds || unit === "second") {
      const amount = Math.round(diffSeconds / seconds);
      return getRelativeFormat(locale, { numeric, style }).format(amount, unit);
    }
  }

  /* istanbul ignore next — unreachable, the "second" unit always matches */
  return "";
}

/**
 * Formats a duration in milliseconds, e.g. `formatDuration(3_725_000)` → `"1h 2m 5s"`.
 */
export function formatDuration(milliseconds: number): string {
  if (!Number.isFinite(milliseconds)) {
    throw new FormatError(`Invalid duration: ${String(milliseconds)}`);
  }
  const totalSeconds = Math.floor(Math.abs(milliseconds) / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  const parts: string[] = [];
  if (hours) parts.push(`${hours}h`);
  if (hours || minutes) parts.push(`${minutes}m`);
  parts.push(`${seconds}s`);

  return (milliseconds < 0 ? "-" : "") + parts.join(" ");
}
```

## Usage

```ts
import {
  formatPrice,
  formatPriceRange,
  formatDate,
  formatDateTime,
  formatRelativeTime,
  formatDuration,
} from "./format";

formatPrice(1234.5);                                  // "$1,234.50"
formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }); // "1.234,50 €"
formatPrice(1_250_000, { compact: true });            // "$1.3M"
formatPrice(9.99, { currencyDisplay: "code" });       // "USD 9.99"
formatPriceRange(10, 20);                             // "$10.00 – $20.00"

formatDate(new Date());                               // "1/15/2024"
formatDate("2024-01-15T10:30:00Z", { timeZone: "UTC", format: "datetime" });
formatDate("2024-01-15", { dateStyle: "full" });      // "Monday, January 15, 2024"
formatRelativeTime(new Date(Date.now() - 3 * 86_400_000)); // "3 days ago"
formatDuration(3_725_000);                            // "1h 2m 5s"
```

### Design notes
- **Invalid input throws `FormatError`** rather than silently rendering `"NaN"` / `"Invalid Date"` — easier to test and to surface bugs.
- **Formatters are memoized** by locale + options, since `Intl` constructors are comparatively slow.
- **Locale/time zone are options, not hard-coded**, so the same helpers work for i18n and for rendering in a user's zone.
- `toDate` copies `Date` instances so callers can't mutate the formatter's input.

```ts
// formatters.ts

export interface FormatPriceOptions {
  /** ISO 4217 currency code, e.g. "USD", "EUR". Defaults to "USD". */
  currency?: string;
  /** BCP 47 locale tag, e.g. "en-US", "de-DE". Defaults to the runtime locale. */
  locale?: string;
  /** Minimum number of fraction digits to show. */
  minimumFractionDigits?: number;
  /** Maximum number of fraction digits to show. */
  maximumFractionDigits?: number;
  /** Render negative amounts as "(12.00)" instead of "-$12.00". */
  accounting?: boolean;
}

export interface FormatDateOptions {
  /** BCP 47 locale tag. Defaults to the runtime locale. */
  locale?: string;
  /** Full date style, e.g. "long" | "medium" | "short". */
  dateStyle?: "full" | "long" | "medium" | "short";
  /** Full time style, e.g. "long" | "medium" | "short". */
  timeStyle?: "full" | "long" | "medium" | "short";
  /** Time zone, e.g. "UTC", "America/New_York". Defaults to the runtime zone. */
  timeZone?: string;
}

const priceFormatterCache = new Map<string, Intl.NumberFormat>();
const dateFormatterCache = new Map<string, Intl.DateTimeFormat>();

/**
 * Formats a number as a currency string.
 *
 * @example formatPrice(1234.5) // "$1,234.50" (en-US, USD)
 * @example formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }) // "1.234,50 €"
 */
export function formatPrice(value: number, options: FormatPriceOptions = {}): string {
  if (!Number.isFinite(value)) {
    throw new TypeError(`Cannot format non-finite price: ${value}`);
  }

  const {
    currency = "USD",
    locale,
    minimumFractionDigits,
    maximumFractionDigits,
    accounting = false,
  } = options;

  const key = JSON.stringify([locale, currency, minimumFractionDigits, maximumFractionDigits, accounting]);
  let formatter = priceFormatterCache.get(key);

  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      currencyDisplay: "narrowSymbol",
      minimumFractionDigits,
      maximumFractionDigits,
      ...(accounting ? { currencySign: "accounting" } : {}),
    });
    priceFormatterCache.set(key, formatter);
  }

  return formatter.format(value);
}

/**
 * Formats a date (Date, ISO string, or epoch millis) as a human-readable string.
 *
 * @example formatDate(new Date()) // "Aug 12, 2025"
 * @example formatDate("2025-08-12T10:30:00Z", { dateStyle: "full", timeZone: "UTC" })
 */
export function formatDate(
  input: Date | string | number,
  options: FormatDateOptions = {},
): string {
  const date = toDate(input);
  const { locale, dateStyle = "medium", timeStyle, timeZone } = options;

  const key = JSON.stringify([locale, dateStyle, timeStyle, timeZone]);
  let formatter = dateFormatterCache.get(key);

  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, {
      dateStyle,
      ...(timeStyle ? { timeStyle } : {}),
      ...(timeZone ? { timeZone } : {}),
    });
    dateFormatterCache.set(key, formatter);
  }

  return formatter.format(date);
}

/**
 * Formats a date relative to now, e.g. "3 days ago" / "in 2 hours".
 */
export function formatRelativeDate(
  input: Date | string | number,
  options: { locale?: string; now?: Date } = {},
): string {
  const date = toDate(input);
  const now = options.now ?? new Date();
  const diffMs = date.getTime() - now.getTime();

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 365 * 24 * 60 * 60 * 1000],
    ["month", 30 * 24 * 60 * 60 * 1000],
    ["week", 7 * 24 * 60 * 60 * 1000],
    ["day", 24 * 60 * 60 * 1000],
    ["hour", 60 * 60 * 1000],
    ["minute", 60 * 1000],
    ["second", 1000],
  ];

  const formatter = new Intl.RelativeTimeFormat(options.locale, { numeric: "auto" });

  for (const [unit, ms] of units) {
    if (Math.abs(diffMs) >= ms || unit === "second") {
      return formatter.format(Math.round(diffMs / ms), unit);
    }
  }

  return formatter.format(0, "second");
}

/** Converts a Date | ISO string | epoch millis into a valid Date, or throws. */
export function toDate(input: Date | string | number): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}
