Notes:
- Uses the built-in `Intl` API, so no dependencies and locale-aware output.
- `Intl` formatter instances are cached by option key to avoid re-creating them on hot paths.
- Invalid input throws `TypeError` (non-finite price) or `RangeError` (invalid date) rather than silently producing `"NaN"`.

## `src/formatters.ts`

```ts
/**
 * Small, dependency-free helpers for formatting prices and dates.
 * Uses the built-in `Intl` APIs, so results respect the given locale.
 */

export type DateInput = Date | string | number;

/* ------------------------------------------------------------------ */
/* Prices                                                              */
/* ------------------------------------------------------------------ */

export interface PriceFormatOptions {
  /** BCP 47 locale tag, e.g. "en-US", "de-DE". Default: "en-US". */
  locale?: string;
  /** ISO 4217 currency code. Only used when `style` is "currency". Default: "USD". */
  currency?: string;
  /** Formatting style. Default: "currency". */
  style?: "currency" | "decimal" | "percent";
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  /** Use compact notation, e.g. 1.2K. Default: false. */
  compact?: boolean;
  signDisplay?: Intl.NumberFormatOptions["signDisplay"];
}

const numberFormatterCache = new Map<string, Intl.NumberFormat>();

function getNumberFormatter(options: PriceFormatOptions): Intl.NumberFormat {
  const {
    locale = "en-US",
    currency = "USD",
    style = "currency",
    compact = false,
    ...rest
  } = options;

  const intlOptions: Intl.NumberFormatOptions = {
    style,
    ...rest,
    ...(compact ? { notation: "compact" as const } : {}),
  };
  if (style === "currency") intlOptions.currency = currency;

  const key = JSON.stringify([locale, intlOptions]);
  let formatter = numberFormatterCache.get(key);
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, intlOptions);
    numberFormatterCache.set(key, formatter);
  }
  return formatter;
}

/**
 * Format a numeric amount as a price.
 *
 * @throws {RangeError} if `amount` is not a finite number.
 *
 * @example
 * formatPrice(1234.5);                                  // "$1,234.50"
 * formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }); // "1.234,50 €"
 * formatPrice(0.156, { style: "percent" });             // "16%"
 */
export function formatPrice(amount: number, options: PriceFormatOptions = {}): string {
  if (typeof amount !== "number" || !Number.isFinite(amount)) {
    throw new RangeError(`Invalid price: ${String(amount)}`);
  }
  return getNumberFormatter(options).format(amount);
}

/* ------------------------------------------------------------------ */
/* Dates                                                               */
/* ------------------------------------------------------------------ */

export interface DateFormatOptions extends Intl.DateTimeFormatOptions {
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
}

const dateFormatterCache = new Map<string, Intl.DateTimeFormat>();

/**
 * Convert a date-like value into a valid `Date`.
 *
 * @throws {RangeError} if the value cannot be parsed as a date.
 */
export function parseDate(value: DateInput): Date {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(value)}`);
  }
  return date;
}

/**
 * Format a date. When no date components are supplied, a medium date
 * style (e.g. "Jan 5, 2024") is used.
 *
 * @example
 * formatDate("2024-01-05");                                  // "Jan 5, 2024"
 * formatDate("2024-01-05", { year: "numeric", month: "long", day: "numeric" });
 * formatDate("2024-01-05T14:30:00Z", { timeZone: "UTC", hour: "2-digit", minute: "2-digit" });
 */
export function formatDate(value: DateInput, options: DateFormatOptions = {}): string {
  const date = parseDate(value);
  const { locale = "en-US", ...intlOptions } = options;

  const resolved: Intl.DateTimeFormatOptions =
    Object.keys(intlOptions).length > 0 ? intlOptions : { dateStyle: "medium" };

  const key = JSON.stringify([locale, resolved]);
  let formatter = dateFormatterCache.get(key);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, resolved);
    dateFormatterCache.set(key, formatter);
  }
  return formatter.format(date);
}

/**
 * Format a date and time together.
 *
 * @example
 * formatDateTime("2024-01-05T14:30:00Z", { timeZone: "UTC" }); // "Jan 5, 2024, 02:30 PM"
 */
export function formatDateTime(value: DateInput, options: DateFormatOptions = {}): string {
  const { locale = "en-US", ...rest } = options;
  return formatDate(value, {
    locale,
    dateStyle: "medium",
    timeStyle: "short",
    ...rest,
  });
}

export interface RelativeDateOptions {
  locale?: string;
  /** Reference point for the comparison. Default: current time. */
  now?: Date;
}

const RELATIVE_UNITS: Array<[Intl.RelativeTimeFormatUnit, number]> = [
  ["year", 31_536_000],
  ["month", 2_592_000],
  ["week", 604_800],
  ["day", 86_400],
  ["hour", 3_600],
  ["minute", 60],
  ["second", 1],
];

/**
 * Format a date relative to another point in time.
 *
 * @example
 * formatRelativeDate(new Date(Date.now() - 3 * 86_400_000)); // "3 days ago"
 */
export function formatRelativeDate(
  value: DateInput,
  options: RelativeDateOptions = {},
): string {
  const date = parseDate(value);
  const now = options.now ?? new Date();
  const diffMs = date.getTime() - now.getTime();
  const absSeconds = Math.abs(diffMs) / 1000;

  const formatter = new Intl.RelativeTimeFormat(options.locale ?? "en-US", {
    numeric: "auto",
  });

  for (const [unit, seconds] of RELATIVE_UNITS) {
    if (absSeconds >= seconds || unit === "second") {
      return formatter.format(Math.round(diffMs / 1000 / seconds), unit);
    }
  }
  /* istanbul ignore next -- unreachable: the loop always returns at "second" */
  return formatter.format(0, "second");
}
