Notes:
- Requires `lib: ["ES2020"]` (or later) in `tsconfig.json` for `Intl.RelativeTimeFormat`; Node 14+ / modern browsers work out of the box.
- Formatter instances are cached by option key, so repeated calls avoid re-creating `Intl` objects.
- Invalid inputs throw a `RangeError` rather than silently producing `"NaN"`.

Below is a self-contained, dependency-free module. It uses `Intl` under the hood, caches formatters (they're expensive to construct), and throws on invalid input rather than silently producing `"NaN"`.

```ts
/**
 * format.ts — small helpers for formatting prices and dates.
 *
 * Requires `lib: ["ES2020"]` (or later) in tsconfig.json for
 * `Intl.RelativeTimeFormat` and `Intl.NumberFormatOptions.signDisplay`.
 */

/* -------------------------------------------------------------------------- */
/* Types                                                                      */
/* -------------------------------------------------------------------------- */

/** Anything that can be turned into a `Date`. */
export type DateInput = Date | number | string;

export type CurrencyDisplay = "symbol" | "narrowSymbol" | "code" | "name";
export type PriceNotation = "standard" | "compact";
export type CompactDisplay = "short" | "long";
export type DateStyle = "full" | "long" | "medium" | "short";
export type TimeStyle = "full" | "long" | "medium" | "short";

const DEFAULT_LOCALE = "en-US";
const DEFAULT_CURRENCY = "USD";

/* -------------------------------------------------------------------------- */
/* Prices                                                                     */
/* -------------------------------------------------------------------------- */

export interface PriceFormatOptions {
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
  /** ISO 4217 currency code. Default: "USD". */
  currency?: string;
  /** How to render the currency. Default: "symbol". */
  currencyDisplay?: CurrencyDisplay;
  /** Treat the input as minor units (cents, pence, …) instead of major units. */
  minorUnits?: boolean;
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  /** "compact" renders 1_200_000 as "$1.2M". Default: "standard". */
  notation?: PriceNotation;
  compactDisplay?: CompactDisplay;
  /** Prefix positive amounts with an explicit "+". */
  showSign?: boolean;
  /** Appended verbatim after the amount, e.g. " /mo". */
  suffix?: string;
}

const numberFormatters = new Map<string, Intl.NumberFormat>();

function getNumberFormatter(
  locale: string,
  options: Intl.NumberFormatOptions,
): Intl.NumberFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let formatter = numberFormatters.get(key);
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options);
    numberFormatters.set(key, formatter);
  }
  return formatter;
}

/** Decimal places the currency actually uses (JPY = 0, USD = 2, BHD = 3, …). */
function currencyFractionDigits(locale: string, currency: string): number {
  return new Intl.NumberFormat(locale, { style: "currency", currency }).resolvedOptions()
    .maximumFractionDigits;
}

/**
 * Format a monetary amount.
 *
 * @throws {TypeError} if `amount` is not a finite number.
 *
 * @example
 * formatPrice(1234.5);                                  // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }); // "1.234,50 €"
 * formatPrice(1999, { minorUnits: true });              // "$19.99"
 * formatPrice(1200000, { notation: "compact" });        // "$1.2M"
 */
export function formatPrice(amount: number, options: PriceFormatOptions = {}): string {
  const {
    locale = DEFAULT_LOCALE,
    currency = DEFAULT_CURRENCY,
    currencyDisplay = "symbol",
    minorUnits = false,
    minimumFractionDigits,
    maximumFractionDigits,
    notation = "standard",
    compactDisplay,
    showSign = false,
    suffix = "",
  } = options;

  if (typeof amount !== "number" || !Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: expected a finite number, received ${String(amount)}`);
  }

  const value = minorUnits
    ? Math.round(amount) / 10 ** currencyFractionDigits(locale, currency)
    : amount;

  const intlOptions = {
    style: "currency",
    currency,
    currencyDisplay,
    notation,
    signDisplay: showSign ? "exceptZero" : "auto",
    ...(minimumFractionDigits !== undefined ? { minimumFractionDigits } : {}),
    ...(maximumFractionDigits !== undefined ? { maximumFractionDigits } : {}),
    ...(notation === "compact" && compactDisplay !== undefined ? { compactDisplay } : {}),
  } as Intl.NumberFormatOptions;

  return `${getNumberFormatter(locale, intlOptions).format(value)}${suffix}`;
}

/**
 * Format a price range. A `suffix` is applied once, at the end.
 *
 * @example
 * formatPriceRange(10, 20);                    // "$10.00 – $20.00"
 * formatPriceRange(10, 20, { suffix: " /mo" }); // "$10.00 – $20.00 /mo"
 */
export function formatPriceRange(
  min: number,
  max: number,
  options: PriceFormatOptions = {},
): string {
  const { suffix = "", ...rest } = options;
  const low = Math.min(min, max);
  const high = Math.max(min, max);

  if (low === high) return formatPrice(low, { ...rest, suffix });

  return `${formatPrice(low, rest)} – ${formatPrice(high, rest)}${suffix}`;
}

/* -------------------------------------------------------------------------- */
/* Dates                                                                      */
/* -------------------------------------------------------------------------- */

export interface DateFormatOptions {
  locale?: string;
  /** IANA time zone, e.g. "America/New_York". */
  timeZone?: string;
  /** Preset date style. Mutually exclusive with the component options below. */
  dateStyle?: DateStyle;
  /** Preset time style. Mutually exclusive with the component options below. */
  timeStyle?: TimeStyle;
  /** Individual date/time components (used when no style is given). */
  year?: "numeric" | "2-digit";
  month?: "numeric" | "2-digit" | "long" | "short" | "narrow";
  day?: "numeric" | "2-digit";
  weekday?: "long" | "short" | "narrow";
  hour?: "numeric" | "2-digit";
  minute?: "numeric" | "2-digit";
  second?: "numeric" | "2-digit";
  hour12?: boolean;
  timeZoneName?: "long" | "short";
}

/** Component keys that count as "the caller picked parts explicitly". */
const DATE_COMPONENT_KEYS: readonly string[] = [
  "weekday",
  "era",
  "year",
  "month",
  "day",
  "hour",
  "minute",
  "second",
  "fractionalSecondDigits",
  "dayPeriod",
  "hour12",
  "hourCycle",
  "calendar",
  "numberingSystem",
  "timeZoneName",
];

const dateFormatters = new Map<string, Intl.DateTimeFormat>();

function getDateFormatter(
  locale: string,
  options: Intl.DateTimeFormatOptions,
): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let formatter = dateFormatters.get(key);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, options);
    dateFormatters.set(key, formatter);
  }
  return formatter;
}

/**
 * Convert a `DateInput` into a valid `Date`.
 *
 * @throws {RangeError} if the value cannot be parsed.
 */
export function toDate(value: DateInput): Date {
  const date = value instanceof Date ? new Date(value.getTime()) : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`toDate: could not parse ${JSON.stringify(value)}`);
  }
  return date;
}

function hasDateComponents(options: object): boolean {
  const source = options as Record<string, unknown>;
  return DATE_COMPONENT_KEYS.some((key) => source[key] !== undefined);
}

/** Build the `Intl` options, preferring styles over individual components. */
function buildDateTimeOptions(options: DateFormatOptions): Intl.DateTimeFormatOptions {
  const { dateStyle, timeStyle, timeZone } = options;
  const result: Record<string, unknown> = {};

  if (timeZone) result.timeZone = timeZone;

  if (dateStyle || timeStyle) {
    if (dateStyle) result.dateStyle = dateStyle;
    if (timeStyle) result.timeStyle = timeStyle;
    return result as Intl.DateTimeFormatOptions;
  }

  const source = options as Record<string, unknown>;
  for (const key of DATE_COMPONENT_KEYS) {
    if (source[key] !== undefined) result[key] = source[key];
  }

  return result as Intl.DateTimeFormatOptions;
}

/**
 * Format a date. Defaults to a medium date style ("Jan 1, 2024").
 *
 * @example
 * formatDate("2024-01-15");                                  // "Jan 15, 2024"
 * formatDate(new Date(), { dateStyle: "full" });              // "Monday, January 15, 2024"
 * formatDate(ts, { year: "numeric", month: "long", day: "numeric" });
 * formatDate(ts, { timeZone: "Asia/Tokyo", dateStyle: "short" });
 */
export function formatDate(value: DateInput, options: DateFormatOptions = {}): string {
  const { locale = DEFAULT_LOCALE } = options;
  const date = toDate(value);
  const intlOptions = buildDateTimeOptions(options);

  if (!intlOptions.dateStyle && !intlOptions.timeStyle && !hasDateComponents(intlOptions)) {
    intlOptions.dateStyle = "medium";
  }

  return getDateFormatter(locale, intlOptions).format(date);
}

/**
 * Format a date and time. Defaults to medium date + short time.
 *
 * @example
 * formatDateTime("2024-01-15T15:04:05Z"); // "Jan 15, 2024, 3:04 PM"
 */
export function formatDateTime(value: DateInput, options: DateFormatOptions = {}): string {
  const { dateStyle, timeStyle } = options;

  if (!dateStyle && !timeStyle && !hasDateComponents(options)) {
    return formatDate(value, { ...options, dateStyle: "medium", timeStyle: "short" });
  }

  return formatDate(value, options);
}

export interface RelativeTimeOptions {
  locale?: string;
  /** Reference point. Default: now. */
  now?: DateInput;
  /** "auto" gives "yesterday"/"tomorrow"/"now"; "always" gives "1 day ago". */
  numeric?: "auto" | "always";
}

const SECOND = 1;
const MINUTE = 60 * SECOND;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;
const MONTH = 30.436875 * DAY; // average Gregorian month
const YEAR = 365.2425 * DAY; // average Gregorian year

/**
 * Format a date relative to another point in time ("3 hours ago").
 *
 * @example
 * formatRelativeTime(Date.now() - 90_000);            // "2 minutes ago"
 * formatRelativeTime(Date.now() + 86_400_000);        // "tomorrow"
 * formatRelativeTime(ts, { now: reference, numeric: "always" });
 */
export function formatRelativeTime(
  value: DateInput,
  options: RelativeTimeOptions = {},
): string {
  const { locale = DEFAULT_LOCALE, now = Date.now(), numeric = "auto" } = options;
  const target = toDate(value);
  const reference = toDate(now);

  const diffSeconds = (target.getTime() - reference.getTime()) / 1000;
  const magnitude = Math.abs(diffSeconds);

  let unit: Intl.RelativeTimeFormatUnit;
  let amount: number;

  if (magnitude < MINUTE) {
    unit = "second";
    amount = Math.trunc(diffSeconds);
  } else if (magnitude < HOUR) {
    unit = "minute";
    amount = Math.round(diffSeconds / MINUTE);
  } else if (magnitude < DAY) {
    unit = "hour";
    amount = Math.round(diffSeconds / HOUR);
  } else if (magnitude < MONTH) {
    unit = "day";
    amount = Math.round(diffSeconds / DAY);
  } else if (magnitude < YEAR) {
    unit = "month";
    amount = Math.round(diffSeconds / MONTH);
  } else {
    unit = "year";
    amount = Math.round(diffSeconds / YEAR);
  }

  return new Intl.RelativeTimeFormat(locale, { numeric }).format(amount, unit);
}
```

### Usage

```ts
import { formatPrice, formatPriceRange, formatDate, formatDateTime, formatRelativeTime } from "./format";

formatPrice(1234.5);                                    // "$1,234.50"
formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }); // "1.234,50 €"
formatPrice(1999, { minorUnits: true });                // "$19.99"
formatPrice(1200000, { notation: "compact" });          // "$1.2M"
formatPrice(49, { showSign: true, suffix: " /mo" });    // "+$49.00 /mo"
formatPriceRange(10, 20, { suffix: " /mo" });           // "$10.00 – $20.00 /mo"

formatDate("2024-01-15");                               // "Jan 15, 2024"
formatDate("2024-01-15", { dateStyle: "full" });        // "Monday, January 15, 2024"
formatDate("2024-01-15", { timeZone: "Asia/Tokyo" });   // "Jan 15, 2024"
formatDateTime("2024-01-15T15:04:05Z");                 // "Jan 15, 2024, 3:04 PM"
formatRelativeTime(Date.now() - 90_000);                // "2 minutes ago"
```

### Notes

- **tsconfig**: set `"lib": ["ES2020"]` (or `"target": "ES2020"`) — `Intl.RelativeTimeFormat` and `signDisplay` need it. Node 14+ ships full ICU by default, so locale data is available.
- **Error handling**: invalid prices throw `TypeError`, unparseable dates throw `RangeError`. If you'd rather get `"—"` back, wrap the calls at the call site.
- **Time zones**: `formatDate`/`formatDateTime` accept an IANA `timeZone`; without one they use the runtime's local zone. `formatRelativeTime` compares absolute instants, so it's zone-independent.
- **Caching**: formatters are memoized per locale + options, so calling these in a list render is cheap.

```ts
// formatters.ts

export interface PriceOptions {
  /** BCP 47 locale tag, e.g. "en-US" or "de-DE". */
  locale?: string;
  /** ISO 4217 currency code, e.g. "USD" or "EUR". */
  currency?: string;
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  /** Render as a compact string, e.g. "$1.2K". */
  compact?: boolean;
}

export interface DateOptions {
  locale?: string;
  /** e.g. "short", "medium", "long", "full". */
  dateStyle?: "short" | "medium" | "long" | "full";
  /** e.g. "short", "medium", "long", "full". */
  timeStyle?: "short" | "medium" | "long" | "full";
  timeZone?: string;
}

export interface RelativeTimeOptions {
  locale?: string;
  /** Reference point for relative output; defaults to now. */
  now?: Date;
}

/** Formats a number as a currency string. */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  const {
    locale = "en-US",
    currency = "USD",
    minimumFractionDigits,
    maximumFractionDigits,
    compact = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new RangeError(`Cannot format non-finite amount: ${amount}`);
  }

  const formatOptions: Intl.NumberFormatOptions = {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
  };

  if (minimumFractionDigits !== undefined) {
    formatOptions.minimumFractionDigits = minimumFractionDigits;
  }
  if (maximumFractionDigits !== undefined) {
    formatOptions.maximumFractionDigits = maximumFractionDigits;
  }

  return new Intl.NumberFormat(locale, formatOptions).format(amount);
}

/** Formats a date (or timestamp) using locale-aware styles. */
export function formatDate(input: Date | number | string, options: DateOptions = {}): string {
  const { locale = "en-US", dateStyle = "medium", timeStyle, timeZone } = options;
  const date = toDate(input);

  const formatOptions: Intl.DateTimeFormatOptions = { dateStyle };
  if (timeStyle) formatOptions.timeStyle = timeStyle;
  if (timeZone) formatOptions.timeZone = timeZone;

  return new Intl.DateTimeFormat(locale, formatOptions).format(date);
}

/** Formats a date and time, e.g. "Jan 5, 2024, 3:20 PM". */
export function formatDateTime(
  input: Date | number | string,
  options: DateOptions = {},
): string {
  return formatDate(input, { dateStyle: "medium", timeStyle: "short", ...options });
}

/** Formats a date relative to now, e.g. "3 days ago" or "in 2 hours". */
export function formatRelativeTime(
  input: Date | number | string,
  options: RelativeTimeOptions = {},
): string {
  const { locale = "en-US", now = new Date() } = options;
  const date = toDate(input);
  const diffMs = date.getTime() - now.getTime();

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 365 * 24 * 60 * 60 * 1000],
    ["month", 30 * 24 * 60 * 60 * 1000],
    ["week", 7 * 24 * 60 * 60 * 1000],
    ["day", 24 * 60 * 60 * 1000],
    ["hour", 60 * 60 * 1000],
    ["minute", 60 * 1000],
    ["second", 1000],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, ms] of units) {
    if (Math.abs(diffMs) >= ms || unit === "second") {
      return rtf.format(Math.round(diffMs / ms), unit);
    }
  }

  return rtf.format(0, "second");
}

function toDate(input: Date | number | string): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}
