/**
 * Formatting helpers for prices and dates.
 * Zero dependencies — built on the platform `Intl` API.
 *
 * Requires `lib: ["ES2021"]` (or newer) for `dateStyle`/`timeStyle`
 * and `Intl.RelativeTimeFormat`.
 */

/* ------------------------------------------------------------------ */
/* Types                                                               */
/* ------------------------------------------------------------------ */

export type DateInput = Date | string | number;

export interface PriceOptions {
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
  /** ISO 4217 currency code. Default: "USD". */
  currency?: string;
  /** Fixed number of fraction digits. Default: 2. */
  fractionDigits?: number;
  /** Use compact notation, e.g. "$1.2K". Default: false. */
  compact?: boolean;
  /** Returned for invalid input. Default: "—". */
  fallback?: string;
}

export interface DateOptions {
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
  /** Default: "medium". */
  dateStyle?: "short" | "medium" | "long" | "full";
  /** IANA time zone, e.g. "Europe/Berlin". Default: the runtime's zone. */
  timeZone?: string;
  /** Returned for invalid input. Default: "—". */
  fallback?: string;
}

export interface DateTimeOptions extends DateOptions {
  /** Default: "short". */
  timeStyle?: "short" | "medium" | "long" | "full";
}

export interface RelativeTimeOptions {
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
  /** Reference point in ms since epoch. Default: `Date.now()`. */
  now?: number;
  /** Returned for invalid input. Default: "—". */
  fallback?: string;
}

/* ------------------------------------------------------------------ */
/* Internals                                                           */
/* ------------------------------------------------------------------ */

const DEFAULT_LOCALE = "en-US";
const DEFAULT_FALLBACK = "—";

/** Normalizes any supported date input to a valid `Date`, or `null`. */
function toDate(value: DateInput): Date | null {
  const date =
    value instanceof Date
      ? value
      : typeof value === "number"
        ? new Date(value)
        : new Date(value);

  return Number.isNaN(date.getTime()) ? null : date;
}

/* ------------------------------------------------------------------ */
/* Prices                                                              */
/* ------------------------------------------------------------------ */

/**
 * Formats a number as a currency string.
 *
 * @example
 * formatPrice(1234.5)                       // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR" })  // "€1,234.50"
 * formatPrice(1234.5, { locale: "de-DE" })  // "1.234,50 $"
 * formatPrice(1234.5, { compact: true })    // "$1.2K"
 */
export function formatPrice(value: number, options: PriceOptions = {}): string {
  const {
    locale = DEFAULT_LOCALE,
    currency = "USD",
    fractionDigits = 2,
    compact = false,
    fallback = DEFAULT_FALLBACK,
  } = options;

  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;

  try {
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      notation: compact ? "compact" : "standard",
      minimumFractionDigits: fractionDigits,
      maximumFractionDigits: fractionDigits,
    }).format(value);
  } catch {
    // Invalid locale or currency code.
    return fallback;
  }
}

/**
 * Formats a number with grouping, without a currency symbol.
 *
 * @example
 * formatNumber(1234567)                    // "1,234,567"
 * formatNumber(0.42, { maximumFractionDigits: 1 }) // "0.4"
 */
export function formatNumber(
  value: number,
  options: {
    locale?: string;
    minimumFractionDigits?: number;
    maximumFractionDigits?: number;
    fallback?: string;
  } = {},
): string {
  const {
    locale = DEFAULT_LOCALE,
    minimumFractionDigits = 0,
    maximumFractionDigits = 2,
    fallback = DEFAULT_FALLBACK,
  } = options;

  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;

  try {
    return new Intl.NumberFormat(locale, {
      minimumFractionDigits,
      maximumFractionDigits,
    }).format(value);
  } catch {
    return fallback;
  }
}

/* ------------------------------------------------------------------ */
/* Dates                                                               */
/* ------------------------------------------------------------------ */

/**
 * Formats a date.
 *
 * @example
 * formatDate(new Date("2024-03-09T12:00:00Z"))                  // "Mar 9, 2024"
 * formatDate("2024-03-09", { dateStyle: "long" })                // "March 9, 2024"
 * formatDate("2024-03-09", { locale: "de-DE", dateStyle: "short" }) // "09.03.24"
 */
export function formatDate(value: DateInput, options: DateOptions = {}): string {
  const {
    locale = DEFAULT_LOCALE,
    dateStyle = "medium",
    timeZone,
    fallback = DEFAULT_FALLBACK,
  } = options;

  const date = toDate(value);
  if (!date) return fallback;

  try {
    return new Intl.DateTimeFormat(locale, { dateStyle, timeZone }).format(date);
  } catch {
    return fallback;
  }
}

/**
 * Formats a date and time.
 *
 * @example
 * formatDateTime("2024-03-09T14:30:00Z", { timeZone: "UTC" }) // "Mar 9, 2024, 2:30 PM"
 */
export function formatDateTime(
  value: DateInput,
  options: DateTimeOptions = {},
): string {
  const {
    locale = DEFAULT_LOCALE,
    dateStyle = "medium",
    timeStyle = "short",
    timeZone,
    fallback = DEFAULT_FALLBACK,
  } = options;

  const date = toDate(value);
  if (!date) return fallback;

  try {
    return new Intl.DateTimeFormat(locale, { dateStyle, timeStyle, timeZone }).format(
      date,
    );
  } catch {
    return fallback;
  }
}

const RELATIVE_UNITS: Array<[Intl.RelativeTimeFormatUnit, number]> = [
  ["year", 60 * 60 * 24 * 365],
  ["month", 60 * 60 * 24 * 30],
  ["week", 60 * 60 * 24 * 7],
  ["day", 60 * 60 * 24],
  ["hour", 60 * 60],
  ["minute", 60],
  ["second", 1],
];

/**
 * Formats a date relative to a reference point.
 *
 * @example
 * formatRelativeTime(Date.now() - 90_000) // "2 minutes ago"
 * formatRelativeTime(Date.now() + 3_600_000) // "in 1 hour"
 */
export function formatRelativeTime(
  value: DateInput,
  options: RelativeTimeOptions = {},
): string {
  const { locale = DEFAULT_LOCALE, now = Date.now(), fallback = DEFAULT_FALLBACK } = options;

  const date = toDate(value);
  if (!date) return fallback;

  const deltaSeconds = Math.round((date.getTime() - now) / 1000);

  try {
    const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
    for (const [unit, seconds] of RELATIVE_UNITS) {
      if (Math.abs(deltaSeconds) >= seconds || unit === "second") {
        return rtf.format(Math.round(deltaSeconds / seconds), unit);
      }
    }
    return rtf.format(0, "second");
  } catch {
    return fallback;
  }
}
