```ts
import { formatPrice, formatDate, formatDateTime, formatRelativeTime } from "./format";

formatPrice(19.99);                                  // "$19.99"
formatPrice(19.99, { currency: "GBP", locale: "en-GB" }); // "£19.99"
formatPrice(1_250_000, { compact: true });            // "$1.3M"
formatPrice(Number.NaN);                             // "—"

formatDate("2024-03-09");                            // "Mar 9, 2024"
formatDateTime("2024-03-09T14:30:00Z", { timeZone: "UTC" });
formatRelativeTime(new Date(Date.now() - 3 * 86_400_000)); // "3 days ago"
```

## Notes

- **Invalid input never throws** — bad locales, currency codes, or unparseable dates fall back to `"—"` (overridable via `fallback`).
- **Locale-aware output** — grouping separators, symbol placement, and month names come from `Intl`, so `de-DE` gives `1.234,50 €` without extra code.
- **Time zones** — `formatDate`/`formatDateTime` accept an IANA `timeZone`; without one they use the runtime's local zone.
- **Caching** — `Intl` formatters are relatively expensive to construct. If you format in a hot path (e.g. a table row), memoize the `Intl.NumberFormat`/`Intl.DateTimeFormat` instance per locale/currency combination rather than calling these helpers per row.

## `src/format.ts`

```ts
/**
 * Small formatting helpers for prices and dates.
 * Everything is built on the platform's `Intl` APIs, so output respects
 * the given locale (and the runtime's ICU data).
 */

export type DateInput = Date | string | number;

/* ------------------------------------------------------------------ */
/* Prices                                                              */
/* ------------------------------------------------------------------ */

export interface PriceFormatOptions {
  /** ISO 4217 currency code. Default: "USD". */
  currency?: string;
  /** BCP 47 locale tag, e.g. "de-DE". Default: runtime locale. */
  locale?: string;
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  /** Render compactly, e.g. "$1.2K". Default: false. */
  compact?: boolean;
}

/** Format a number as a currency string. Throws on non-finite input. */
export function formatPrice(amount: number, options: PriceFormatOptions = {}): string {
  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: expected a finite number, received ${amount}`);
  }

  const {
    currency = "USD",
    locale,
    minimumFractionDigits,
    maximumFractionDigits,
    compact = false,
  } = options;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
    ...(minimumFractionDigits !== undefined && { minimumFractionDigits }),
    ...(maximumFractionDigits !== undefined && { maximumFractionDigits }),
  }).format(amount);
}

export interface PercentFormatOptions {
  locale?: string;
  /** 0.15 -> "15%". Default: true. */
  scale?: boolean;
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
}

/** Format a ratio (0.15) or an already-scaled number (15) as a percentage. */
export function formatPercent(value: number, options: PercentFormatOptions = {}): string {
  if (!Number.isFinite(value)) {
    throw new TypeError(`formatPercent: expected a finite number, received ${value}`);
  }

  const { locale, scale = true, minimumFractionDigits, maximumFractionDigits } = options;

  return new Intl.NumberFormat(locale, {
    style: "percent",
    ...(minimumFractionDigits !== undefined && { minimumFractionDigits }),
    ...(maximumFractionDigits !== undefined && { maximumFractionDigits }),
  }).format(scale ? value : value / 100);
}

/* ------------------------------------------------------------------ */
/* Dates                                                               */
/* ------------------------------------------------------------------ */

export interface DateFormatOptions {
  locale?: string;
  /** IANA time zone, e.g. "Europe/Berlin". Default: runtime time zone. */
  timeZone?: string;
  dateStyle?: "full" | "long" | "medium" | "short";
  timeStyle?: "full" | "long" | "medium" | "short";
}

/** Convert any supported input into a valid `Date`, or throw. */
export function toDate(value: DateInput): Date {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`toDate: invalid date ${JSON.stringify(value)}`);
  }
  return date;
}

/** e.g. "Sep 4, 2025" */
export function formatDate(value: DateInput, options: DateFormatOptions = {}): string {
  const { locale, timeZone, dateStyle = "medium" } = options;
  return new Intl.DateTimeFormat(locale, { dateStyle, ...(timeZone && { timeZone }) }).format(
    toDate(value),
  );
}

/** e.g. "Sep 4, 2025, 2:30 PM" */
export function formatDateTime(value: DateInput, options: DateFormatOptions = {}): string {
  const { locale, timeZone, dateStyle = "medium", timeStyle = "short" } = options;
  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    timeStyle,
    ...(timeZone && { timeZone }),
  }).format(toDate(value));
}

/** e.g. "2:30 PM" */
export function formatTime(value: DateInput, options: DateFormatOptions = {}): string {
  const { locale, timeZone, timeStyle = "short" } = options;
  return new Intl.DateTimeFormat(locale, { timeStyle, ...(timeZone && { timeZone }) }).format(
    toDate(value),
  );
}

export interface RelativeTimeOptions {
  locale?: string;
  numeric?: "always" | "auto";
  style?: "long" | "short" | "narrow";
}

/** e.g. "3 days ago", "in 2 hours" (relative to `base`, default: now). */
export function formatRelativeTime(
  value: DateInput,
  base: DateInput = new Date(),
  options: RelativeTimeOptions = {},
): string {
  const { locale, numeric = "auto", style = "long" } = options;
  const diffMs = toDate(value).getTime() - toDate(base).getTime();

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 365 * 24 * 60 * 60 * 1000],
    ["month", 30 * 24 * 60 * 60 * 1000],
    ["week", 7 * 24 * 60 * 60 * 1000],
    ["day", 24 * 60 * 60 * 1000],
    ["hour", 60 * 60 * 1000],
    ["minute", 60 * 1000],
    ["second", 1000],
  ];

  const formatter = new Intl.RelativeTimeFormat(locale, { numeric, style });
  for (const [unit, ms] of units) {
    if (Math.abs(diffMs) >= ms || unit === "second") {
      return formatter.format(Math.round(diffMs / ms), unit);
    }
  }
  return formatter.format(0, "second"); // unreachable, kept for exhaustiveness
}
```

