- Invalid input (non-finite numbers, unparsable dates) throws a `TypeError` rather than silently producing `"NaN"`.
- `Intl` output depends on the runtime's ICU data; on Node, use a build with full-icu (the default since Node 14) for all locales.

```ts
// formatters.ts

export interface PriceOptions {
  /** BCP 47 locale tag, e.g. "en-US" or "de-DE". */
  locale?: string;
  /** ISO 4217 currency code, e.g. "USD" or "EUR". */
  currency?: string;
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  /** Render as a compact string, e.g. "$1.2K". */
  compact?: boolean;
}

export interface DateOptions {
  locale?: string;
  /** e.g. "short", "medium", "long", "full". */
  dateStyle?: "short" | "medium" | "long" | "full";
  /** e.g. "short", "medium", "long", "full". */
  timeStyle?: "short" | "medium" | "long" | "full";
  timeZone?: string;
}

/** Formats a number as a currency string. */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid price: ${amount}`);
  }

  const {
    locale = "en-US",
    currency = "USD",
    minimumFractionDigits,
    maximumFractionDigits,
    compact = false,
  } = options;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    compact,
    ...(minimumFractionDigits !== undefined ? { minimumFractionDigits } : {}),
    ...(maximumFractionDigits !== undefined ? { maximumFractionDigits } : {}),
  }).format(amount);
}

/** Formats a date (or timestamp) using the locale's date format. */
export function formatDate(date: Date | number | string, options: DateOptions = {}): string {
  const { locale = "en-US", dateStyle = "medium", timeZone } = options;
  const value = toDate(date);

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    ...(timeZone ? { timeZone } : {}),
  }).format(value);
}

/** Formats a date and time using the locale's date and time formats. */
export function formatDateTime(date: Date | number | string, options: DateOptions = {}): string {
  const { locale = "en-US", dateStyle = "medium", timeStyle = "short", timeZone } = options;
  const value = toDate(date);

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    timeStyle,
    ...(timeZone ? { timeZone } : {}),
  }).format(value);
}

/**
 * Formats a date relative to now, e.g. "3 days ago" or "in 2 hours".
 */
export function formatRelativeTime(
  date: Date | number | string,
  options: { locale?: string; now?: Date } = {},
): string {
  const { locale = "en-US", now = new Date() } = options;
  const value = toDate(date);

  const diffSeconds = Math.round((value.getTime() - now.getTime()) / 1000);
  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  const formatter = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, seconds] of units) {
    if (Math.abs(diffSeconds) >= seconds || unit === "second") {
      return formatter.format(Math.round(diffSeconds / seconds), unit);
    }
  }

  return formatter.format(0, "second");
}

function toDate(date: Date | number | string): Date {
  const value = date instanceof Date ? date : new Date(date);
  if (Number.isNaN(value.getTime())) {
    throw new RangeError(`Invalid date: ${String(date)}`);
  }
  return value;
}
