```ts
/**
 * Small, dependency-free helpers for formatting prices and dates.
 *
 * Everything is built on the platform `Intl` API, so output follows the
 * user's locale (currency symbols, digit grouping, month names, ...).
 */

/* ------------------------------------------------------------------ *
 * Prices
 * ------------------------------------------------------------------ */

/** Where to place the currency symbol relative to the amount. */
export type CurrencyPosition = 'auto' | 'before' | 'after';

export interface PriceFormatOptions {
  /** BCP 47 locale tag, e.g. "en-US", "de-DE". Defaults to the runtime locale. */
  locale?: string;
  /** ISO 4217 currency code, e.g. "USD", "EUR", "JPY". Defaults to "USD". */
  currency?: string;
  /** Number of fraction digits. Defaults to the currency's natural digits. */
  fractionDigits?: number;
  /** Use compact notation: 1234 -> "$1.23K". */
  compact?: boolean;
  /** "auto" keeps the locale's own placement (e.g. "1,00 €" in de-DE). */
  currencyPosition?: CurrencyPosition;
  /** Returned when the value is not a finite number. */
  fallback?: string;
}

/** The number of fraction digits a currency normally uses (JPY -> 0, USD -> 2). */
function defaultFractionDigits(locale: string | undefined, currency: string): number {
  try {
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
    }).resolvedOptions().maximumFractionDigits;
  } catch {
    return 2;
  }
}

/**
 * Format a monetary amount.
 *
 * @example
 * formatPrice(1234.5)                       // "$1,234.50"
 * formatPrice(1234.5, { locale: 'de-DE', currency: 'EUR' }) // "1.234,50 €"
 * formatPrice(1234.5, { currencyPosition: 'before' })       // "$ 1,234.50"
 * formatPrice(1_200_000, { compact: true })                 // "$1.2M"
 * formatPrice(Number.NaN)                                  // "—"
 */
export function formatPrice(value: number, options: PriceFormatOptions = {}): string {
  const {
    locale,
    currency = 'USD',
    compact = false,
    currencyPosition = 'auto',
    fallback = '—',
  } = options;

  if (typeof value !== 'number' || !Number.isFinite(value)) return fallback;
  if (!/^[A-Za-z]{3}$/.test(currency)) {
    throw new RangeError(`Invalid currency code: "${currency}"`);
  }

  const fractionDigits = options.fractionDigits ?? defaultFractionDigits(locale, currency);

  const formatter = new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
    notation: compact ? 'compact' : 'standard',
    // Compact notation reads better without forced trailing zeros.
    minimumFractionDigits: compact ? 0 : fractionDigits,
    maximumFractionDigits: fractionDigits,
  });

  const parts = formatter.formatToParts(value);
  if (currencyPosition === 'auto') return parts.map((p) => p.value).join('');

  const currencyPart = parts.find((p) => p.type === 'currency');
  if (!currencyPart) return parts.map((p) => p.value).join('');

  const amount = parts
    .filter((p) => p.type !== 'currency')
    .map((p) => p.value)
    .join('');

  return currencyPosition === 'before'
    ? `${currencyPart.value} ${amount}`.trim()
    : `${amount} ${currencyPart.value}`.trim();
}

/* ------------------------------------------------------------------ *
 * Dates
 * ------------------------------------------------------------------ */

/** Anything we accept as a point in time. */
export type DateInput = Date | string | number;

export interface DateFormatOptions {
  locale?: string;
  dateStyle?: 'full' | 'long' | 'medium' | 'short';
  timeStyle?: 'full' | 'long' | 'medium' | 'short';
  /** IANA time zone, e.g. "UTC", "America/New_York". */
  timeZone?: string;
  fallback?: string;
}

export interface RelativeTimeOptions {
  locale?: string;
  /** The moment to compare against. Defaults to now. */
  now?: Date;
  /** "auto" says "yesterday", "always" says "1 day ago". */
  numeric?: 'auto' | 'always';
  fallback?: string;
}

/**
 * Coerce a `DateInput` into a valid `Date`, or `null` if it can't be parsed.
 *
 * Note: date-only ISO strings ("2024-03-01") are parsed as UTC midnight,
 * while date-time strings without an offset are parsed as local time.
 */
export function parseDate(value: DateInput): Date | null {
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

/**
 * Format a date.
 *
 * @example
 * formatDate(new Date())                          // "Mar 1, 2024"
 * formatDate('2024-03-01', { dateStyle: 'full' })  // "Friday, March 1, 2024"
 * formatDate('2024-03-01', { locale: 'de-DE' })    // "01.03.2024"
 */
export function formatDate(value: DateInput, options: DateFormatOptions = {}): string {
  const { locale, dateStyle = 'medium', timeStyle, timeZone, fallback = '—' } = options;

  const date = parseDate(value);
  if (!date) return fallback;

  const intlOptions: Intl.DateTimeFormatOptions = { dateStyle };
  if (timeStyle) intlOptions.timeStyle = timeStyle;
  if (timeZone) intlOptions.timeZone = timeZone;

  return new Intl.DateTimeFormat(locale, intlOptions).format(date);
}

/**
 * Format a date *and* time.
 *
 * @example
 * formatDateTime('2024-03-01T14:30:00Z', { timeZone: 'UTC' }) // "Mar 1, 2024, 02:30 PM"
 */
export function formatDateTime(value: DateInput, options: DateFormatOptions = {}): string {
  return formatDate(value, { dateStyle: 'medium', timeStyle: 'short', ...options });
}

/**
 * Format a date relative to another moment ("3 days ago", "in 2 hours").
 *
 * @example
 * formatRelativeTime(Date.now() - 1000 * 60 * 60 * 24 * 3) // "3 days ago"
 */
export function formatRelativeTime(value: DateInput, options: RelativeTimeOptions = {}): string {
  const { locale, now = new Date(), numeric = 'auto', fallback = '—' } = options;

  const date = parseDate(value);
  if (!date) return fallback;

  const diffMs = date.getTime() - now.getTime();
  const absMs = Math.abs(diffMs);

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ['year', 365 * 24 * 60 * 60 * 1000],
    ['month', 30 * 24 * 60 * 60 * 1000],
    ['week', 7 * 24 * 60 * 60 * 1000],
    ['day', 24 * 60 * 60 * 1000],
    ['hour', 60 * 60 * 1000],
    ['minute', 60 * 1000],
    ['second', 1000],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric });
  for (const [unit, ms] of units) {
    if (absMs >= ms || unit === 'second') {
      return rtf.format(Math.round(diffMs / ms), unit);
    }
  }

  return fallback;
}
