```ts
/**
 * Small, locale-aware helpers for formatting prices and dates.
 * Requires `lib: ["ES2021"]` (or newer) in tsconfig for `dateStyle`/`timeStyle`.
 */

export interface PriceFormatOptions {
  /** BCP 47 locale tag, e.g. "en-US" or "de-DE". Default: "en-US". */
  locale?: string;
  /** ISO 4217 currency code, e.g. "USD", "EUR", "JPY". Default: "USD". */
  currency?: string;
  /** Minimum fraction digits to display. */
  minimumFractionDigits?: number;
  /** Maximum fraction digits to display. */
  maximumFractionDigits?: number;
  /** How to render negative amounts: "-$5.00" vs "($5.00)". Default: "sign". */
  negativeStyle?: "sign" | "accounting";
}

export interface DateFormatOptions {
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
  /** Date portion style. Default: "medium". */
  dateStyle?: "full" | "long" | "medium" | "short";
  /** Time portion style. Omit for date-only output. */
  timeStyle?: "full" | "long" | "medium" | "short";
  /** IANA time zone, e.g. "America/New_York". Default: runtime's zone. */
  timeZone?: string;
}

/**
 * Formats a number as a currency string.
 *
 * @example formatPrice(1234.5) // "$1,234.50"
 * @example formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }) // "1.234,50 €"
 */
export function formatPrice(amount: number, options: PriceFormatOptions = {}): string {
  if (!Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: expected a finite number, received ${amount}`);
  }

  const {
    locale = "en-US",
    currency = "USD",
    minimumFractionDigits,
    maximumFractionDigits,
    negativeStyle = "sign",
  } = options;

  const formatter = new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits,
    maximumFractionDigits,
    currencySign: negativeStyle === "accounting" ? "accounting" : "standard",
    signDisplay: negativeStyle === "accounting" ? "exceptZero" : "auto",
  });

  return formatter.format(amount);
}

/**
 * Formats a date (Date, ISO string, or timestamp) as a localized string.
 *
 * @example formatDate(new Date()) // "Jan 15, 2025"
 * @example formatDate("2025-01-15T18:30:00Z", { dateStyle: "full", timeStyle: "short" })
 */
export function formatDate(
  date: Date | string | number,
  options: DateFormatOptions = {},
): string {
  const { locale = "en-US", dateStyle = "medium", timeStyle, timeZone } = options;

  const parsed = date instanceof Date ? date : new Date(date);
  if (Number.isNaN(parsed.getTime())) {
    throw new RangeError(`formatDate: invalid date: ${String(date)}`);
  }

  return new Intl.DateTimeFormat(locale, { dateStyle, timeStyle, timeZone }).format(parsed);
}

/**
 * Convenience wrapper: date + time in one call.
 *
 * @example formatDateTime(new Date()) // "Jan 15, 2025, 6:30 PM"
 */
export function formatDateTime(
  date: Date | string | number,
  options: Omit<DateFormatOptions, "dateStyle" | "timeStyle"> = {},
): string {
  return formatDate(date, { ...options, dateStyle: "medium", timeStyle: "short" });
}
