```ts
/**
 * Small, dependency-free helpers for formatting prices and dates.
 * Everything is built on the platform's `Intl` APIs, so output is
 * locale-aware (and works in any modern browser or Node ≥ 14 with full ICU).
 */

/* -------------------------------------------------------------------------- */
/* Prices                                                                      */
/* -------------------------------------------------------------------------- */

export interface FormatPriceOptions {
  /** BCP 47 locale tag, e.g. "en-US", "de-DE", "ja-JP". Default: "en-US". */
  locale?: string;
  /** ISO 4217 currency code, e.g. "USD", "EUR", "JPY". Default: "USD". */
  currency?: string;
  /** Minimum digits after the decimal separator. Default: 2. */
  minimumFractionDigits?: number;
  /** Maximum digits after the decimal separator. Default: 2. */
  maximumFractionDigits?: number;
  /** Use compact notation, e.g. "$1.2K". Default: false. */
  compact?: boolean;
}

/**
 * Format a number as a currency string.
 *
 * @example formatPrice(1234.5)                     // "$1,234.50"
 * @example formatPrice(1234.5, { currency: "EUR" }) // "1.234,50 €"
 * @example formatPrice(1_250_000, { compact: true })// "$1.3M"
 */
export function formatPrice(amount: number, options: FormatPriceOptions = {}): string {
  const {
    locale = "en-US",
    currency = "USD",
    minimumFractionDigits = 2,
    maximumFractionDigits = 2,
    compact = false,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new RangeError(`Cannot format a non-finite price: ${amount}`);
  }

  const formatter = compact
    ? new Intl.NumberFormat(locale, {
        style: "currency",
        currency,
        notation: "compact",
        minimumFractionDigits: 0,
        maximumFractionDigits: 1,
      })
    : new Intl.NumberFormat(locale, {
        style: "currency",
        currency,
        minimumFractionDigits,
        maximumFractionDigits,
      });

  return formatter.format(amount);
}

/**
 * Format a number as a percentage.
 *
 * @example formatPercent(0.256)                     // "25.6%"
 * @example formatPercent(0.256, { maximumFractionDigits: 0 }) // "26%"
 */
export function formatPercent(
  ratio: number,
  options: Omit<FormatPriceOptions, "currency" | "compact"> = {},
): string {
  const { locale = "en-US", minimumFractionDigits = 0, maximumFractionDigits = 2 } = options;

  if (!Number.isFinite(ratio)) {
    throw new RangeError(`Cannot format a non-finite percentage: ${ratio}`);
  }

  return new Intl.NumberFormat(locale, {
    style: "percent",
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(ratio);
}

/* -------------------------------------------------------------------------- */
/* Dates                                                                       */
/* -------------------------------------------------------------------------- */

/** Anything that can be turned into a `Date`. */
export type DateInput = Date | string | number;

export interface FormatDateOptions {
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
  /** Date portion style. Default: "medium". */
  dateStyle?: "full" | "long" | "medium" | "short";
  /** Time portion style. Omit to render the date only. */
  timeStyle?: "full" | "long" | "medium" | "short";
  /** IANA time zone, e.g. "America/New_York". Default: the runtime's zone. */
  timeZone?: string;
}

export interface FormatRelativeDateOptions {
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
  /** Reference point for "in 3 days" / "2 days ago". Default: `new Date()`. */
  now?: Date;
}

/** Convert input into a valid `Date`, throwing on invalid values. */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}

/**
 * Format a date (and optionally a time).
 *
 * @example formatDate("2024-03-15")                          // "Mar 15, 2024"
 * @example formatDate(new Date(), { dateStyle: "full" })      // "Friday, March 15, 2024"
 * @example formatDate(1710000000000, { timeStyle: "short" })  // "Mar 9, 2024, 12:00 PM"
 */
export function formatDate(input: DateInput, options: FormatDateOptions = {}): string {
  const { locale = "en-US", dateStyle = "medium", timeStyle, timeZone } = options;

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    ...(timeStyle ? { timeStyle } : {}),
    ...(timeZone ? { timeZone } : {}),
  }).format(toDate(input));
}

/**
 * Format a date and time together.
 *
 * @example formatDateTime("2024-03-15T18:30:00Z") // "Mar 15, 2024, 6:30 PM"
 */
export function formatDateTime(
  input: DateInput,
  options: Omit<FormatDateOptions, "timeStyle"> = {},
): string {
  return formatDate(input, { ...options, timeStyle: options.timeStyle ?? "short" });
}

const RELATIVE_UNITS: Array<[Intl.RelativeTimeFormatUnit, number]> = [
  ["year", 365 * 24 * 60 * 60 * 1000],
  ["month", 30 * 24 * 60 * 60 * 1000],
  ["week", 7 * 24 * 60 * 60 * 1000],
  ["day", 24 * 60 * 60 * 1000],
  ["hour", 60 * 60 * 1000],
  ["minute", 60 * 1000],
  ["second", 1000],
];

/**
 * Format a date relative to another point in time.
 *
 * @example formatRelativeDate(Date.now() - 3_600_000) // "1 hour ago"
 * @example formatRelativeDate(Date.now() + 86_400_000) // "tomorrow"
 */
export function formatRelativeDate(
  input: DateInput,
  options: FormatRelativeDateOptions = {},
): string {
  const { locale = "en-US", now = new Date() } = options;
  const diff = toDate(input).getTime() - now.getTime();
  const absDiff = Math.abs(diff);

  const formatter = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, ms] of RELATIVE_UNITS) {
    if (absDiff >= ms || unit === "second") {
      return formatter.format(Math.round(diff / ms), unit);
    }
  }

  /* istanbul ignore next — unreachable, the loop always returns on "second" */
  return formatter.format(0, "second");
}
```

### Usage

```ts
import { formatPrice, formatPercent, formatDate, formatDateTime, formatRelativeDate } from "./formatters";

formatPrice(19.99);                                   // "19.99" → "$19.99"
formatPrice(19.99, { currency: "JPY", maximumFractionDigits: 0 }); // "¥20"
formatPrice(1_250_000, { compact: true });            // "$1.3M"
formatPercent(0.075);                                 // "7.5%"

formatDate("2024-03-15");                             // "Mar 15, 2024"
formatDate("2024-03-15", { dateStyle: "long" });      // "March 15, 2024"
formatDateTime("2024-03-15T18:30:00Z", { timeZone: "UTC" }); // "Mar 15, 2024, 6:30 PM"
formatRelativeDate(Date.now() - 7 * 86_400_000);      // "last week"
```

**Notes**
- All formatters throw a `RangeError` for invalid input (`NaN`, `Infinity`, unparsable date strings) so bad data fails loudly.
- Currency and date output is locale-sensitive; pass `locale` (and optionally `timeZone`) to control it.
- `formatPrice` defaults to 2 fraction digits, which is wrong for zero-decimal currencies like JPY — pass `maximumFractionDigits: 0` for those.

```ts
/**
 * Small, dependency-free helpers for formatting prices and dates.
 * All formatting is done via the built-in `Intl` APIs.
 */

/** Options for {@link formatPrice}. */
export interface FormatPriceOptions {
  /** BCP 47 locale tag, e.g. `"en-US"`. Defaults to the runtime locale. */
  locale?: string;
  /** ISO 4217 currency code, e.g. `"USD"`, `"EUR"`, `"JPY"`. Defaults to `"USD"`. */
  currency?: string;
  /** Minimum number of fraction digits to show. */
  minimumFractionDigits?: number;
  /** Maximum number of fraction digits to show. */
  maximumFractionDigits?: number;
  /** Use compact notation, e.g. `"$1.2K"`. Defaults to `false`. */
  compact?: boolean;
  /** Returned when the value is not a finite number. Defaults to `"—"`. */
  fallback?: string;
}

/**
 * Formats a numeric amount as a currency string.
 *
 * @example
 * formatPrice(1234.5);                                  // "$1,234.50"
 * formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }); // "1.234,50 €"
 * formatPrice(1_250_000, { compact: true });            // "$1.3M"
 */
export function formatPrice(value: number, options: FormatPriceOptions = {}): string {
  const {
    locale,
    currency = "USD",
    minimumFractionDigits,
    maximumFractionDigits,
    compact = false,
    fallback = "—",
  } = options;

  if (typeof value !== "number" || !Number.isFinite(value)) {
    return fallback;
  }

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
    ...(minimumFractionDigits !== undefined ? { minimumFractionDigits } : {}),
    ...(maximumFractionDigits !== undefined ? { maximumFractionDigits } : {}),
  }).format(value);
}

/** Options for {@link formatDate}. */
export interface FormatDateOptions extends Intl.DateTimeFormatOptions {
  /** BCP 47 locale tag, e.g. `"en-US"`. Defaults to the runtime locale. */
  locale?: string;
  /** IANA time zone, e.g. `"America/New_York"`. Defaults to the runtime zone. */
  timeZone?: string;
  /** Returned when the date cannot be parsed. Defaults to `"—"`. */
  fallback?: string;
}

/**
 * Formats a date using `Intl.DateTimeFormat`.
 * Accepts a `Date`, a timestamp, or an ISO date string.
 *
 * @example
 * formatDate(new Date("2024-03-15T12:00:00Z"), { dateStyle: "medium", timeZone: "UTC" });
 * formatDate("2024-03-15", { year: "numeric", month: "long", day: "numeric" });
 */
export function formatDate(
  date: Date | number | string,
  options: FormatDateOptions = {},
): string {
  const { locale, timeZone, fallback = "—", ...dateTimeOptions } = options;

  const parsed = date instanceof Date ? date : new Date(date);
  if (Number.isNaN(parsed.getTime())) {
    return fallback;
  }

  return new Intl.DateTimeFormat(locale, { timeZone, ...dateTimeOptions }).format(parsed);
}

/** Options for {@link formatRelativeTime}. */
export interface FormatRelativeTimeOptions {
  /** BCP 47 locale tag, e.g. `"en-US"`. Defaults to the runtime locale. */
  locale?: string;
  /** Returned when the date cannot be parsed. Defaults to `"—"`. */
  fallback?: string;
}

/**
 * Formats a date relative to now, e.g. `"3 days ago"` or `"in 2 hours"`.
 *
 * @example
 * formatRelativeTime(Date.now() - 1000 * 60 * 60 * 24 * 3)); // "3 days ago"
 */
export function formatRelativeTime(
  date: Date | number | string,
  options: FormatRelativeTimeOptions = {},
): string {
  const { locale, fallback = "—" } = options;

  const parsed = date instanceof Date ? date : new Date(date);
  if (Number.isNaN(parsed.getTime())) {
    return fallback;
  }

  const deltaSeconds = Math.round((parsed.getTime() - Date.now()) / 1000);
  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  const formatter = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  for (const [unit, seconds] of units) {
    if (Math.abs(deltaSeconds) >= seconds || unit === "second") {
      return formatter.format(Math.round(deltaSeconds / seconds), unit);
    }
  }

  return fallback;
}
