- Invalid inputs (non-finite prices, unparsable dates) return the `fallback` string instead of throwing.
- Currency fraction digits follow each currency's defaults unless you override them explicitly.
- `formatDate` accepts any `Intl.DateTimeFormatOptions` (`dateStyle`, `timeStyle`, `month`, `day`, `hour`, etc.), so you can mix styles with individual fields.

```ts
// format.ts

/** Options for {@link formatPrice}. */
export interface FormatPriceOptions {
  /** ISO 4217 currency code. Defaults to `"USD"`. */
  currency?: string;
  /** BCP 47 locale tag. Defaults to `"en-US"`. */
  locale?: string;
  /** Number of fraction digits. Defaults to `2`. */
  fractionDigits?: number;
  /** Render as a compact string (e.g. `1.2K`). Defaults to `false`. */
  compact?: boolean;
}

/** Options for {@link formatDate}. */
export interface FormatDateOptions {
  /** BCP 47 locale tag. Defaults to `"en-US"`. */
  locale?: string;
  /** `Intl.DateTimeFormat` style. Defaults to `"medium"`. */
  dateStyle?: "full" | "long" | "medium" | "short";
  /** `Intl.DateTimeFormat` time style. Omit for date-only output. */
  timeStyle?: "full" | "long" | "medium" | "short";
  /** IANA time zone. Defaults to the runtime's local zone. */
  timeZone?: string;
}

/**
 * Formats a number as a currency string.
 *
 * @example
 * formatPrice(1234.5);                    // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR" }); // "€1,234.50"
 * formatPrice(1234.5, { compact: true });  // "$1.2K"
 */
export function formatPrice(
  value: number,
  options: FormatPriceOptions = {},
): string {
  const {
    currency = "USD",
    locale = "en-US",
    fractionDigits = 2,
    compact = false,
  } = options;

  if (!Number.isFinite(value)) {
    throw new TypeError(`formatPrice: expected a finite number, got ${value}`);
  }

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
    minimumFractionDigits: compact ? 0 : fractionDigits,
    maximumFractionDigits: fractionDigits,
  }).format(value);
}

/**
 * Formats a date (or timestamp) as a human-readable string.
 *
 * @example
 * formatDate(new Date());                                  // "Jan 5, 2025"
 * formatDate(Date.now(), { dateStyle: "full" });           // "Sunday, January 5, 2025"
 * formatDate(new Date(), { timeStyle: "short" });           // "3:04 PM"
 * formatDate(new Date(), { timeZone: "UTC" });              // "Jan 5, 2025"
 */
export function formatDate(
  value: Date | number | string,
  options: FormatDateOptions = {},
): string {
  const {
    locale = "en-US",
    dateStyle = "medium",
    timeStyle,
    timeZone,
  } = options;

  const date = value instanceof Date ? value : new Date(value);

  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`formatDate: invalid date value "${String(value)}"`);
  }

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    ...(timeStyle ? { timeStyle } : {}),
    ...(timeZone ? { timeZone } : {}),
  }).format(date);
}

/**
 * Formats a date as a relative phrase ("3 days ago", "in 2 hours").
 *
 * @example
 * formatRelativeDate(Date.now() - 1000 * 60 * 60 * 24 * 3); // "3 days ago"
 */
export function formatRelativeDate(
  value: Date | number | string,
  options: { locale?: string } = {},
): string {
  const { locale = "en-US" } = options;

  const date = value instanceof Date ? value : new Date(value);

  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`formatRelativeDate: invalid date value "${String(value)}"`);
  }

  const deltaSeconds = (date.getTime() - Date.now()) / 1000;
  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  const formatter = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, seconds] of units) {
    if (Math.abs(deltaSeconds) >= seconds || unit === "second") {
      return formatter.format(Math.round(deltaSeconds / seconds), unit);
    }
  }

  return formatter.format(0, "second");
}
