/**
 * Small, dependency-free helpers for formatting prices and dates.
 * All formatting is delegated to the built-in `Intl` APIs, so output
 * follows the user's locale/time zone when one isn't specified.
 */

/* -------------------------------------------------------------------------- */
/* Prices                                                                     */
/* -------------------------------------------------------------------------- */

export interface PriceFormatOptions {
  /** BCP 47 locale tag, e.g. "en-US", "de-DE", "ja-JP". Default: "en-US". */
  locale?: string;
  /** ISO 4217 currency code, e.g. "USD", "EUR", "JPY". Default: "USD". */
  currency?: string;
  /** "standard" → $1,234.56 · "compact" → $1.2K */
  notation?: "standard" | "compact";
  /** Override the currency symbol position/name, e.g. "US$" or " dollars". */
  currencyDisplay?: "symbol" | "narrowSymbol" | "code" | "name";
  /** Number of fraction digits. Defaults to the currency's convention. */
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
}

/**
 * Format a numeric amount as a currency string.
 *
 * @example
 * formatPrice(1234.5);                          // "$1,234.50"
 * formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }); // "1.234,50 €"
 * formatPrice(1_250_000, { notation: "compact" });           // "$1.3M"
 */
export function formatPrice(
  amount: number,
  options: PriceFormatOptions = {},
): string {
  const {
    locale = "en-US",
    currency = "USD",
    notation = "standard",
    currencyDisplay = "symbol",
    minimumFractionDigits,
    maximumFractionDigits,
  } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`Cannot format non-finite price: ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation,
    currencyDisplay,
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

/**
 * Format a price without a currency symbol (e.g. for input fields).
 *
 * @example
 * formatAmount(1234.5);                            // "1,234.50"
 * formatAmount(1234.5, { locale: "fr-FR" });       // "1 234,50"
 */
export function formatAmount(
  amount: number,
  options: {
    locale?: string;
    minimumFractionDigits?: number;
    maximumFractionDigits?: number;
  } = {},
): string {
  const { locale = "en-US", minimumFractionDigits, maximumFractionDigits } = options;

  if (!Number.isFinite(amount)) {
    throw new TypeError(`Cannot format non-finite amount: ${amount}`);
  }

  return new Intl.NumberFormat(locale, {
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

/* -------------------------------------------------------------------------- */
/* Dates                                                                       */
/* -------------------------------------------------------------------------- */

/** Anything that can be turned into a valid `Date`. */
export type DateInput = Date | string | number;

export interface DateFormatOptions {
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
  /** How verbose the date part should be. Default: "medium". */
  dateStyle?: "full" | "long" | "medium" | "short";
  /** Include a time part (omit for date-only output). */
  timeStyle?: "full" | "long" | "medium" | "short";
  /** IANA time zone, e.g. "America/New_York". Default: the runtime's zone. */
  timeZone?: string;
}

export interface RelativeTimeFormatOptions {
  locale?: string;
  /** Style of the resulting phrase. Default: "long". */
  style?: "long" | "short" | "narrow";
  /** "always" → "in 2 days" · "auto" → "tomorrow". Default: "auto". */
  numeric?: "always" | "auto";
  /** Reference point for the comparison. Default: the current time. */
  now?: Date;
}

/** Convert the supported input types into a valid `Date`, or throw. */
function toDate(input: DateInput): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid date: ${String(input)}`);
  }
  return date;
}

/**
 * Format a date (and optionally a time).
 *
 * @example
 * formatDate(new Date());                              // "Mar 5, 2025"
 * formatDate("2025-03-05T14:30:00Z", { dateStyle: "full" }); // "Wednesday, March 5, 2025"
 * formatDate("2025-03-05T14:30:00Z", { timeStyle: "short" }); // "2:30 PM"
 */
export function formatDate(
  input: DateInput,
  options: DateFormatOptions = {},
): string {
  const {
    locale = "en-US",
    dateStyle = "medium",
    timeStyle,
    timeZone,
  } = options;

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    timeStyle,
    timeZone,
  }).format(toDate(input));
}

/**
 * Format the time portion of a date.
 *
 * @example
 * formatTime("2025-03-05T14:30:00Z", { timeZone: "UTC" }); // "2:30 PM"
 */
export function formatTime(
  input: DateInput,
  options: Omit<DateFormatOptions, "dateStyle"> = {},
): string {
  const { locale = "en-US", timeStyle = "short", timeZone } = options;

  return new Intl.DateTimeFormat(locale, { timeStyle, timeZone }).format(
    toDate(input),
  );
}

/**
 * Format a date as an ISO 8601 string (UTC), useful for APIs and filenames.
 *
 * @example
 * formatIsoDate("2025-03-05T14:30:00Z"); // "2025-03-05T14:30:00.000Z"
 */
export function formatIsoDate(input: DateInput): string {
  return toDate(input).toISOString();
}

/**
 * Format a date relative to another point in time.
 *
 * @example
 * formatRelativeTime(Date.now() - 3_600_000);                  // "1 hour ago"
 * formatRelativeTime(Date.now() + 86_400_000);                  // "tomorrow"
 * formatRelativeTime("2025-03-05", { now: new Date("2025-03-01") }); // "in 4 days"
 */
export function formatRelativeTime(
  input: DateInput,
  options: RelativeTimeFormatOptions = {},
): string {
  const {
    locale = "en-US",
    style = "long",
    numeric = "auto",
    now = new Date(),
  } = options;

  const diffMs = toDate(input).getTime() - now.getTime();
  const rtf = new Intl.RelativeTimeFormat(locale, { style, numeric });

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 365 * 24 * 60 * 60 * 1000],
    ["month", 30 * 24 * 60 * 60 * 1000],
    ["week", 7 * 24 * 60 * 60 * 1000],
    ["day", 24 * 60 * 60 * 1000],
    ["hour", 60 * 60 * 1000],
    ["minute", 60 * 1000],
    ["second", 1000],
  ];

  for (const [unit, ms] of units) {
    if (Math.abs(diffMs) >= ms || unit === "second") {
      return rtf.format(Math.round(diffMs / ms), unit);
    }
  }

  return rtf.format(0, "second");
}
