```ts
/**
 * format.ts — helpers for formatting money and dates.
 *
 * Zero dependencies: everything is built on the platform `Intl` APIs.
 * Requires TypeScript `lib` ES2020+ (for `Intl.DateTimeFormat` date/time
 * styles, `notation: "compact"` and `Intl.RelativeTimeFormat`).
 */

/* -------------------------------------------------------------------------- */
/* Types                                                                       */
/* -------------------------------------------------------------------------- */

export type DateInput = Date | number | string;

export interface PriceOptions {
  /** ISO 4217 code. @default "USD" */
  currency?: string;
  /** BCP 47 tag. @default "en-US" */
  locale?: string;
  /** Defaults to the currency's own convention (2 for USD, 0 for JPY, …). */
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  /** @default "symbol" */
  currencyDisplay?: "symbol" | "narrowSymbol" | "code" | "name";
  /** @default "auto" */
  signDisplay?: "auto" | "always" | "exceptZero" | "never";
  /** Drop trailing zeros: 12.5 -> "$12.50" becomes "$12.5", 12 -> "$12". */
  trimFraction?: boolean;
}

export interface PercentOptions {
  locale?: string;
  /** @default 0 */
  fractionDigits?: number;
  /** "percent": 0.25 -> "25%". "ratio": 0.25 -> "0.25". */
  style?: "percent" | "ratio";
  signDisplay?: "auto" | "always" | "exceptZero" | "never";
}

export interface DateOptions {
  locale?: string;
  /** IANA zone, e.g. "Europe/Berlin". Defaults to the runtime's zone. */
  timeZone?: string;
  /** @default "medium" */
  dateStyle?: "full" | "long" | "medium" | "short";
  timeStyle?: "full" | "long" | "medium" | "short";
  /** Custom pattern ("MMM d, yyyy", "HH:mm 'UTC'"). Overrides the styles. */
  pattern?: string;
}

export interface RelativeTimeOptions {
  locale?: string;
  /** Reference point. @default new Date() */
  now?: Date;
  /** "auto" -> "yesterday"; "always" -> "1 day ago". @default "auto" */
  numeric?: "auto" | "always";
}

export interface DurationOptions {
  /** "short" -> "1h 30m", "long" -> "1 hour 30 minutes", "clock" -> "01:30:00" */
  style?: "short" | "long" | "clock";
  locale?: string;
  /** How many units to show. @default 2 */
  maxUnits?: number;
}

/* -------------------------------------------------------------------------- */
/* Internals                                                                   */
/* -------------------------------------------------------------------------- */

const pad = (value: number, length: number): string =>
  String(Math.abs(value)).padStart(length, "0");

function assertFinite(value: number, fn: string): void {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new TypeError(`${fn}: expected a finite number, received ${String(value)}`);
  }
}

/** Removes a trailing all-zero fraction without touching grouping separators. */
function trimFractionDigits(formatter: Intl.NumberFormat, value: number): string {
  const parts = formatter.formatToParts(value);
  const fractionIndex = parts.findIndex((part) => part.type === "fraction");
  if (fractionIndex === -1) return parts.map((part) => part.value).join("");

  const trimmed = parts[fractionIndex].value.replace(/0+$/, "");
  if (trimmed.length > 0) {
    return parts.map((part, i) => (i === fractionIndex ? trimmed : part.value)).join("");
  }

  // The whole fraction was zeros — drop it together with the decimal separator.
  return parts
    .filter((part, i) => i !== fractionIndex && !(part.type === "decimal" && i < fractionIndex))
    .map((part) => part.value)
    .join("");
}

interface ZonedParts {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second: number;
  millisecond: number;
  hour12: number;
  monthShort: string;
  monthLong: string;
  weekdayShort: string;
  weekdayLong: string;
}

/** Calendar fields of `date` as seen in `timeZone`. */
function getZonedParts(date: Date, locale: string, timeZone?: string): ZonedParts {
  const numeric = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).formatToParts(date);

  const values: Record<string, number> = {};
  for (const part of numeric) {
    if (part.type !== "literal") values[part.type] = Number(part.value);
  }

  const longNames = new Intl.DateTimeFormat(locale, {
    timeZone,
    month: "long",
    weekday: "long",
  }).formatToParts(date);
  const shortNames = new Intl.DateTimeFormat(locale, {
    timeZone,
    month: "short",
    weekday: "short",
  }).formatToParts(date);

  const pick = (parts: Intl.DateTimeFormatPart[], type: string): string =>
    parts.find((part) => part.type === type)?.value ?? "";

  const hour = values.hour ?? 0;
  return {
    year: values.year ?? 0,
    month: values.month ?? 1,
    day: values.day ?? 1,
    hour,
    minute: values.minute ?? 0,
    second: values.second ?? 0,
    millisecond: date.getMilliseconds(),
    hour12: hour % 12 === 0 ? 12 : hour % 12,
    monthShort: pick(shortNames, "month"),
    monthLong: pick(longNames, "month"),
    weekdayShort: pick(shortNames, "weekday"),
    weekdayLong: pick(longNames, "weekday"),
  };
}

/** Offset of `timeZone` from UTC in minutes at the given instant. */
function timeZoneOffsetMinutes(date: Date, timeZone?: string): number {
  if (!timeZone) return -date.getTimezoneOffset();

  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(date);

  const v: Record<string, number> = {};
  for (const part of parts) {
    if (part.type !== "literal") v[part.type] = Number(part.value);
  }

  const asUTC = Date.UTC(v.year, v.month - 1, v.day, v.hour, v.minute, v.second);
  return Math.round((asUTC - (date.getTime() - date.getMilliseconds())) / 60_000);
}

function formatOffset(minutes: number, withColon: boolean): string {
  const sign = minutes < 0 ? "-" : "+";
  const abs = Math.abs(minutes);
  const hh = pad(Math.floor(abs / 60), 2);
  const mm = pad(abs % 60, 2);
  return withColon ? `${sign}${hh}:${mm}` : `${sign}${hh}${mm}`;
}

/* -------------------------------------------------------------------------- */
/* Dates — parsing                                                             */
/* -------------------------------------------------------------------------- */

/** Coerces to a `Date`, throwing on invalid input. */
export function toDate(value: DateInput): Date {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`toDate: invalid date ${JSON.stringify(value)}`);
  }
  return date;
}

export function isValidDate(value: DateInput): boolean {
  const date = value instanceof Date ? value : new Date(value);
  return !Number.isNaN(date.getTime());
}

/**
 * Parses "YYYY-MM-DD" as *local* midnight.
 *
 * `new Date("2024-03-05")` is parsed as UTC by the language spec, which
 * shifts the calendar day for users west of Greenwich — this avoids that.
 */
export function parseLocalDate(value: string): Date {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) {
    throw new TypeError(`parseLocalDate: expected "YYYY-MM-DD", received ${JSON.stringify(value)}`);
  }
  const [, y, m, d] = match;
  const date = new Date(Number(y), Number(m) - 1, Number(d));
  if (date.getDate() !== Number(d)) {
    throw new RangeError(`parseLocalDate: ${value} is not a real calendar date`);
  }
  return date;
}

/* -------------------------------------------------------------------------- */
/* Dates — formatting                                                          */
/* -------------------------------------------------------------------------- */

const TOKEN_RE =
  /''|'([^']*)'|yyyy|yy|MMMM|MMM|MM|M|dd|d|EEEE|EEE|EE|HH|H|hh|h|mm|m|ss|s|SSS|ZZ|Z|a/g;

function formatWithPattern(
  date: Date,
  pattern: string,
  locale: string,
  timeZone?: string,
): string {
  const p = getZonedParts(date, locale, timeZone);
  const offset = timeZoneOffsetMinutes(date, timeZone);

  return pattern.replace(TOKEN_RE, (match, literal?: string) => {
    if (match === "''") return "'";
    if (match.startsWith("'")) return literal ?? "";

    switch (match) {
      case "yyyy": return pad(p.year, 4);
      case "yy": return pad(p.year % 100, 2);
      case "MMMM": return p.monthLong;
      case "MMM": return p.monthShort;
      case "MM": return pad(p.month, 2);
      case "M": return String(p.month);
      case "dd": return pad(p.day, 2);
      case "d": return String(p.day);
      case "EEEE": return p.weekdayLong;
      case "EEE":
      case "EE": return p.weekdayShort;
      case "HH": return pad(p.hour, 2);
      case "H": return String(p.hour);
      case "hh": return pad(p.hour12, 2);
      case "h": return String(p.hour12);
      case "mm": return pad(p.minute, 2);
      case "m": return String(p.minute);
      case "ss": return pad(p.second, 2);
      case "s": return String(p.second);
      case "SSS": return pad(p.millisecond, 3);
      case "a": return p.hour < 12 ? "AM" : "PM";
      case "Z": return formatOffset(offset, true);
      case "ZZ": return formatOffset(offset, false);
      default: return match;
    }
  });
}

/**
 * Formats a date.
 *
 * @example
 * formatDate(new Date("2024-03-05T12:00:00Z"));                  // "Mar 5, 2024"
 * formatDate(d, { locale: "de-DE" });                            // "05.03.2024"
 * formatDate(d, { pattern: "EEEE, MMM d yyyy 'at' HH:mm" });     // "Tuesday, Mar 5 2024 at 12:00"
 */
export function formatDate(date: DateInput, options: DateOptions = {}): string {
  const d = toDate(date);
  const { locale = "en-US", timeZone, pattern, dateStyle = "medium", timeStyle } = options;

  if (pattern) return formatWithPattern(d, pattern, locale, timeZone);

  return new Intl.DateTimeFormat(locale, {
    dateStyle,
    ...(timeStyle ? { timeStyle } : {}),
    ...(timeZone ? { timeZone } : {}),
  }).format(d);
}

/** Date + time, e.g. "Mar 5, 2024, 12:00 PM". */
export function formatDateTime(date: DateInput, options: DateOptions = {}): string {
  return formatDate(date, { dateStyle: "medium", timeStyle: "short", ...options });
}

/** Time only, e.g. "12:00 PM". */
export function formatTime(
  date: DateInput,
  options: {
    locale?: string;
    timeZone?: string;
    hour12?: boolean;
    timeStyle?: "full" | "long" | "medium" | "short";
  } = {},
): string {
  const d = toDate(date);
  const { locale = "en-US", timeZone, hour12, timeStyle = "short" } = options;

  return new Intl.DateTimeFormat(locale, {
    timeStyle,
    ...(hour12 === undefined ? {} : { hour12 }),
    ...(timeZone ? { timeZone } : {}),
  }).format(d);
}

/** "2024-03-05" in the given zone (defaults to the runtime's zone). */
export function formatISODate(date: DateInput, options: { timeZone?: string } = {}): string {
  const p = getZonedParts(toDate(date), "en-US", options.timeZone);
  return `${pad(p.year, 4)}-${pad(p.month, 2)}-${pad(p.day, 2)}`;
}

/** Full ISO-8601 instant, e.g. "2024-03-05T12:00:00.000Z". */
export function formatISOTimestamp(date: DateInput): string {
  return toDate(date).toISOString();
}

/** True when both instants fall on the same calendar day in `timeZone`. */
export function isSameDay(a: DateInput, b: DateInput, timeZone?: string): boolean {
  const pa = getZonedParts(toDate(a), "en-US", timeZone);
  const pb = getZonedParts(toDate(b), "en-US", timeZone);
  return pa.year === pb.year && pa.month === pb.month && pa.day === pb.day;
}

/** "Mar 5, 2024 – Mar 8, 2024" (collapses to a single date when both match). */
export function formatDateRange(start: DateInput, end: DateInput, options: DateOptions = {}): string {
  const from = toDate(start);
  const to = toDate(end);
  const { locale = "en-US", timeZone, pattern } = options;

  if (pattern) {
    const a = formatWithPattern(from, pattern, locale, timeZone);
    const b = formatWithPattern(to, pattern, locale, timeZone);
    return a === b ? a : `${a} – ${b}`;
  }

  if (isSameDay(from, to, timeZone)) return formatDate(from, options);
  return `${formatDate(from, options)} – ${formatDate(to, options)}`;
}

/* -------------------------------------------------------------------------- */
/* Dates — relative time & durations                                           */
/* -------------------------------------------------------------------------- */

/** Whole calendar months between two instants (signed). */
function calendarMonths(from: Date, to: Date): number {
  let months = (to.getFullYear() - from.getFullYear()) * 12 + (to.getMonth() - from.getMonth());
  const probe = new Date(from.getFullYear(), from.getMonth() + months, from.getDate());
  if (months > 0 && probe.getTime() > to.getTime()) months -= 1;
  else if (months < 0 && probe.getTime() < to.getTime()) months += 1;
  return months;
}

/** Whole calendar years between two instants (signed). */
function calendarYears(from: Date, to: Date): number {
  let years = to.getFullYear() - from.getFullYear();
  const probe = new Date(from.getFullYear() + years, from.getMonth(), from.getDate());
  if (years > 0 && probe.getTime() > to.getTime()) years -= 1;
  else if (years < 0 && probe.getTime() < to.getTime()) years += 1;
  return years;
}

/**
 * Human-readable distance from `now`.
 *
 * @example
 * formatRelativeTime(new Date("2024-03-04T12:00:00Z"), { now: new Date("2024-03-05T12:00:00Z") });
 * // "yesterday"
 */
export function formatRelativeTime(date: DateInput, options: RelativeTimeOptions = {}): string {
  const target = toDate(date);
  const now = options.now ? toDate(options.now) : new Date();
  const { locale = "en-US", numeric = "auto" } = options;

  const diff = target.getTime() - now.getTime();
  const abs = Math.abs(diff);

  let value: number;
  let unit: "second" | "minute" | "hour" | "day" | "month" | "year";

  if (abs < 60_000) {
    value = Math.round(diff / 1_000);
    unit = "second";
  } else if (abs < 3_600_000) {
    value = Math.round(diff / 60_000);
    unit = "minute";
  } else if (abs < 86_400_000) {
    value = Math.round(diff / 3_600_000);
    unit = "hour";
  } else if (abs < 31 * 86_400_000) {
    value = Math.round(diff / 86_400_000);
    unit = "day";
  } else if (abs < 365 * 86_400_000) {
    value = calendarMonths(now, target);
    unit = "month";
  } else {
    value = calendarYears(now, target);
    unit = "year";
  }

  if (Object.is(value, -0)) value = 0;

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric });
  return rtf.format(value, unit as Parameters<Intl.RelativeTimeFormat["format"]>[1]);
}

/**
 * Formats a duration.
 *
 * @example
 * formatDuration(5_400_000);                    // "1h 30m"
 * formatDuration(5_400_000, { style: "long" }); // "1 hour 30 minutes"
 * formatDuration(5_400_000, { style: "clock" });// "01:30:00"
 */
export function formatDuration(ms: number, options: DurationOptions = {}): string {
  assertFinite(ms, "formatDuration");
  const { style = "short", locale = "en-US", maxUnits = 2 } = options;

  const totalSeconds = Math.floor(Math.abs(ms) / 1_000);
  const sign = ms < 0 ? "-" : "";

  const hours = Math.floor(totalSeconds / 3_600);
  const minutes = Math.floor((totalSeconds % 3_600) / 60);
  const seconds = totalSeconds % 60;

  if (style === "clock") {
    return `${sign}${pad(hours, 2)}:${pad(minutes, 2)}:${pad(seconds, 2)}`;
  }

  const plural = new Intl.PluralRules(locale);
  const units = [
    { value: hours, singular: "hour", plural: "hours" },
    { value: minutes, singular: "minute", plural: "minutes" },
    { value: seconds, singular: "second", plural: "seconds" },
  ];

  const nonZero = units.filter((unit) => unit.value > 0);
  const shown = (nonZero.length > 0 ? nonZero : [units[units.length - 1]]).slice(
    0,
    Math.max(1, maxUnits),
  );

  const parts = shown.map((unit) => {
    if (style === "long") {
      const label = plural.select(unit.value) === "one" ? unit.singular : unit.plural;
      return `${unit.value} ${label}`;
    }
    return `${unit.value}${unit.singular[0]}`;
  });

  return `${sign}${parts.join(" ")}`;
}

/* -------------------------------------------------------------------------- */
/* Prices                                                                      */
/* -------------------------------------------------------------------------- */

/**
 * Formats an amount of money.
 *
 * @example
 * formatPrice(1234.5);                                   // "$1,234.50"
 * formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }); // "1.234,50 €"
 * formatPrice(12, { trimFraction: true });               // "$12"
 * formatPrice(12, { signDisplay: "always" });            // "+$12.00"
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  assertFinite(amount, "formatPrice");
  const {
    currency = "USD",
    locale = "en-US",
    minimumFractionDigits,
    maximumFractionDigits,
    currencyDisplay = "symbol",
    signDisplay = "auto",
    trimFraction = false,
  } = options;

  const formatter = new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    currencyDisplay,
    signDisplay,
    ...(minimumFractionDigits === undefined ? {} : { minimumFractionDigits }),
    ...(maximumFractionDigits === undefined ? {} : { maximumFractionDigits }),
  });

  return trimFraction ? trimFractionDigits(formatter, amount) : formatter.format(amount);
}

/**
 * Formats a minor-unit amount (cents) as currency.
 *
 * @example
 * formatCents(1999); // "$19.99"
 */
export function formatCents(cents: number, options: PriceOptions = {}): string {
  assertFinite(cents, "formatCents");
  return formatPrice(cents / 100, options);
}

/**
 * Formats a percentage.
 *
 * @example
 * formatPercent(0.256);                       // "26%"
 * formatPercent(0.256, { fractionDigits: 1 }); // "25.6%"
 */
export function formatPercent(value: number, options: PercentOptions = {}): string {
  assertFinite(value, "formatPercent");
  const {
    locale = "en-US",
    fractionDigits = 0,
    style = "percent",
    signDisplay = "auto",
  } = options;

  return new Intl.NumberFormat(locale, {
    style: style === "percent" ? "percent" : "decimal",
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
    signDisplay,
  }).format(value);
}

/**
 * Compact notation, e.g. "$1.2K".
 */
export function formatCompactPrice(amount: number, options: PriceOptions = {}): string {
  assertFinite(amount, "formatCompactPrice");
  const {
    currency = "USD",
    locale = "en-US",
    currencyDisplay = "symbol",
    signDisplay = "auto",
  } = options;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    currencyDisplay,
    signDisplay,
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(amount);
}

/**
 * A price range; collapses to a single price when min === max.
 *
 * @example
 * formatPriceRange(10, 25); // "$10.00 – $25.00"
 */
export function formatPriceRange(min: number, max: number, options: PriceOptions = {}): string {
  assertFinite(min, "formatPriceRange");
  assertFinite(max, "formatPriceRange");
  if (min === max) return formatPrice(min, options);
  const [low, high] = min <= max ? [min, max] : [max, min];
  return `${formatPrice(low, options)} – ${formatPrice(high, options)}`;
}

/**
 * Plain number formatting with grouping.
 *
 * @example
 * formatNumber(1234567.89); // "1,234,567.89"
 */
export function formatNumber(
  value: number,
  options: Intl.NumberFormatOptions & { locale?: string } = {},
): string {
  assertFinite(value, "formatNumber");
  const { locale = "en-US", ...rest } = options;
  return new Intl.NumberFormat(locale, rest).format(value);
}
