/**
 * Small, dependency-free helpers for formatting prices and dates.
 * Uses the built-in `Intl` API, so output respects the given locale.
 */

const DEFAULT_FALLBACK = "—";

/* -------------------------------------------------------------------------- */
/* Prices                                                                     */
/* -------------------------------------------------------------------------- */

export interface FormatPriceOptions {
  /** BCP 47 locale tag, e.g. "en-US". Defaults to the runtime locale. */
  locale?: string;
  /** ISO 4217 currency code, e.g. "USD", "EUR", "JPY". */
  currency?: string;
  /** Minimum fraction digits to show (default: currency's own default). */
  minFractionDigits?: number;
  /** Maximum fraction digits to show (default: currency's own default). */
  maxFractionDigits?: number;
  /** Show the currency code instead of the symbol (e.g. "12.50 USD"). */
  useCurrencyCode?: boolean;
  /** Returned when the amount is missing or not a finite number. */
  fallback?: string;
}

/**
 * Formats a monetary amount.
 *
 * @example formatPrice(1234.5)                  // "$1,234.50" (en-US, USD)
 * @example formatPrice(1234.5, { locale: "de-DE", currency: "EUR" })
 */
export function formatPrice(
  amount: number | null | undefined,
  options: FormatPriceOptions = {},
): string {
  const {
    locale,
    currency = "USD",
    minFractionDigits,
    maxFractionDigits,
    useCurrencyCode = false,
    fallback = DEFAULT_FALLBACK,
  } = options;

  if (amount === null || amount === undefined || !Number.isFinite(amount)) {
    return fallback;
  }

  const formatter = new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    currencyDisplay: useCurrencyCode ? "code" : "symbol",
    ...(minFractionDigits !== undefined ? { minimumFractionDigits } : {}),
    ...(maxFractionDigits !== undefined ? { maximumFractionDigits } : {}),
  });

  return formatter.format(amount);
}

export interface FormatPercentOptions {
  locale?: string;
  /** Number of fraction digits (default: 0). */
  fractionDigits?: number;
  fallback?: string;
}

/**
 * Formats a ratio (0.25) or an already-scaled percentage (25) as a percentage.
 *
 * @example formatPercent(0.256) // "26%"
 * @example formatPercent(25.6, { fractionDigits: 1 }) // "25.6%"
 */
export function formatPercent(
  value: number | null | undefined,
  options: FormatPercentOptions = {},
): string {
  const { locale, fractionDigits = 0, fallback = DEFAULT_FALLBACK } = options;

  if (value === null || value === undefined || !Number.isFinite(value)) {
    return fallback;
  }

  return new Intl.NumberFormat(locale, {
    style: "percent",
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  }).format(value);
}

/* -------------------------------------------------------------------------- */
/* Dates                                                                       */
/* -------------------------------------------------------------------------- */

export type DateFormatStyle = "short" | "medium" | "long" | "full";

export interface FormatDateOptions {
  locale?: string;
  /** Preset for the date parts shown. Default: "medium". */
  style?: DateFormatStyle;
  /** IANA time zone, e.g. "America/New_York". */
  timeZone?: string;
  fallback?: string;
}

const DATE_STYLES: Record<DateFormatStyle, Intl.DateTimeFormatOptions> = {
  short: { year: "numeric", month: "numeric", day: "numeric" },
  medium: { year: "numeric", month: "short", day: "numeric" },
  long: { year: "numeric", month: "long", day: "numeric" },
  full: { weekday: "long", year: "numeric", month: "long", day: "numeric" },
};

/** Coerces a Date | ISO string | epoch-ms number into a valid Date, or null. */
function toDate(value: Date | string | number): Date | null {
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

/**
 * Formats a date.
 *
 * @example formatDate("2024-03-09T12:00:00Z", { style: "long", timeZone: "UTC" })
 */
export function formatDate(
  value: Date | string | number | null | undefined,
  options: FormatDateOptions = {},
): string {
  const { locale, style = "medium", timeZone, fallback = DEFAULT_FALLBACK } = options;
  const date = value === null || value === undefined ? null : toDate(value);
  if (!date) return fallback;

  return new Intl.DateTimeFormat(locale, {
    ...DATE_STYLES[style],
    ...(timeZone ? { timeZone } : {}),
  }).format(date);
}

/**
 * Formats a date and time.
 *
 * @example formatDateTime(new Date(), { timeZone: "Europe/Berlin" })
 */
export function formatDateTime(
  value: Date | string | number | null | undefined,
  options: FormatDateOptions = {},
): string {
  const { locale, timeZone, fallback = DEFAULT_FALLBACK } = options;
  const date = value === null || value === undefined ? null : toDate(value);
  if (!date) return fallback;

  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeStyle: "short",
    ...(timeZone ? { timeZone } : {}),
  }).format(date);
}

export interface FormatRelativeTimeOptions {
  locale?: string;
  /** "auto" picks a sensible unit; otherwise force one, e.g. "day". */
  unit?: Intl.RelativeTimeFormatUnit | "auto";
  fallback?: string;
}

const DIVISIONS: { amount: number; unit: Intl.RelativeTimeFormatUnit }[] = [
  { amount: 60, unit: "second" },
  { amount: 60, unit: "minute" },
  { amount: 24, unit: "hour" },
  { amount: 7, unit: "day" },
  { amount: 4.34524, unit: "week" },
  { amount: 12, unit: "month" },
  { amount: Number.POSITIVE_INFINITY, unit: "year" },
];

/**
 * Formats a date relative to now, e.g. "3 days ago" / "in 2 hours".
 */
export function formatRelativeTime(
  value: Date | string | number | null | undefined,
  options: FormatRelativeTimeOptions = {},
): string {
  const { locale, unit = "auto", fallback = DEFAULT_FALLBACK } = options;
  const date = value === null || value === undefined ? null : toDate(value);
  if (!date) return fallback;

  let deltaSeconds = (date.getTime() - Date.now()) / 1000;

  if (unit === "auto") {
    for (const division of DIVISIONS) {
      if (Math.abs(deltaSeconds) < division.amount) break;
      deltaSeconds /= division.amount;
    }
  } else {
    const secondsPerUnit: Record<string, number> = {
      second: 1,
      minute: 60,
      hour: 3600,
      day: 86400,
      week: 604800,
      month: 2629800,
      year: 31557600,
    };
    deltaSeconds /= secondsPerUnit[unit] ?? 1;
  }

  const resolvedUnit = unit === "auto" ? pickUnit(Math.abs(deltaSeconds)) : unit;

  return new Intl.RelativeTimeFormat(locale, { numeric: "auto" }).format(
    Math.round(deltaSeconds),
    resolvedUnit,
  );
}

function pickUnit(value: number): Intl.RelativeTimeFormatUnit {
  if (value < 60) return "second";
  if (value < 3600) return "minute";
  if (value < 86400) return "hour";
  if (value < 604800) return "day";
  if (value < 2629800) return "week";
  if (value < 31557600) return "month";
  return "year";
}
```

## Usage

```ts
import { formatPrice, formatPercent, formatDate, formatDateTime, formatRelativeTime } from "./format";

formatPrice(1234.5);                                   // "$1,234.50"
formatPrice(1234.5, { locale: "de-DE", currency: "EUR" }); // "1.234,50 €"
formatPrice(1234.5, { useCurrencyCode: true });         // "USD 1,234.50"
formatPrice(null);                                     // "—"

formatPercent(0.256);                                  // "26%"
formatDate("2024-03-09T12:00:00Z", { style: "long", timeZone: "UTC" });
formatDateTime(new Date(), { timeZone: "Europe/Berlin" });
formatRelativeTime(new Date(Date.now() - 3 * 86400_000)); // "3 days ago"
```

Notes:
- All functions are pure and locale-aware; pass `locale`/`timeZone` explicitly for deterministic output (useful in tests).
- `Intl` is available in modern browsers, Node 18+, and Deno/Bun — no polyfill or dependency needed.
- Invalid/missing inputs return the `fallback` string rather than throwing.

```ts
// format.ts

export interface FormatPriceOptions {
  /** ISO 4217 currency code, e.g. "USD", "EUR". Defaults to "USD". */
  currency?: string;
  /** BCP 47 locale, e.g. "en-US", "de-DE". Defaults to the runtime locale. */
  locale?: string;
  /** "standard" (1,234.56) or "compact" (1.2K). */
  notation?: "standard" | "compact";
  /** Fixed number of fraction digits. Omit to use the currency's default. */
  fractionDigits?: number;
  /** Whether to append the currency symbol/code. Defaults to true. */
  showCurrency?: boolean;
}

export interface FormatDateOptions {
  locale?: string;
  /** e.g. "medium", "short", "full". */
  dateStyle?: Intl.DateTimeFormatOptions["dateStyle"];
  /** e.g. "short", "medium". */
  timeStyle?: Intl.DateTimeFormatOptions["timeStyle"];
  /** Explicit format overrides take precedence over the styles above. */
  pattern?: Intl.DateTimeFormatOptions;
}

/** Formats a number as a price, e.g. 1234.5 -> "$1,234.50". */
export function formatPrice(value: number, options: FormatPriceOptions = {}): string {
  const {
    currency = "USD",
    locale,
    notation = "standard",
    fractionDigits,
    showCurrency = true,
  } = options;

  if (!Number.isFinite(value)) {
    throw new RangeError(`formatPrice: expected a finite number, received ${value}`);
  }

  return new Intl.NumberFormat(locale, {
    style: showCurrency ? "currency" : "decimal",
    currency: showCurrency ? currency : undefined,
    currencyDisplay: "symbol",
    notation,
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  }).format(value);
}

/** Formats a number as a percentage, e.g. 0.256 -> "25.6%". */
export function formatPercent(
  value: number,
  options: { locale?: string; fractionDigits?: number } = {},
): string {
  const { locale, fractionDigits = 1 } = options;

  if (!Number.isFinite(value)) {
    throw new RangeError(`formatPercent: expected a finite number, received ${value}`);
  }

  return new Intl.NumberFormat(locale, {
    style: "percent",
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  }).format(value);
}

/** Formats a date, e.g. "Jan 5, 2025". Accepts a Date, timestamp, or ISO string. */
export function formatDate(
  date: Date | number | string,
  options: FormatDateOptions = {},
): string {
  const { locale, dateStyle = "medium", timeStyle, pattern } = options;
  const d = toDate(date);

  const intlOptions: Intl.DateTimeFormatOptions = pattern ?? {
    dateStyle,
    ...(timeStyle ? { timeStyle } : {}),
  };

  return new Intl.DateTimeFormat(locale, intlOptions).format(d);
}

/** Formats only the time portion, e.g. "3:04 PM". */
export function formatTime(
  date: Date | number | string,
  options: { locale?: string; timeStyle?: Intl.DateTimeFormatOptions["timeStyle"] } = {},
): string {
  const { locale, timeStyle = "short" } = options;
  return new Intl.DateTimeFormat(locale, { timeStyle }).format(toDate(date));
}

/** Formats a date relative to now, e.g. "3 days ago", "in 2 hours". */
export function formatRelativeTime(
  date: Date | number | string,
  options: { locale?: string; now?: Date } = {},
): string {
  const { locale, now = new Date() } = options;
  const target = toDate(date);
  const deltaSeconds = (target.getTime() - now.getTime()) / 1000;

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });

  for (const [unit, seconds] of units) {
    if (Math.abs(deltaSeconds) >= seconds || unit === "second") {
      return rtf.format(Math.round(deltaSeconds / seconds), unit);
    }
  }

  return rtf.format(0, "second");
}

function toDate(date: Date | number | string): Date {
  const d = date instanceof Date ? date : new Date(date);
  if (Number.isNaN(d.getTime())) {
    throw new RangeError(`Invalid date: ${String(date)}`);
  }
  return d;
}
```

Example usage:

```ts
formatPrice(1234.5);                        // "$1,234.50"
formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }); // "1.234,50 €"
formatPrice(1_200_000, { notation: "compact" });           // "$1.2M"
formatPercent(0.256);                        // "25.6%"
formatDate("2025-01-05T15:04:00Z");           // "Jan 5, 2025"
formatTime("2025-01-05T15:04:00Z", { timeStyle: "medium" }); // "3:04:00 PM"
formatRelativeTime(new Date(Date.now() - 3 * 864e5));       // "3 days ago"
