/**
 * Small, dependency-free helpers for formatting prices and dates.
 * Output is produced by the built-in `Intl` APIs, so it follows the
 * runtime's locale data (and respects the user's locale settings).
 */

/* -------------------------------------------------------------------------- */
/* Prices                                                                     */
/* -------------------------------------------------------------------------- */

export interface PriceFormatOptions extends Omit<Intl.NumberFormatOptions, "style"> {
  /** ISO 4217 currency code. Default: "USD". */
  currency?: string;
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
}

/**
 * Format a monetary amount, e.g. `formatPrice(1234.5)` -> "$1,234.50".
 *
 * @throws TypeError if `amount` is not a finite number.
 */
export function formatPrice(amount: number, options: PriceFormatOptions = {}): string {
  if (typeof amount !== "number" || !Number.isFinite(amount)) {
    throw new TypeError(`formatPrice: expected a finite number, received ${String(amount)}`);
  }

  const { currency = "USD", locale = "en-US", ...intlOptions } = options;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    ...intlOptions,
  }).format(amount);
}

/**
 * Format a number as a plain decimal string, e.g. `formatAmount(0.5)` -> "0.50".
 * Useful when you want the digits but not a currency symbol.
 */
export function formatAmount(
  amount: number,
  options: Omit<Intl.NumberFormatOptions, "style"> & { locale?: string } = {},
): string {
  if (typeof amount !== "number" || !Number.isFinite(amount)) {
    throw new TypeError(`formatAmount: expected a finite number, received ${String(amount)}`);
  }

  const { locale = "en-US", ...intlOptions } = options;

  return new Intl.NumberFormat(locale, {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
    ...intlOptions,
  }).format(amount);
}

/* -------------------------------------------------------------------------- */
/* Dates                                                                       */
/* -------------------------------------------------------------------------- */

/** Anything that can be turned into a `Date`. */
export type DateInput = Date | string | number;

export interface DateFormatOptions extends Intl.DateTimeFormatOptions {
  /** BCP 47 locale tag. Default: "en-US". */
  locale?: string;
}

/**
 * Normalize a `DateInput` into a valid `Date`.
 *
 * @throws RangeError if the value cannot be parsed as a date.
 */
export function toDate(value: DateInput): Date {
  const date = value instanceof Date ? value : new Date(value);

  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`toDate: invalid date value: ${String(value)}`);
  }

  return date;
}

/**
 * Format a date, e.g. `formatDate("2024-03-08")` -> "Mar 8, 2024".
 * Pass standard `Intl.DateTimeFormatOptions` to override the defaults.
 */
export function formatDate(value: DateInput, options: DateFormatOptions = {}): string {
  const { locale = "en-US", ...intlOptions } = options;

  return new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "short",
    day: "numeric",
    ...intlOptions,
  }).format(toDate(value));
}

/**
 * Format a date and time, e.g. `formatDateTime(date)` -> "Mar 8, 2024, 2:30 PM".
 */
export function formatDateTime(value: DateInput, options: DateFormatOptions = {}): string {
  const { locale = "en-US", ...intlOptions } = options;

  return new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
    ...intlOptions,
  }).format(toDate(value));
}

/**
 * Format a date relative to `now`, e.g. "2 days ago" / "in 3 hours".
 */
export function formatRelativeDate(
  value: DateInput,
  options: { locale?: string; now?: Date } = {},
): string {
  const { locale = "en-US", now = new Date() } = options;
  const diffMs = toDate(value).getTime() - now.getTime();

  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ["year", 365 * 24 * 60 * 60 * 1000],
    ["month", 30 * 24 * 60 * 60 * 1000],
    ["week", 7 * 24 * 60 * 60 * 1000],
    ["day", 24 * 60 * 60 * 1000],
    ["hour", 60 * 60 * 1000],
    ["minute", 60 * 1000],
    ["second", 1000],
  ];

  const absDiff = Math.abs(diffMs);
  const [unit, unitMs] = units.find(([, ms]) => absDiff >= ms) ?? units[units.length - 1];

  return new Intl.RelativeTimeFormat(locale, { numeric: "auto" }).format(
    Math.round(diffMs / unitMs),
    unit,
  );
}
