Below is a dependency-free module built on the `Intl` API (works in Node 18+, browsers, Deno, Bun). It covers prices, percentages, and dates, with input validation and formatter caching.

## `src/format.ts`

```ts
/**
 * Small, dependency-free helpers for formatting prices and dates.
 *
 * Built on the Intl API, so output is locale-aware.
 * Requires ES2020+ (or `lib: ["ES2020", "DOM"]` in tsconfig).
 */

/* -------------------------------------------------------------------------- */
/* Internal utilities                                                          */
/* -------------------------------------------------------------------------- */

const DEFAULT_LOCALE = 'en-US';

/** Intl formatters are expensive to construct, so cache them by options. */
const numberFormatters = new Map<string, Intl.NumberFormat>();
const dateFormatters = new Map<string, Intl.DateTimeFormat>();
const relativeFormatters = new Map<string, Intl.RelativeTimeFormat>();

function getNumberFormatter(
  locale: string,
  options: Intl.NumberFormatOptions,
): Intl.NumberFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let formatter = numberFormatters.get(key);
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options);
    numberFormatters.set(key, formatter);
  }
  return formatter;
}

function getDateFormatter(
  locale: string,
  options: Intl.DateTimeFormatOptions,
): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let formatter = dateFormatters.get(key);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, options);
    dateFormatters.set(key, formatter);
  }
  return formatter;
}

function getRelativeFormatter(
  locale: string,
  options: Intl.RelativeTimeFormatOptions,
): Intl.RelativeTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let formatter = relativeFormatters.get(key);
  if (!formatter) {
    formatter = new Intl.RelativeTimeFormat(locale, options);
    relativeFormatters.set(key, formatter);
  }
  return formatter;
}

function assertFiniteNumber(value: number, fn: string): void {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(
      `${fn}: expected a finite number, received ${String(value)}`,
    );
  }
}

/* -------------------------------------------------------------------------- */
/* Prices                                                                      */
/* -------------------------------------------------------------------------- */

export interface PriceOptions {
  /** BCP-47 locale tag. Defaults to `"en-US"`. */
  locale?: string;
  /** ISO 4217 currency code. Defaults to `"USD"`. */
  currency?: string;
  currencyDisplay?: 'symbol' | 'narrowSymbol' | 'code' | 'name';
  /** Minimum fraction digits shown (default: currency's own default, usually 2). */
  minimumFractionDigits?: number;
  /** Maximum fraction digits shown (default: currency's own default, usually 2). */
  maximumFractionDigits?: number;
  /** Use grouping separators ("1,234.56"). Defaults to `true`. */
  useGrouping?: boolean;
  signDisplay?: 'auto' | 'always' | 'exceptZero' | 'never';
  /** Treat the input as minor units (cents) rather than major units. */
  fromCents?: boolean;
}

/**
 * Format a monetary amount.
 *
 * @example
 * formatPrice(1234.5);                       // "$1,234.50"
 * formatPrice(1234.5, { currency: 'EUR' });  // "€1,234.50"
 * formatPrice(1050, { fromCents: true });    // "$10.50"
 */
export function formatPrice(value: number, options: PriceOptions = {}): string {
  assertFiniteNumber(value, 'formatPrice');

  const {
    locale = DEFAULT_LOCALE,
    currency = 'USD',
    fromCents = false,
    ...rest
  } = options;

  const amount = fromCents ? value / 100 : value;

  return getNumberFormatter(locale, {
    style: 'currency',
    currency,
    ...rest,
  }).format(amount);
}

/**
 * Format a monetary amount in compact notation ("$1.2K").
 */
export function formatCompactPrice(
  value: number,
  options: PriceOptions & { compactDisplay?: 'short' | 'long' } = {},
): string {
  assertFiniteNumber(value, 'formatCompactPrice');

  const {
    locale = DEFAULT_LOCALE,
    currency = 'USD',
    fromCents = false,
    compactDisplay = 'short',
    ...rest
  } = options;

  const amount = fromCents ? value / 100 : value;

  return getNumberFormatter(locale, {
    style: 'currency',
    currency,
    notation: 'compact',
    compactDisplay,
    ...rest,
  }).format(amount);
}

/**
 * Format a plain number with grouping and optional fixed decimals.
 *
 * @example
 * formatNumber(1234567);                    // "1,234,567"
 * formatNumber(3.14159, { maximumFractionDigits: 2 }); // "3.14"
 */
export function formatNumber(
  value: number,
  options: {
    locale?: string;
    minimumFractionDigits?: number;
    maximumFractionDigits?: number;
    useGrouping?: boolean;
    notation?: 'standard' | 'compact';
    compactDisplay?: 'short' | 'long';
  } = {},
): string {
  assertFiniteNumber(value, 'formatNumber');

  const { locale = DEFAULT_LOCALE, ...rest } = options;
  return getNumberFormatter(locale, { style: 'decimal', ...rest }).format(value);
}

/**
 * Format a ratio as a percentage.
 *
 * @example
 * formatPercentage(0.156);                 // "16%"
 * formatPercentage(15.6, { fromPercent: true }); // "16%"
 */
export function formatPercentage(
  value: number,
  options: {
    locale?: string;
    fromPercent?: boolean;
    minimumFractionDigits?: number;
    maximumFractionDigits?: number;
    signDisplay?: 'auto' | 'always' | 'exceptZero' | 'never';
  } = {},
): string {
  assertFiniteNumber(value, 'formatPercentage');

  const { locale = DEFAULT_LOCALE, fromPercent = false, ...rest } = options;
  const ratio = fromPercent ? value / 100 : value;

  return getNumberFormatter(locale, { style: 'percent', ...rest }).format(ratio);
}

/**
 * Convert a major-unit amount to integer minor units (cents), avoiding
 * floating-point drift.
 */
export function toCents(amount: number): number {
  assertFiniteNumber(amount, 'toCents');
  return Math.round((amount + Number.EPSILON) * 100);
}

/**
 * Convert integer minor units (cents) to a major-unit amount.
 */
export function fromCents(cents: number): number {
  assertFiniteNumber(cents, 'fromCents');
  return cents / 100;
}

/**
 * The currency symbol for a given currency code and locale.
 *
 * @example
 * currencySymbol('USD', 'en-US'); // "$"
 */
export function currencySymbol(
  currency: string,
  locale: string = DEFAULT_LOCALE,
): string {
  const parts = getNumberFormatter(locale, {
    style: 'currency',
    currency,
    currencyDisplay: 'narrowSymbol',
  }).formatToParts(0);
  return parts.find((part) => part.type === 'currency')?.value ?? currency;
}

/* -------------------------------------------------------------------------- */
/* Dates                                                                       */
/* -------------------------------------------------------------------------- */

/** Anything we accept as a date: a `Date`, an ISO string, or a timestamp. */
export type DateInput = Date | string | number;

/**
 * Normalize a date-like value into a valid `Date`.
 *
 * @throws {RangeError} if the value cannot be parsed.
 */
export function toDate(input: DateInput): Date {
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`toDate: could not parse date ${JSON.stringify(input)}`);
  }
  return date;
}

export interface DateFormatOptions {
  locale?: string;
  /** IANA time zone, e.g. `"America/New_York"`. Defaults to the runtime's zone. */
  timeZone?: string;
  /** Full date + time styles. Cannot be combined with the component options below. */
  dateStyle?: 'full' | 'long' | 'medium' | 'short';
  timeStyle?: 'full' | 'long' | 'medium' | 'short';
  year?: 'numeric' | '2-digit';
  month?: 'numeric' | '2-digit' | 'long' | 'short' | 'narrow';
  day?: 'numeric' | '2-digit';
  weekday?: 'long' | 'short' | 'narrow';
  hour?: 'numeric' | '2-digit';
  minute?: 'numeric' | '2-digit';
  second?: 'numeric' | '2-digit';
  hour12?: boolean;
  era?: 'long' | 'short' | 'narrow';
}

const COMPONENT_KEYS = [
  'year',
  'month',
  'day',
  'weekday',
  'hour',
  'minute',
  'second',
  'hour12',
  'era',
] as const;

/**
 * Format a date.
 *
 * @example
 * formatDate('2024-03-09T12:00:00Z');                 // "Mar 9, 2024"
 * formatDate(d, { dateStyle: 'full' });                 // "Saturday, March 9, 2024"
 * formatDate(d, { year: 'numeric', month: 'long' });    // "March 2024"
 */
export function formatDate(
  input: DateInput,
  options: DateFormatOptions = {},
): string {
  const { locale = DEFAULT_LOCALE, ...rest } = options;

  const usesStyles = rest.dateStyle !== undefined || rest.timeStyle !== undefined;
  const usesComponents = COMPONENT_KEYS.some((key) => rest[key] !== undefined);
  if (usesStyles && usesComponents) {
    throw new TypeError(
      'formatDate: dateStyle/timeStyle cannot be combined with year/month/day/hour/etc.',
    );
  }

  const intlOptions: Intl.DateTimeFormatOptions = usesStyles
    ? { dateStyle: rest.dateStyle, timeStyle: rest.timeStyle, timeZone: rest.timeZone }
    : { ...rest, timeZone: rest.timeZone };

  return getDateFormatter(locale, intlOptions).format(toDate(input));
}

/**
 * Format a date and time.
 *
 * @example
 * formatDateTime('2024-03-09T12:00:00Z'); // "Mar 9, 2024, 12:00 PM"
 */
export function formatDateTime(
  input: DateInput,
  options: DateFormatOptions = {},
): string {
  const { locale = DEFAULT_LOCALE, timeZone, ...rest } = options;
  return formatDate(input, {
    locale,
    timeZone,
    dateStyle: rest.dateStyle ?? 'medium',
    timeStyle: rest.timeStyle ?? 'short',
  });
}

/**
 * Format only the time portion of a date.
 *
 * @example
 * formatTime('2024-03-09T12:00:00Z'); // "12:00 PM"
 */
export function formatTime(
  input: DateInput,
  options: DateFormatOptions = {},
): string {
  const { locale = DEFAULT_LOCALE, timeZone } = options;
  return formatDate(input, { locale, timeZone, timeStyle: 'short' });
}

/**
 * ISO-8601 date (UTC), e.g. `"2024-03-09"`.
 */
export function formatISODate(input: DateInput): string {
  return toDate(input).toISOString().slice(0, 10);
}

/**
 * ISO-8601 date and time (UTC), e.g. `"2024-03-09T12:00:00.000Z"`.
 */
export function formatISODateTime(input: DateInput): string {
  return toDate(input).toISOString();
}

/**
 * Calendar date in a specific time zone, e.g. `"2024-03-08"` in `America/New_York`.
 */
export function formatISODateInTimeZone(
  input: DateInput,
  timeZone: string,
): string {
  return getDateFormatter('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(toDate(input));
}

const RELATIVE_DIVISIONS: ReadonlyArray<{
  amount: number;
  unit: Intl.RelativeTimeFormatUnit;
}> = [
  { amount: 60, unit: 'seconds' },
  { amount: 60, unit: 'minutes' },
  { amount: 24, unit: 'hours' },
  { amount: 7, unit: 'days' },
  { amount: 4.34524, unit: 'weeks' },
  { amount: 12, unit: 'months' },
  { amount: Number.POSITIVE_INFINITY, unit: 'years' },
];

/**
 * Format a date relative to another point in time ("3 days ago", "in 2 hours").
 *
 * @example
 * formatRelativeTime('2024-03-06T12:00:00Z', { now: '2024-03-09T12:00:00Z' });
 * // "3 days ago"
 */
export function formatRelativeTime(
  input: DateInput,
  options: {
    locale?: string;
    /** Reference point. Defaults to `new Date()`. */
    now?: DateInput;
    /** `"auto"` renders "yesterday" instead of "1 day ago". */
    numeric?: 'always' | 'auto';
    style?: 'long' | 'short' | 'narrow';
  } = {},
): string {
  const {
    locale = DEFAULT_LOCALE,
    now = new Date(),
    numeric = 'auto',
    style = 'long',
  } = options;

  const formatter = getRelativeFormatter(locale, { numeric, style });
  let duration = (toDate(input).getTime() - toDate(now).getTime()) / 1000;

  for (const division of RELATIVE_DIVISIONS) {
    if (Math.abs(duration) < division.amount) {
      return formatter.format(Math.round(duration), division.unit);
    }
    duration /= division.amount;
  }

  return formatter.format(Math.round(duration), 'years');
}

/**
 * Format a duration in seconds as a compact string ("2d 3h", "45s").
 */
export function formatDuration(
  totalSeconds: number,
  options: { maxUnits?: number } = {},
): string {
  assertFiniteNumber(totalSeconds, 'formatDuration');

  const { maxUnits = 2 } = options;
  const units = [
    { suffix: 'd', seconds: 86_400 },
    { suffix: 'h', seconds: 3_600 },
    { suffix: 'm', seconds: 60 },
    { suffix: 's', seconds: 1 },
  ];

  let remaining = Math.floor(Math.abs(totalSeconds));
  const parts: string[] = [];

  for (const unit of units) {
    if (parts.length >= maxUnits) break;
    const count = Math.floor(remaining / unit.seconds);
    if (count > 0) {
      parts.push(`${count}${unit.suffix}`);
      remaining -= count * unit.seconds;
    }
  }

  if (parts.length === 0) return '0s';
  return `${totalSeconds < 0 ? '-' : ''}${parts.join(' ')}`;
}

/**
 * Whether two dates fall on the same calendar day (optionally in a given zone).
 */
export function isSameDay(
  a: DateInput,
  b: DateInput,
  timeZone?: string,
): boolean {
  const formatter = getDateFormatter('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  });
  return formatter.format(toDate(a)) === formatter.format(toDate(b));
}
```

