## Usage

```ts
import { formatPrice, formatRelativeTime, formatDate } from './format';

const invoice = {
  total: 1999,                                   // cents
  createdAt: '2024-03-09T12:00:00Z',
};

formatPrice(invoice.total, { fromCents: true, currency: 'EUR' }); // "19,99 €"
formatDate(invoice.createdAt, { dateStyle: 'long' });            // "March 9, 2024"
formatRelativeTime(invoice.createdAt);                           // "5 months ago"
```

**Design notes**

- **Caching** — `Intl` formatters are costly to build, so instances are memoized by locale + options.
- **Validation** — invalid numbers throw `TypeError`; unparseable dates throw `RangeError`, so bugs surface at the call site instead of rendering `"$NaN"`.
- **Cents handling** — `fromCents` / `toCents` avoid the classic `0.1 + 0.2` rounding bug.
- **Locale awareness** — every function accepts a `locale` (and dates accept a `timeZone`), so output adapts without extra code.

One caveat: `formatDuration` uses fixed English abbreviations (`d`/`h`/`m`/`s`) rather than `Intl` translations, since `Intl.DurationFormat` isn't widely available yet. If you need localized durations, that would be the piece to swap out.

```ts
// format.ts

export interface PriceOptions {
  /** BCP 47 locale tag, e.g. "en-US" */
  locale?: string;
  /** ISO 4217 currency code, e.g. "USD" */
  currency?: string;
  /** Number of fraction digits (defaults to the currency's standard) */
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  /** Render as a compact string, e.g. "$1.2K" */
  compact?: boolean;
  /** Prefix the result, e.g. "Total: $12.00" */
  prefix?: string;
}

export interface DateOptions {
  /** BCP 47 locale tag, e.g. "en-US" */
  locale?: string;
  /** Use a named style like "short", "medium", "long", "full" */
  dateStyle?: "short" | "medium" | "long" | "full";
  timeStyle?: "short" | "medium" | "long" | "full";
  /** Or specify parts individually (ignored if dateStyle/timeStyle are set) */
  year?: "numeric" | "2-digit";
  month?: "numeric" | "2-digit" | "short" | "long" | "narrow";
  day?: "numeric" | "2-digit";
  hour?: "numeric" | "2-digit";
  minute?: "numeric" | "2-digit";
  second?: "numeric" | "2-digit";
  timeZone?: string;
  /** Include a time-zone abbreviation, e.g. "PST" */
  timeZoneName?: "short" | "long";
}

/**
 * Format a monetary amount.
 * @throws RangeError if the amount is not a finite number.
 */
export function formatPrice(amount: number, options: PriceOptions = {}): string {
  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid price amount: ${amount}`);
  }

  const {
    locale = "en-US",
    currency = "USD",
    minimumFractionDigits,
    maximumFractionDigits,
    compact = false,
    prefix = "",
  } = options;

  const formatter = new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
    ...(minimumFractionDigits !== undefined && { minimumFractionDigits }),
    ...(maximumFractionDigits !== undefined && { maximumFractionDigits }),
  });

  return `${prefix}${formatter.format(amount)}`;
}

/**
 * Format a date (Date object, timestamp, or ISO string).
 * @throws RangeError if the input cannot be parsed as a date.
 */
export function formatDate(date: Date | number | string, options: DateOptions = {}): string {
  const parsed = toDate(date);
  const {
    locale = "en-US",
    dateStyle,
    timeStyle,
    year,
    month,
    day,
    hour,
    minute,
    second,
    timeZone,
    timeZoneName,
  } = options;

  const hasParts = year || month || day || hour || minute || second || timeZoneName;
  const useStyles = dateStyle || timeStyle;

  const formatter = new Intl.DateTimeFormat(
    locale,
    useStyles
      ? { dateStyle, timeStyle, ...(timeZone && { timeZone }) }
      : {
          year,
          month,
          day,
          hour,
          minute,
          second,
          timeZoneName,
          ...(timeZone && { timeZone }),
        },
  );

  // If neither styles nor parts were given, fall back to a readable default.
  if (!useStyles && !hasParts) {
    return new Intl.DateTimeFormat(locale, {
      dateStyle: "medium",
      ...(timeZone && { timeZone }),
    }).format(parsed);
  }

  return formatter.format(parsed);
}

/** Format both date and time, e.g. "Jan 5, 2025, 3:04 PM". */
export function formatDateTime(
  date: Date | number | string,
  options: DateOptions = {},
): string {
  return formatDate(date, {
    dateStyle: "medium",
    timeStyle: "short",
    ...options,
  });
}

/** Relative time, e.g. "3 days ago". */
export function formatRelativeTime(
  date: Date | number | string,
  locale = "en-US",
  now: Date = new Date(),
): string {
  const parsed = toDate(date);
  const diffSeconds = (parsed.getTime() - now.getTime()) / 1000;
  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["year", 60 * 60 * 24 * 365],
    ["month", 60 * 60 * 24 * 30],
    ["week", 60 * 60 * 24 * 7],
    ["day", 60 * 60 * 24],
    ["hour", 60 * 60],
    ["minute", 60],
    ["second", 1],
  ];

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  for (const [unit, seconds] of units) {
    if (Math.abs(diffSeconds) >= seconds || unit === "second") {
      return rtf.format(Math.round(diffSeconds / seconds), unit);
    }
  }
  return rtf.format(0, "second");
}

function toDate(value: Date | number | string): Date {
  const d = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(d.getTime())) {
    throw new RangeError(`Invalid date: ${String(value)}`);
  }
  return d;
}
```

**Usage**

```ts
formatPrice(1234.5);                                  // "$1,234.50"
formatPrice(1234.5, { currency: "EUR", locale: "de-DE" }); // "1.234,50 €"
formatPrice(1_200_000, { compact: true });             // "$1.2M"
formatPrice(19.99, { prefix: "Total: " });             // "Total: $19.99"

formatDate("2025-01-05T15:04:00Z");                   // "Jan 5, 2025"
formatDate(new Date(), { dateStyle: "full", timeZone: "UTC" });
formatDateTime("2025-01-05T15:04:00Z", { timeZone: "America/New_York" });
formatRelativeTime(Date.now() - 3 * 24 * 60 * 60 * 1000); // "3 days ago"
```

Notes:
- All output goes through `Intl`, so results are locale-aware and timezone-aware.
- Amounts are stored as numbers; if you need exact currency arithmetic, use integer minor units (e.g. cents) or a decimal library before calling `formatPrice`.

## `useOnlineStatus.ts`

```ts
import { useSyncExternalStore } from 'react';

/**
 * Subscribe to the browser's online/offline events.
 * Returns an unsubscribe function (useSyncExternalStore's cleanup contract).
 */
function subscribe(onStoreChange: () => void): () => void {
  window.addEventListener('online', onStoreChange);
  window.addEventListener('offline', onStoreChange);

  return () => {
    window.removeEventListener('online', onStoreChange);
    window.removeEventListener('offline', onStoreChange);
  };
}

/** Current value, read on every render to detect changes. */
function getSnapshot(): boolean {
  return navigator.onLine;
}

/** Value used during SSR / hydration, where `navigator` doesn't exist. */
function getServerSnapshot(): boolean {
  return true;
}

/**
 * Tracks whether the browser is currently online.
 *
 * @returns `true` when the browser reports a network connection, `false` when offline.
 *
 * @example
 * const isOnline = useOnlineStatus();
 * if (!isOnline) return <OfflineBanner />;
 */
export function useOnlineStatus(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

export default useOnlineStatus;
```

### Why `useSyncExternalStore`?

The browser's online status lives *outside* React, so it's a textbook external store. `useSyncExternalStore` handles the tricky parts for you:

- **No stale renders** — the snapshot is re-read during render, so a change that happens between render and commit is caught.
- **SSR-safe** — `getServerSnapshot` avoids touching `navigator` on the server, and hydration matches the server output.
- **Correct cleanup** — listeners are removed on unmount.

### Usage

```tsx
import { useOnlineStatus } from './useOnlineStatus';

function SaveButton() {
  const isOnline = useOnlineStatus();

  return (
    <button disabled={!isOnline}>
      {isOnline ? 'Save' : 'Offline — changes will be queued'}
    </button>
  );
}
```

### Notes & caveats

- `navigator.onLine` only tells you whether the browser *thinks* it has a network connection. It does **not** mean your API is reachable — a captive portal or a dead upstream server still reports `true`. For real connectivity checks, ping your own endpoint.
- The `online`/`offline` events fire on the `window`, so they work across tabs automatically (no `localStorage` sync needed).
- If you need to distinguish "was offline and just came back" (e.g. to trigger a data refetch), keep the previous value in state:

```ts
export function useConnectionChange(onReconnect: () => void) {
  const isOnline = useOnlineStatus();
  const wasOnline = useRef(isOnline);

  useEffect(() => {
    if (wasOnline.current === false && isOnline === true) {
      onReconnect();
    }
    wasOnline.current = isOnline;
  }, [isOnline, onReconnect]);
}
```

