## `useOnlineStatus.ts`

```ts
import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * Reads the browser's current connectivity flag.
 * Returns `true` during SSR (no `navigator`) to avoid hydration mismatches;
 * the real value is applied in the effect on the client.
 */
function getInitialOnline(): boolean {
  if (typeof navigator === 'undefined') return true
  return navigator.onLine
}

/**
 * Tracks whether the browser is online or offline.
 *
 * Listens to the `online` / `offline` window events and keeps the returned
 * value in sync. Listeners are removed on unmount.
 *
 * @example
 * const isOnline = useOnlineStatus()
 * if (!isOnline) return <Banner>You are offline — changes won't be saved.</Banner>
 */
export function useOnlineStatus(): boolean {
  const [isOnline, setIsOnline] = useState<boolean>(getInitialOnline)

  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    // The status may have flipped between the initial render and this effect
    // (e.g. while the tab was backgrounded), so re-sync once.
    setIsOnline(navigator.onLine)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  return isOnline
}

/* -------------------------------------------------------------------------- */
/* Optional: a richer variant that verifies real reachability                 */
/* -------------------------------------------------------------------------- */

export type Connectivity = {
  /** `true` when the browser reports a network connection. */
  isOnline: boolean
  /** `true` when a reachability probe to `checkUrl` is failing. */
  isReachable: boolean
  /** Timestamp (ms) of the last detected change, or `null` if never changed. */
  lastChangedAt: number | null
  /** Manually re-run the probe. */
  refresh: () => void
}

/**
 * Like `useOnlineStatus`, but optionally verifies that the internet is
 * actually reachable by probing `checkUrl`.
 *
 * `navigator.onLine` only tells you whether the device is attached to *some*
 * network — it stays `true` on a captive portal, a dead Wi-Fi link, or when
 * the upstream connection is down. Passing a `checkUrl` (e.g. your own
 * `/api/health` endpoint) gives a much more accurate answer.
 *
 * @param checkUrl   URL to probe. When omitted, only `navigator.onLine` is used.
 * @param intervalMs How often to re-probe while mounted.
 */
export function useConnectivity(
  checkUrl?: string,
  intervalMs = 30_000,
): Connectivity {
  const [isOnline, setIsOnline] = useState<boolean>(getInitialOnline)
  const [isReachable, setIsReachable] = useState<boolean>(getInitialOnline)
  const [lastChangedAt, setLastChangedAt] = useState<number | null>(null)
  const abortRef = useRef<AbortController | null>(null)

  const update = useCallback((online: boolean, reachable: boolean) => {
    setIsOnline((prevOnline) => {
      setIsReachable((prevReachable) => {
        if (prevOnline !== online || prevReachable !== reachable) {
          setLastChangedAt(Date.now())
        }
        return reachable
      })
      return online
    })
  }, [])

  const probe = useCallback(async () => {
    if (!checkUrl) return

    abortRef.current?.abort()
    const controller = new AbortController()
    abortRef.current = controller

    try {
      await fetch(checkUrl, {
        method: 'HEAD',
        cache: 'no-store',
        signal: controller.signal,
      })
      update(navigator.onLine, true)
    } catch (error) {
      if ((error as Error).name === 'AbortError') return
      update(navigator.onLine, false)
    }
  }, [checkUrl, update])

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true)
      void probe()
    }
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    setIsOnline(navigator.onLine)
    void probe()

    const timer = checkUrl ? window.setInterval(() => void probe(), intervalMs) : undefined

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
      if (timer !== undefined) window.clearInterval(timer)
      abortRef.current?.abort()
    }
  }, [probe, intervalMs, checkUrl])

  return { isOnline, isReachable, lastChangedAt, refresh: () => void probe() }
}
```

