import { useSyncExternalStore } from 'react';

/**
 * Reads the current connectivity state.
 * `navigator.onLine` is `false` when the browser has no network connection
 * (airplane mode, no Wi-Fi, cable unplugged). It is `true` as soon as a
 * network interface is up — it does NOT guarantee the internet is reachable.
 */
const getSnapshot = (): boolean =>
  typeof navigator === 'undefined' ? true : navigator.onLine !== false;

/**
 * Snapshot used during server rendering / hydration, where there is no
 * `navigator`. Assume "online" so the server and client markup match.
 */
const getServerSnapshot = (): boolean => true;

/**
 * Subscribes to the browser's connectivity events. The `online` and `offline`
 * events fire on `window` in every tab of the same origin, so all tabs stay
 * in sync automatically.
 */
const subscribe = (onStoreChange: () => void): (() => void) => {
  if (typeof window === 'undefined') return () => {};

  window.addEventListener('online', onStoreChange);
  window.addEventListener('offline', onStoreChange);

  return () => {
    window.removeEventListener('online', onStoreChange);
    window.removeEventListener('offline', onStoreChange);
  };
};

/**
 * Tracks whether the browser is online or offline.
 *
 * @returns `true` when online, `false` when offline.
 *
 * @example
 * const isOnline = useOnlineStatus();
 * if (!isOnline) return <OfflineBanner />;
 */
export function useOnlineStatus(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

export default useOnlineStatus;
```

