  };
}

/** Reads the current value from the browser. */
function getSnapshot(): boolean {
  return navigator.onLine;
}

/** Value used during server-side rendering (no `window`/`navigator` available). */
function getServerSnapshot(): boolean {
  return true;
}

/**
 * Returns `true` when the browser believes it is online, `false` when offline.
 */
export function useOnlineStatus(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}
```

## Usage

```tsx
import { useOnlineStatus } from "./useOnlineStatus";

function ConnectionBanner() {
  const isOnline = useOnlineStatus();

  if (isOnline) return null;

  return (
    <div role="alert">
      You are offline. Some features may be unavailable.
    </div>
  );
}
```

## Notes

- **Why `useSyncExternalStore`:** the online/offline state lives outside React (in the browser), so this hook treats it as an external store. React handles subscribing, unsubscribing, and tearing-free reads for you — no `useState`/`useEffect` needed.
- **SSR safety:** `getServerSnapshot` prevents the `navigator is not defined` crash during server rendering. The hook hydrates to the real value on the client.
- **Caveat:** `navigator.onLine` only reports whether the device is connected to a network — it does *not* guarantee actual internet reachability (a captive portal or dead upstream connection still reports "online"). If you need real connectivity, pair this with a ping/fetch check.
- **Older React (< 18):** `useSyncExternalStore` isn't available; use `useState` + `useEffect` instead:

```ts
export function useOnlineStatus(): boolean {
  const [isOnline, setIsOnline] = useState(() =>
    typeof navigator === "undefined" ? true : navigator.onLine
  );

  useEffect(() => {
    const goOnline = () => setIsOnline(true);
    const goOffline = () => setIsOnline(false);

    window.addEventListener("online", goOnline);
    window.addEventListener("offline", goOffline);

    // Re-sync in case the status changed between render and effect.
    setIsOnline(navigator.onLine);

    return () => {
      window.removeEventListener("online", goOnline);
      window.removeEventListener("offline", goOffline);
    };
  }, []);

  return isOnline;
}
```

