import { useSyncExternalStore } from 'react';

/**
 * Subscribes to the browser's `online` / `offline` events.
 * `useSyncExternalStore` expects a function that returns an unsubscribe callback.
 */
function subscribe(onStoreChange: () => void): () => void {
  window.addEventListener('online', onStoreChange);
  window.addEventListener('offline', onStoreChange);

  return () => {
    window.removeEventListener('online', onStoreChange);
    window.removeEventListener('offline', onStoreChange);
  };
}

/**
 * Client snapshot: the browser's current connectivity flag.
 * Must return a cached/stable value — a primitive boolean is ideal here.
 */
function getSnapshot(): boolean {
  return navigator.onLine;
}

/**
 * Server snapshot: used during SSR and the hydration pass.
 * We optimistically report "online" so the server markup matches the
 * first client render and React doesn't warn about a hydration mismatch.
 */
function getServerSnapshot(): boolean {
  return true;
}

/**
 * Tracks whether the browser is online or offline.
 *
 * @returns `true` when the browser reports it is online, `false` when offline.
 */
export function useOnlineStatus(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

export default useOnlineStatus;
```

