## Notes

**Why `useSyncExternalStore`?** It's the official API for reading from a mutable external source (the browser) in a way that's safe for concurrent rendering and hydration. It handles subscribing, unsubscribing, and tearing automatically. If you're on React 17 or earlier, use this equivalent instead:

```ts
import { useState, useEffect } from 'react';

export function useOnlineStatus(): boolean {
  const [isOnline, setIsOnline] = useState(
    () => typeof navigator === 'undefined' ? true : navigator.onLine
  );

  useEffect(() => {
    const goOnline = () => setIsOnline(true);
    const goOffline = () => setIsOnline(false);

    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);

    // Re-sync in case the state changed between render and effect.
    setIsOnline(navigator.onLine);

    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, []);

  return isOnline;
}
```

**Caveat:** `navigator.onLine` is a heuristic — it only tells you whether the device has *a* network connection, not whether the internet is actually reachable (a captive portal or a dead uplink still reports `online`). If you need true reachability, pair this hook with a heartbeat request to your own API:

```ts
export function useReachable(url = '/api/health') {
  const isOnline = useOnlineStatus();
  const [isReachable, setIsReachable] = useState(true);

  useEffect(() => {
    if (!isOnline) {
      setIsReachable(false);
      return;
    }

    let cancelled = false;

    const check = async () => {
      try {
        await fetch(url, { method: 'HEAD', cache: 'no-store' });
        if (!cancelled) setIsReachable(true);
      } catch {
        if (!cancelled) setIsReachable(false);
      }
    };

    check();
    const id = setInterval(check, 30_000);
    return () => {
      cancelled = true;
      clearInterval(id);
    };
  }, [isOnline, url]);

  return isReachable;
}
```

